["customText"] = "function()\n    \n    local s = C_CurrencyInfo.GetCurrencyInfo(2148)\n    local aoe = C_CurrencyInfo.GetCurrencyInfo(2149)\n    local stheal = C_CurrencyInfo.GetCurrencyInfo(2150)\n    local aoeheal = C_CurrencyInfo.GetCurrencyInfo(2151)\n    local crit = C_CurrencyInfo.GetCurrencyInfo(2152)\n    local haste = C_CurrencyInfo.GetCurrencyInfo(2153)\n    \n    local out = {\n        {'ST',s.quantity},\n        {'AOE',aoe.quantity},\n        {'ST HEAL',stheal.quantity},\n        {'AOE HEAL',aoeheal.quantity},\n        {'CRIT',crit.quantity},\n        {'HASTE',haste.quantity},\n    }\n    \n    local str = ''\n    for k,v in ipairs(out) do \n        local a,b = v[1],v[2]\n        str = str .. a .. ' - ' .. b .. '\\n'\n    end\n    return str\n    \nend\n\n\n\n",
