["actions"] = {
["start"] = {
["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region and region.state and region.state.show then\n    aura_env.regions[aura_env.cloneId] = region\n    WeakAuras.ScanEvents(\"HDH_WEEK\", region.state.event, 1)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local auraID, cloneID  = aura_env.id, aura_env.cloneId\nlocal region = WeakAuras.GetRegion(auraID, cloneID)\nif region then\n    WeakAuras.ScanEvents(\"HDH_WEEK\", region.state.event, 0)\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.regions = {}\n\naura_env.db = {\n    ----------------------------------------------------------------\n    -- Aiding the Accord\n    ----------------------------------------------------------------\n    [\"aidAccord\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Unterstützt das Abkommen\",\n            [\"enUS\"] = \"Aiding the Accord\",\n            [\"frFR\"] = \"Aider le Concordat\",\n            [\"koKR\"] = \"협의회 지원\",\n            [\"ruRU\"] = \"Помощь союзу\",\n            [\"zhCN\"] = \"援助联军\",\n            [\"zhTW\"] = \"支援協調者\",\n        },\n        \n        [\"questReq\"] = 1,\n        [\"questID\"] = { 72374, 70750, 72068, 72373, 75859, 75259, 72375, 75861, 75860, 77254, 77976, 78446, 78447, 78861 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Aurostor (Emerald Dream World Boss)\n    ----------------------------------------------------------------\n    [\"dreamWorldBoss\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"Aurostor\",\n            --[\"frFR\"] = \"\",\n            [\"koKR\"] = \"오로스토르\",\n            --[\"ruRU\"] = \"\",\n            [\"zhCN\"] = \"休眠者奥罗斯托\",\n            [\"zhTW\"] = \"『休眠者』奧羅司特\",\n        },\n        \n        [\"questReq\"] = 1,\n        [\"questID\"] = { 76367 },\n    },\n    \n    ----------------------------------------------------------------\n    -- The Big Dig: Traitor's Rest\n    ----------------------------------------------------------------\n    [\"bigDig\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"The Big Dig\",\n            [\"frFR\"] = \"La grande fouille\",\n            --[\"koKR\"] = \"\",\n            --[\"ruRU\"] = \"\",\n            [\"zhCN\"] = \"盛大发掘\",\n            [\"zhTW\"] = \"重大挖掘\",\n        },\n        \n        [\"questReq\"] = 1,\n        [\"questID\"] = { 79226 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Blooming Dreamseeds\n    ----------------------------------------------------------------\n    [\"dreamseeds\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"Blooming Dreamseeds\",\n            --[\"frFR\"] = \"\",\n            [\"koKR\"] = \"만발하는 꿈씨앗\",\n            --[\"ruRU\"] = \"\",\n            [\"zhCN\"] = \"盛放的梦境之种\",\n            [\"zhTW\"] = \"綻放的夢境種子\",\n        },\n        \n        [\"questReq\"] = 1,\n        [\"questID\"] = { 78821 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Community Feast\n    ----------------------------------------------------------------\n    [\"commFeast\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Gemeinschaftliches Festmahl\",\n            [\"enUS\"] = \"Community Feast\",\n            [\"frFR\"] = \"Festin tribal\",\n            [\"koKR\"] = \"공동체 잔치\",\n            [\"ruRU\"] = \"Большое пиршество\",\n            [\"zhCN\"] = \"社区盛宴\",\n            [\"zhTW\"] = \"集體盛宴\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 70893 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Eran'nda Supply Crates\n    ----------------------------------------------------------------\n    [\"eranndaCrates\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"Eran'nda Supply Crates\",\n            --[\"frFR\"] = \"\",\n            [\"koKR\"] = \"에란다 보급 상자\",\n            --[\"ruRU\"] = \"\",\n            [\"zhCN\"] = \"艾兰恩达的补给箱\",\n            [\"zhTW\"] = \"愛蘭妲的補給箱\",\n        },\n        [\"questReq\"] = 2,\n        [\"questID\"] = { 78427, 78428 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Fyrakk Assaults\n    ----------------------------------------------------------------\n    [\"fyrakk\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Angriffe von Fyrakk\",\n            [\"enUS\"] = \"Fyrakk Assault\",\n            [\"frFR\"] = \"Assauts de Fyrakka\",\n            [\"koKR\"] = \"피락의 습격\",\n            [\"ruRU\"] = \"Налеты Фиракка\",\n            [\"zhCN\"] = \"菲莱克突袭\",\n            [\"zhTW\"] = \"菲拉卡襲擊\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 75467 },\n        [\"poi\"] = { [7429] = 2023, [7432] = 2024 }\n    },\n    \n    ----------------------------------------------------------------\n    -- The Grand Hunt\n    ----------------------------------------------------------------\n    [\"grandHunt\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Die Große Jagd\",\n            [\"enUS\"] = \"The Grand Hunt\",\n            [\"frFR\"] = \"Grandes chasses\",\n            [\"koKR\"] = \"사냥의 제전\",\n            [\"ruRU\"] = \"Великая охота\",\n            [\"zhCN\"] = \"洪荒狩猎\",\n            [\"zhTW\"] = \"大狩獵\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 70906 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Keys of Loyalty\n    ----------------------------------------------------------------\n    [\"keyLoyalty\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Schlüssel der Loyalität\",\n            [\"enUS\"] = \"Keys of Loyalty\",\n            [\"frFR\"] = \"Clés de la loyauté\",\n            [\"koKR\"] = \"충성의 열쇠\",\n            [\"ruRU\"] = \"Ключи преданности\",\n            [\"zhCN\"] = \"忠诚之钥\",\n            [\"zhTW\"] = \"忠誠之鑰\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 66133, 66805 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Primal Storms\n    ----------------------------------------------------------------\n    [\"primalStorms\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Primalisten\",\n            [\"enUS\"] = \"Primalists\",\n            [\"frFR\"] = \"Tempêtes\",\n            [\"koKR\"] = \"원시술사\",\n            [\"ruRU\"] = \"Изначальные бури\",\n            [\"zhCN\"] = \"元素风暴\",\n            [\"zhTW\"] = \"洪荒使者\",\n        },\n        [\"questReq\"] = 4,\n        [\"questID\"] = { 70753, 70723, 70754, 70752 },\n        [\"questInfo\"] = {\n            [70753] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"A\",\n                    [\"koKR\"] = \"바\",\n                    [\"ruRU\"] = \"В\",\n                    [\"zhCN\"] = \"风\",\n                    [\"zhTW\"] = \"風\",\n                },\n            },\n            [70723] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"E\",\n                    [\"koKR\"] = \"땅\",\n                    [\"ruRU\"] = \"З\",\n                    [\"zhCN\"] = \"地\",\n                    [\"zhTW\"] = \"地\",\n                },\n            },\n            [70754] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"F\",\n                    [\"koKR\"] = \"불\",\n                    [\"ruRU\"] = \"О\",\n                    [\"zhCN\"] = \"火\",\n                    [\"zhTW\"] = \"火\",\n                },\n            },\n            [70752] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"W\",\n                    [\"koKR\"] = \"물\",\n                    [\"ruRU\"] = \"Л\",\n                    [\"zhCN\"] = \"水\",\n                    [\"zhTW\"] = \"水\",\n                },\n            },\n        },\n    },\n    \n    ----------------------------------------------------------------\n    -- Researchers Under Fire\n    ----------------------------------------------------------------\n    [\"underFire\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"Researchers Under Fire\",\n            --[\"frFR\"] = \"\",\n            [\"koKR\"] = \"불타고 있는 연구원들\",\n            [\"ruRU\"] = \"Исследователи под огнём\",\n            [\"zhCN\"] = \"研究员遇袭\",\n            [\"zhTW\"] = \"遭攻擊的研究員\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 75629, 75630, 75628, 75627 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Siege of Dragonbane Keep\n    ----------------------------------------------------------------\n    [\"siegeKeep\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Belagerung: Drachenfluchfestung\",\n            [\"enUS\"] = \"Siege of Dragonbane Keep\",\n            [\"frFR\"] = \"Donjon de Fléau des Dragons\",\n            [\"koKR\"] = \"성채 공성전\",\n            [\"ruRU\"] = \"Штурм Драконьей погибели\",\n            [\"zhCN\"] = \"围攻灭龙要塞\",\n            [\"zhTW\"] = \"攻打龍禍要塞\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 70866 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Sparks of Life\n    ----------------------------------------------------------------\n    [\"lifeSpark\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Funken des Lebens\",\n            [\"enUS\"] = \"Sparks of Life\",\n            [\"frFR\"] = \"Étincelles de vie\",\n            [\"koKR\"] = \"생명의 불꽃\",\n            [\"ruRU\"] = \"Искры жизни\",\n            [\"zhCN\"] = \"生命火花\",\n            [\"zhTW\"] = \"生命火花\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 72646, 72649, 72648, 72647, 74871, 75305, 78097 },\n    },\n    \n    ----------------------------------------------------------------\n    -- The Superbloom\n    ----------------------------------------------------------------\n    [\"superbloom\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"Superbloom\",\n            --[\"frFR\"] = \"\",\n            [\"koKR\"] = \"만개화\",\n            --[\"ruRU\"] = \"\",\n            [\"zhCN\"] = \"超然盛放\",\n            [\"zhTW\"] = \"繁盛綻放\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 78319 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Time Rifts / When Time Needs Mending\n    ----------------------------------------------------------------\n    [\"timeRift\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"When Time Needs Mending\",\n            --[\"frFR\"] = \"\",\n            --[\"koKR\"] = \"\",\n            --[\"ruRU\"] = \"\",\n            [\"zhCN\"] = \"时间也需要治愈\",\n            [\"zhTW\"] = \"當時間需要治療時\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 77236 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Trial of Elements\n    ----------------------------------------------------------------\n    [\"trialElements\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Prüfung der Elemente\",\n            [\"enUS\"] = \"Trial of Elements\",\n            [\"frFR\"] = \"Épreuve des éléments\",\n            [\"koKR\"] = \"원소의 시험\",\n            [\"ruRU\"] = \"Испытание стихий\",\n            [\"zhCN\"] = \"元素宝箱\",\n            [\"zhTW\"] = \"元素的試煉\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 71995 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Trial of Flood\n    ----------------------------------------------------------------\n    [\"trialFlood\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Prüfung der Flut\",\n            [\"enUS\"] = \"Trial of Flood\",\n            [\"frFR\"] = \"Épreuve du déluge\",\n            [\"koKR\"] = \"홍수의 시험\",\n            [\"ruRU\"] = \"Испытание прилива\",\n            [\"zhCN\"] = \"洪水宝箱\",\n            [\"zhTW\"] = \"洪流的試煉\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 71033 },\n    },\n    \n    ----------------------------------------------------------------\n    -- World Boss\n    ----------------------------------------------------------------\n    [\"worldBoss\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Weltboss\",\n            [\"enUS\"] = \"World Boss\",\n            [\"frFR\"] = \"Boss mondial\",\n            [\"koKR\"] = \"필드 보스\",\n            [\"ruRU\"] = \"Мировой босс\",\n            [\"zhCN\"] = \"世界首领\",\n            [\"zhTW\"] = \"世界首領\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 69927, 69928, 69929, 69930 },\n        [\"questInfo\"] = {\n            [69927] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"Bazual\",\n                    [\"koKR\"] = \"바주알\",\n                    [\"ruRU\"] = \"Базуал\",\n                    [\"zhCN\"] = \"巴祖阿尔\",\n                    [\"zhTW\"] = \"巴組爾\",\n                },\n            },\n            [69928] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"Liskanoth\",\n                    [\"koKR\"] = \"리스카노스\",\n                    [\"ruRU\"] = \"Лисканот\",\n                    [\"zhCN\"] = \"利斯卡诺\",\n                    [\"zhTW\"] = \"利斯卡諾\",\n                },\n            },\n            [69929] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"Strunraan\",\n                    [\"koKR\"] = \"스트루나란\",\n                    [\"ruRU\"] = \"Струнраан\",\n                    [\"zhCN\"] = \"斯图恩兰\",\n                    [\"zhTW\"] = \"史珠那朗\",\n                },\n            },\n            [69930] = {\n                [\"name\"] = {\n                    [\"enUS\"] = \"Basrikron\",\n                    [\"koKR\"] = \"바스리크론\",\n                    [\"ruRU\"] = \"Базрикрон\",\n                    [\"zhCN\"] = \"巴斯律孔\",\n                    [\"zhTW\"] = \"巴斯里隆\",\n                },\n            },\n        }\n    },\n    \n    ----------------------------------------------------------------\n    -- The Zaqali Elders (Zaralek World Boss)\n    ----------------------------------------------------------------\n    [\"zaqaliElders\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Älteste der Zaqali\",\n            [\"enUS\"] = \"Zaqali Elders\",\n            [\"frFR\"] = \"Anciens zaqalis\",\n            [\"koKR\"] = \"자칼리 장로\",\n            [\"ruRU\"] = \"Старейшины закали\",\n            [\"zhCN\"] = \"扎卡利长老\",\n            [\"zhTW\"] = \"扎卡利長老\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 74892 },\n    },\n    \n    ----------------------------------------------------------------\n    -- A Worthy Ally\n    ----------------------------------------------------------------\n    [\"worthyAlly\"] = {\n        [\"name\"] = {\n            [\"deDE\"] = \"Würdiger Verbündeter\",\n            [\"enUS\"] = \"A Worthy Ally\",\n            [\"frFR\"] = \"Précieuse alliance\",\n            [\"koKR\"] = \"가치 있는 동맹\",\n            [\"ruRU\"] = \"Достойный союзник\",\n            [\"zhCN\"] = \"强大的盟友\",\n            [\"zhTW\"] = \"寶貴的盟友\",\n        },\n        [\"questReq\"] = 1,\n        [\"questID\"] = { 78444 },\n    },\n    \n    ----------------------------------------------------------------\n    -- Zaralek Caverns Events\n    ----------------------------------------------------------------\n    [\"zaralekEvents\"] = {\n        [\"name\"] = {\n            --[\"deDE\"] = \"\",\n            [\"enUS\"] = \"Zaralek Events\",\n            --[\"frFR\"] = \"\",\n            [\"koKR\"] = \"자랄레크 미니퀘\",\n            [\"ruRU\"] = \"События Заралек\",\n            [\"zhCN\"] = \"查拉雷克事件\",\n            [\"zhTW\"] = \"扎拉萊克事件\",\n        },\n        [\"questReq\"] = 18,\n        [\"questID\"] = { 74352, 75156, 75222, 75370, 75441, 75450, 75451, 75454, 75455, 75461, 75471, 75478, 75494, 75611, 75612, 75624, 75664, 75705 },\n        [\"questInfo\"] = {\n            [74352] = true, [75156] = true, [75222] = true, [75370] = true, [75441] = true,\n            [75450] = true, [75451] = true, [75454] = true, [75455] = true, [75461] = true,\n            [75471] = true, [75478] = true, [75494] = true, [75611] = true, [75612] = true,\n            [75624] = true, [75664] = true, [75705] = true,\n        }\n    }\n}\n\n\n\n",
