["events"] = "START,CHAT_MSG_LOOT,BAG_UPDATE,QUEST_COMPLETE,QUEST_TURNED_IN,UNIT_INVENTORY_CHANGED,ITEM_COUNT_CHANGED",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates)\n    -- build vars\n    local cfg  = aura_env.config.weekly\n    \n    -- is this thing even on?\n    if not cfg.weeklyEnable then return end\n    \n    -- start checking weekly events\n    for event, v in pairs(aura_env.db) do\n        local lang = GetLocale()\n        local name = v.name[lang] or v.name[\"enUS\"]\n        local questDB = v.questID\n        local required = v.questReq\n        local info = \"\"\n        local tooltip = \"Incomplete Events: |n|n|cFFFFFFFF\"\n        \n        -- should we care about this event?\n        if cfg[event] then\n            \n            -- start checking quest progress\n            local completed = 0\n            for _, questID in pairs(questDB) do\n                -- done?\n                local questComplete = C_QuestLog.IsQuestFlaggedCompleted(questID)\n                if questComplete then completed = completed + 1 end\n                \n                -- info: eran'nda supply crates\n                if event == \"eranndaCrates\" then\n                    local c = questComplete and \"|cFFaad371\" or \"\"\n                    info = c .. completed .. \"/\" .. #questDB .. \"|r\"\n                end\n                \n                -- info: fyakk assaults\n                if event == \"fyrakk\" then\n                    for _, poi in pairs(C_AreaPoiInfo.GetAreaPOIForMap(1978)) do\n                        if v.poi[poi] then\n                            info = C_Map.GetMapInfo(v.poi[poi]).name\n                        end\n                    end\n                end\n                \n                -- itorate through event information\n                if v.questInfo then\n                    for infoID, x in pairs(v.questInfo) do\n                        if questID == infoID then\n                            \n                            -- info: primalists\n                            if event == \"primalStorms\" then\n                                local c = questComplete and \"|cFFaad371\" or \"\"\n                                local out = x.name[lang] or x.name[\"enUS\"]\n                                if cfg.hideComplete and questComplete then info = info\n                                else info = info == \"\" and c .. out .. \"|r\" or info .. \" / \" .. c .. out .. \"|r\" end\n                            end\n                            \n                            -- info: world boss\n                            if event == \"worldBoss\" then\n                                if C_TaskQuest.IsActive(questID) or questComplete then\n                                    local c = questComplete and \"|cFFaad371\" or \"\"\n                                    local out = x.name[lang] or x.name[\"enUS\"]\n                                    info = c .. out .. \"|r\"\n                                end\n                            end\n                            \n                            -- info: zaralek events\n                            if event == \"zaralekEvents\" then\n                                local c = questComplete and \"|cFFaad371\" or \"\"\n                                local out = completed .. \"/\" .. required\n                                local title = C_QuestLog.GetTitleForQuestID(questID) or \"\"\n                                info = c .. out .. \"|r\"\n                                if not questComplete then tooltip = tooltip .. title .. \"|n\" end\n                            end\n                            \n                        end\n                    end\n                end\n            end\n            local IsComplete = completed >= required and true or false\n            \n            -- update the bar?\n            if allstates[event] then\n                if cfg.hideComplete and IsComplete then\n                    allstates[event] = { changed = true, show = false }\n                elseif not cfg.hideComplete and IsComplete then\n                    allstates[event] = { changed = true, info = info }\n                end\n            end\n            \n            \n            -- build the bars\n            if completed >= required and not cfg.hideComplete or completed < required then\n                allstates[event] = {\n                    autoHide     = true,\n                    changed      = true,\n                    event        = event,\n                    index        = name,\n                    info         = info,\n                    IsComplete   = IsComplete,\n                    name         = name,\n                    progressType = \"static\",\n                    show         = true,\n                    tooltip      = tooltip or \"\",\n                    total        = 100,\n                    value        = 0,\n                }\n            end\n        end  \n    end\n    \n    return true   \nend",
