["customText"] = "function()\n    local lines = {}\n    table.insert(lines, C_Spell.GetSpellInfo(aura_env.config.targetSpell).name)\n    for _, entry in ipairs(aura_env.debuffTable) do\n        if entry.applied then\n            local m = math.floor(entry.time / 60)\n            local s = math.floor(entry.time % 60)\n            table.insert(lines, string.format(\"%02d:%02d - %s\", m, s, entry.name))\n        end\n    end\n    return table.concat(lines, \"\\n\")\nend",
