["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{expirationTime = true}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"BigWigs_StartBar\" and ... then\n        local bar = ...\n        if bar then\n            local b = WeakAuras.GetBigWigsTimerById(bar)\n            if b then\n                local duration = b.duration\n                local expirationTime = b.expirationTime\n                local spellID = b.spellId\n                local count = aura_env.counter\n                if spellID == \"381602\" then\n                    allstates[spellID] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        duration = duration,\n                        expirationTime = expirationTime,\n                        text = count % 4 == 1 and \"Left\" or count % 4 == 2 and \"Back\" or count % 4 == 3 and \"Right\" or count % 4 == 0 and \"Front\",\n                        autoHide = true,\n                    }   \n                    return true \n                end\n            end\n        end\n        \n    elseif event == \"BigWigs_StopBar\" and ... then\n        local bar = ...\n        if bar then\n            local b = WeakAuras.GetBigWigsTimerById(bar)\n            if b then\n                local spellID = b.spellId\n                if spellID == \"381862\" then\n                    local state = allstates[spellID] \n                    if state then\n                        state.show = false\n                        state.changed = true\n                        return true\n                    end\n                end\n            end\n        end\n        \n    elseif event == \"UNIT_SPELLCAST_START\" then\n        local _, _, spellID = ...\n        if spellID == 381602 or spellID == 381605 then\n            aura_env.counter = aura_env.counter + 1\n        end\n        \n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.counter = 1\n    end\nend",
