["preferToUpdate"] = false,
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["cooldownEdge"] = false,
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "custom",
["events"] = "PLAYER_REGEN_ENABLED, PLAYER_REGEN_DISABLED, UNIT_COMBAT, UPDATE_MOUSEOVER_UNIT, CLEU:UNIT_DIED, MODIFIER_STATE_CHANGED, NAME_PLATE_UNIT_ADDED,  READY_CHECK, CHALLENGE_MODE_START",
["spellIds"] = {
},
["subeventPrefix"] = "SPELL",
["names"] = {
},
["custom_type"] = "event",
["custom"] = "function(event, ...)\n    if (aura_env.config.settingsGroup.requireLead and not UnitIsGroupLeader(\"player\")) then return end \n    -- doesn't do marking if not player lead and \"not lead\" is toggled in custom options\n    \n    ---------------------------------------------------------------------------------------\n    if event == \"PLAYER_REGEN_ENABLED\" then\n        aura_env.marks = {}\n        aura_env.assigned = {}\n        aura_env.checkPremarkedMobs()\n        aura_env.checkPremarkedPlayers()\n    end\n    if event == \"PLAYER_REGEN_DISABLED\" then\n        aura_env.checkPremarkedMobs()\n        aura_env.checkPremarkedPlayers()\n    end\n    \n    \n    ---------------------------------------------------------------------------------------\n    --mouseover functionality\n    if (event == \"UPDATE_MOUSEOVER_UNIT\" or event == \"MODIFIER_STATE_CHANGED\") and aura_env.config.settingsGroup.mouseover then\n        if (aura_env.config.settingsGroup.ShiftDown and not IsShiftKeyDown()) then return end\n        local guid = UnitGUID(\"mouseover\")\n        if not guid then return end\n        local unitid = select(6, strsplit(\"-\", guid))\n        if not aura_env.isUnitValid(\"mouseover\") then return end\n        aura_env.checkPremarkedPlayers()\n        aura_env.checkPremarkedMobs()\n        aura_env.markUnit(\"mouseover\", aura_env.getOrder(unitid))\n    end\n    \n    \n    ---------------------------------------------------------------------------------------\n    --combat marking\n    if event == \"UNIT_COMBAT\" and aura_env.config.settingsGroup.regularMarking then\n        local unit = select(1, ...)\n        local guid = UnitGUID(unit)\n        if not guid then return end\n        local unitid = select(6, strsplit(\"-\", guid))\n        if not aura_env.isUnitValid(unit) or not UnitAffectingCombat(unit) or not UnitCanAttack(\"player\", unit) then return end\n        aura_env.checkPremarkedPlayers()\n        aura_env.checkPremarkedMobs()\n        aura_env.markUnit(unit, aura_env.getOrder(unitid))\n    end \n    \n    ---------------------------------------------------------------------------------------\n    --nameplate marking\n    if event == \"NAME_PLATE_UNIT_ADDED\" then \n        local unit = select(1, ...)\n        if not aura_env.isUnitValidNameplate(unit) then return end\n        aura_env.checkPremarkedPlayers()\n        aura_env.checkPremarkedMobs()\n        local unitid = select(6, strsplit(\"-\",UnitGUID(unit)))\n        aura_env.markUnit(unit, aura_env.getOrder(unitid, true))\n    end\n    \n    \n    ---------------------------------------------------------------------------------------\n    --Frees up marks when mobs die\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" and (select(2,...) == \"UNIT_DIED\" or select(2,...) == \"UNIT_DESTROYED\") then\n        local guid = select(8,...)     \n        if guid and(aura_env.marks[guid]) then\n            local type = select(1, strsplit(\"-\", guid)) \n            \n            if string.lower(type)~=\"player\" then\n                aura_env.assigned[aura_env.marks[guid]] = false\n                aura_env.marks[guid] = nil\n            end\n        end    \n    end\n    \n    \n    ---------------------------------------------------------------------------------------\n    if event == \"READY_CHECK\" or event == \"CHALLENGE_MODE_START\" then        \n        aura_env.setTankMark()\n        aura_env.setHealMark()\n    end\nend\n\n\n",
["debuffType"] = "HELPFUL",
},
