["init"] = {
["custom"] = "--[[\nReport bugs on discord to anDe#0001 on discord or on wago.\n\nNot finding a mob you want marked?\nsimply add a row like this:\n[\"42069\"] = true,\nwhere \"42069\" is the NPC id. MAKE SURE YOU INCLUDE THE \"\"\nDon't bother with config stuff. that's just for custom config tab\nAlso, thanks for reading this comment. Not a lot of people bother. Hope you're having a swell day :)\n\n1=star, 2=circle, 3=diamond, 4=triangle, 5=moon, 6=square, 7=cross, 8=skull\n\n]]\n\naura_env.orderList = {\n    [\"defaultOrder\"] = {1,2,3,4,5,6,7,8},\n    [\"caster1\"] = {4,3,2,1,5,6,7,8},\n    [\"caster2\"] = {6,7,1,3,5,4,2,2},\n    [\"nonCaster1\"] = {5,7,6,8,4,3,2,1},\n    [\"nonCaster2\"] = {6,8,5,7,4,3,2,1},\n    [\"prio\"] = {8,7,5,4,3,2},\n    [\"incorp\"] = {6,7,5,4,3,2},\n}\n\n\n\naura_env.mobList = {\n    --Affixes\n    [\"204560\"] = aura_env.config.npc204560 and \"incorp\", --Incorporeal\n    \n    \n    --Atal'dazar\n    [\"127879\"] = aura_env.config.npc127879, --Shieldbearer of Zul\n    [\"122969\"] = aura_env.config.npc122969 and \"caster1\", --Zanchuli Witch-Doctor\n    [\"125977\"] = aura_env.config.npc125977, --Reanimation Totem boss fight\n    [\"128434\"] = aura_env.config.npc128434 and \"caster1\", --Feasting Skyscreamer\n    [\"122972\"] = aura_env.config.npc122972 and \"caster1\", --Dazar'ai Auger\n    [\"122971\"] = aura_env.config.npc122971, --Dazar'ai Juggernaut\n    [\"132126\"] = aura_env.config.npc132126, --Gilded Priestess\n    [\"122984\"] = aura_env.config.npc122984, --Dazar'ai Colossus\n    [\"122973\"] = aura_env.config.npc122973, --Dazar'ai Confessor\n    [\"129553\"] = aura_env.config.npc129553, --Dinomancer Kisho\n    \n    \n    \n    --Everbloom\n    [\"81819\"] = aura_env.config.npc81819, --everbloom-naturalist\n    [\"81820\"] = aura_env.config.npc81820, --everbloom-mender\n    [\"81985\"] = aura_env.config.npc81985, --everbloom-tender !NotDefault\n    [\"84990\"] = aura_env.config.npc84990, --addled-arcanomancer\n    [\"84989\"] = aura_env.config.npc84989, --infested-icecaller\n    [\"84957\"] = aura_env.config.npc84957, --putrid-pyromancer\n    [\"83893\"] = aura_env.config.npc83893, --Earthshaper Telu\n    [\"83892\"] = aura_env.config.npc83892, --Life Warden Gola\n    \n    --Black Rook Hold\n    [\"98370\"] = aura_env.config.npc98370, --ghostly-councilor\n    [\"98521\"] = aura_env.config.npc98521, --lord-etheldrin-ravencrest\n    [\"98280\"] = aura_env.config.npc98280, --risen-arcanist\n    [\"100486\"] = aura_env.config.npc100486, --risen-arcanist(boss)\n    [\"98813\"] = aura_env.config.npc98813, --bloodscent-felhound\n    [\"102788\"] = aura_env.config.npc102788, --felspite-dominator\n    [\"98691\"] = aura_env.config.npc98691, --risen-scout\n    [\"98810\"] = aura_env.config.npc98810, --wrathguard-bladelord\n    \n    --Throne of tides\n    [\"41096\"] = aura_env.config.oracle, --nazjar-oracle\n    [\"41139\"] = aura_env.config.oracle, --nazjar-oracle\n    [\"44404\"] = aura_env.config.npc44404, --nazjar-frost-witch\n    [\"214209\"] = aura_env.config.npc214209, --nazjar-tempest-witch(boss)\n    [\"40634\"] = aura_env.config.npc40634, --nazjar-tempest-witch\n    [\"212775\"] = aura_env.config.npc212775, --faceless-seer\n    [\"40943\"] = aura_env.config.npc40943, --gilgoblin-aquamage\n    [\"213806\"] = aura_env.config.npc213806, --splotch (last boss caster mob)\n    [\"40925\"] = aura_env.config.npc40925, --Tainted Sentry\n    \n    --doti\n    [\"205384\"] = aura_env.config.npc205384, --infinite-chronoweaver\n    [\"205408\"] = aura_env.config.npc205408, --infinite-timeslicer (stun)\n    [\"206066\"] = aura_env.config.npc206066, --timestream-leech (no mark default)\n    [\"206064\"] = aura_env.config.npc206064, --coalesced-moment\n    [\"205691\"] = aura_env.config.npc205691, --iridikrons-creation(boss)\n    [\"204918\"] = aura_env.config.npc204918, --iridikrons-creation\n    [\"201223\"] = aura_env.config.npc201223, --infinite-twilight-magus\n    [\"205158\"] = aura_env.config.npc205158, --spurlok-timesworn-sentinel\n    [\"199748\"] = aura_env.config.npc199748, --timeline-marauder\n    [\"206074\"] = aura_env.config.npc206074, --pendule\n    [\"208165\"] = aura_env.config.raiderKnight, --alliance-knight\n    [\"207969\"] = aura_env.config.raiderKnight, --horde-raider\n    [\"204206\"] = aura_env.config.farseerPaladin, --horde-farseer\n    [\"208193\"] = aura_env.config.farseerPaladin, --paladin-of-the-silver-hand\n    [\"205727\"] = aura_env.config.npc205727, --time-lost-rocketeer\n    [\"205337\"] = aura_env.config.npc205337, --infinite-timebender\n    [\"206140\"] = aura_env.config.npc206140, --Coalesced Time\n    [\"205363\"] = aura_env.config.npc205363, --Time Lost Waveshaper\n    [\"205212\"] = aura_env.config.npc205212, --Infinite Keeper(last boss)\n    \n    --dht\n    [\"95769\"] = aura_env.config.npc95769, --mindshattered-screecher\n    [\"95771\"] = aura_env.config.npc95771, --dreadsoul-ruiner\n    [\"95766\"] = aura_env.config.npc95766, --crazed-razorbeak(disabled default)\n    [\"101991\"] = aura_env.config.npc101991, --nightmare-dweller\n    [\"100527\"] = aura_env.config.npc100527, --dreadfire-imp\n    [\"99366\"] = aura_env.config.npc99366, --taintheart-summoner\n    \n    --Waycrest Manor \n    [\"131850\"] = aura_env.config.npc131850 and \"caster1\", --Maddened Survivalist\n    [\"134024\"] = aura_env.config.npc134024 and \"caster1\", --Devouring Maggot\n    [\"142587\"] = aura_env.config.npc134024 and \"caster1\", --Devouring Maggot spawn\n    [\"131677\"] = aura_env.config.npc131677 and \"caster1\", --Heartsbane Runeweaver\n    [\"131586\"] = aura_env.config.npc131586, --Banquet Steward\n    [\"131666\"] = aura_env.config.npc131666 and \"caster2\", --Coven Thornshaper\n    [\"131858\"] = aura_env.config.npc131858, --Thornguard\n    [\"131685\"] = aura_env.config.npc131685 and \"caster2\", --Runic Disciple \n    [\"131587\"] = aura_env.config.npc131587 and \"caster1\", --Bewitched Captain\n    [\"131670\"] = aura_env.config.npc131670 and \"caster2\", --Heartsbane Vinetwister\n    [\"131812\"] = aura_env.config.npc131812 and \"caster2\", --Heartsbane Soulcharmer\n    [\"135474\"] = aura_env.config.npc135474 and \"caster1\", --Thistle Acolyte\n    [\"135365\"] = aura_env.config.npc135365 and \"caster1\", --Matron Alma\n    [\"131819\"] = aura_env.config.npc131819 and \"caster1\", --Coven Diviner\n    [\"131818\"] = aura_env.config.npc131818 and \"caster1\", --Marked Sister\n    [\"135552\"] = aura_env.config.npc135552, --Deathtouched slaver (boss)\n}\n\n--includes mobs that should be marked by nameplate appearing. You can either add mobs uniquely OR add both in the table above and here\naura_env.mobListNameplate = {\n    --Atal'dazar\n    [\"125977\"] = aura_env.config.npc125977, --Reanimation Totem boss fight    \n}\n\n\n--DO NOT TOUCH\n\naura_env.marks = {} --[guid]= markerIndex\naura_env.assigned = {} --[markerIndex] = boolean\n\n\naura_env.getOrder = function(unitId, isNameplate) \n    local orderName\n    if (isNameplate) then\n        orderName = aura_env.mobListNameplate[unitId]\n    else\n        orderName = aura_env.mobList[unitId]\n    end\n    return  aura_env.orderList[orderName] or aura_env.orderList[\"defaultOrder\"]\nend\n\n--marks the tank with the mark from config IF they don't have a mark already\naura_env.setTankMark = function()\n    if aura_env.config.settingsGroup.markTank == 1 then return end\n    for unit in WA_IterateGroupMembers() do\n        if UnitGroupRolesAssigned(unit) == \"TANK\" and not GetRaidTargetIndex(unit) and not aura_env.assigned[aura_env.config.settingsGroup.markTank - 1] then \n            SetRaidTarget(unit, aura_env.config.settingsGroup.markTank - 1) \n            return\n        end\n    end\nend\naura_env.setTankMark()\n\n\n--marks the Healer with the mark from config IF they don't have a mark already\naura_env.setHealMark = function()\n    if aura_env.config.settingsGroup.markHeal == 1 then return end\n    for unit in WA_IterateGroupMembers() do\n        if UnitGroupRolesAssigned(unit) == \"HEALER\" and not GetRaidTargetIndex(unit) and not aura_env.assigned[aura_env.config.settingsGroup.markTank - 1] then \n            SetRaidTarget(unit, aura_env.config.settingsGroup.markHeal - 1) \n            return\n        end\n    end\nend\naura_env.setHealMark()\n\n\n--checks marks on players in party. DOES NOT empty the list of marked mobs or marks in use\naura_env.checkPremarkedPlayers = function ()\n    for unit in WA_IterateGroupMembers() do\n        if GetRaidTargetIndex(unit) then\n            aura_env.assigned[GetRaidTargetIndex(unit)] = true\n            aura_env.marks[unit] = GetRaidTargetIndex(unit)\n        end\n    end\nend\n\n\n--checks nameplates and boss frames on screen and adds them to the tracked list if not already in it. DOES NOT empty the list of marked mobs or marks in use\naura_env.checkPremarkedMobs = function ()\n    for i = 1,40 do\n        local unit = \"nameplate\"..i\n        if UnitExists(unit) and GetRaidTargetIndex(unit) and not UnitPlayerControlled(unit) then\n            aura_env.assigned[GetRaidTargetIndex(unit)] = true\n            aura_env.marks[UnitGUID(unit)] = GetRaidTargetIndex(unit)\n        end\n    end\n    for i = 1,6 do\n        local unit = \"boss\"..i\n        if UnitExists(unit) and GetRaidTargetIndex(unit) and not UnitPlayerControlled(unit) then\n            aura_env.assigned[GetRaidTargetIndex(unit)] = true\n            aura_env.marks[UnitGUID(unit)] = GetRaidTargetIndex(unit) \n        end\n    end\nend\n\n--checks if the unit should be marked\naura_env.isUnitValid = function (unit)\n    if unit == \"player\" then return end\n    local guid = UnitGUID(unit)\n    \n    if not guid then return end\n    local unitid = select(6, strsplit(\"-\", guid))\n    if (unitid == \"134024\" or unitid==\"142587\") and not WA_GetUnitBuff(unit, \"Parasitic\") then\n        return\n    end\n    return UnitExists(unit) and not GetRaidTargetIndex(unit) and aura_env.mobList[unitid] and not UnitIsDead(unit)\nend\n\n--special case for nameplate marking, but same as the function above. Should merge them in the future\naura_env.isUnitValidNameplate = function (unit)\n    if unit == \"player\" then return end\n    local guid = UnitGUID(unit)\n    if not guid then return end\n    local unitid = select(6, strsplit(\"-\", guid))    \n    return UnitExists(unit) and not GetRaidTargetIndex(unit) and aura_env.mobListNameplate[unitid] and not UnitIsDead(unit)\nend\n\n--takes in a unit and the order to mark it with. function checks the marks in the order to find the first availible marker from that order\naura_env.markUnit = function (unit, order)\n    local guid = UnitGUID(unit)\n    \n    --special case: if the unit has previously had a marker that has been removed\n    if aura_env.marks[guid] and not GetRaidTargetIndex(unit) then        \n        aura_env.checkPremarkedMobs()\n        aura_env.checkPremarkedPlayers()\n        \n        --if the same marker is still is available\n        if aura_env.marks[guid] and aura_env.assigned[aura_env.marks[guid]] and not aura_env.isAnotherGuidAssignedToMark(guid, aura_env.marks[guid]) then\n            aura_env.assigned[aura_env.marks[guid]] = true\n            SetRaidTarget(unit,aura_env.marks[guid])\n            return\n        end\n        --wasn't able to re-apply the same marker due to the marker being in use by another mob. Normal case kicks in and we assign a new marker\n    end\n    \n    --normal case:\n    for i=1, #order do\n        if not aura_env.assigned[order[i]] and aura_env.config.settingsGroup.enabledMarks[order[i]] then\n            \n            aura_env.marks[guid] = order[i]\n            aura_env.assigned[order[i]] = true\n            SetRaidTarget(unit, order[i])\n            return\n        end\n    end\nend    \n\n\n\naura_env.isAnotherGuidAssignedToMark = function (guid, markIndex)\n    for k,v in pairs(aura_env.marks) do \n        if k ~= guid and markIndex == v then \n            return true \n        end\n    end\n    \nend\n\n\n\n\n--megawatt sync NYI\n\naura_env.specializationName = {\n    [250] = \"TANK\",\n    [581] = \"TANK\",\n    [104] = \"TANK\",\n    [268] = \"TANK\",\n    [66] = \"TANK\",\n    [73] = \"TANK\",\n    [105] = \"HEALER\",\n    [270] = \"HEALER\",\n    [65] = \"HEALER\",\n    [256] = \"HEALER\",\n    [257] = \"HEALER\",\n    [264] = \"HEALER\",\n    [251] = \"DAMAGER\",\n    [252] = \"DAMAGER\",\n    [577] = \"DAMAGER\",\n    [102] = \"DAMAGER\",\n    [103] = \"DAMAGER\",\n    [253] = \"DAMAGER\",\n    [254] = \"DAMAGER\",\n    [255] = \"DAMAGER\",\n    [62] = \"DAMAGER\",\n    [63] = \"DAMAGER\",\n    [64] = \"DAMAGER\",\n    [269] = \"DAMAGER\",\n    [70] = \"DAMAGER\",\n    [258] = \"DAMAGER\",\n    [259] = \"DAMAGER\",\n    [260] = \"DAMAGER\",\n    [261] = \"DAMAGER\",\n    [262] = \"DAMAGER\",\n    [263] = \"DAMAGER\",\n    [265] = \"DAMAGER\",\n    [266] = \"DAMAGER\",\n    [267] = \"DAMAGER\",\n    [71] = \"DAMAGER\",\n    [72] = \"DAMAGER\",\n}\naura_env.GetChatType = function()\n    -- Returns a STRING with the Chat Type for 'SendAddonMessage'\n    return IsInGroup(LE_PARTY_CATEGORY_INSTANCE) and \"INSTANCE_CHAT\" or \"PARTY\"\nend\n\n--sends info regarding marking preferences to megawatt's WA\naura_env.sendPlayerInfo = function()\n    -- ROLE - MarkMobs - MarkPlayers - LEADER - TankIcon - HealerIcon - Decider\n    local role = UnitGroupRolesAssigned(\"player\") == \"NONE\" and aura_env.specializationName[GetSpecializationInfo(GetSpecialization())] or UnitGroupRolesAssigned(\"player\")\n    local leader, score = UnitIsGroupLeader(\"player\"), C_PlayerInfo.GetPlayerMythicPlusRatingSummary(\"player\").currentSeasonScore\n    local markMobs = true\n    local markPlayers = aura_env.config.settingsGroup.markTank > 1\n    local msg = string.format(\"%s:%s:%s:%s:%s:%s\", role, tostring(markMobs), tostring(markPlayers), tostring(leader), score, 2) -- Sending 2 as build to differenciate my WA\n    return C_ChatInfo.SendAddonMessage(\"MYTHICAUTOMARK\", \"WHO_MARK^\"..msg, aura_env.GetChatType())\nend\naura_env.sendPlayerInfo()\n\n\n\n\n\n\n\n\n\n",
["do_custom"] = true,
},
