["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_AURA_APPLIED\"\n        and spellID == 382630 then\n            local aura_env = aura_env\n            if aura_env.timer then\n                aura_env.timer:Cancel()\n            end\n            aura_env.timer = C_Timer.NewTimer(10, function() WeakAuras.ScanEvents(\"CAUSESE_ORBS\", \"nilcheck\") end)\n            allstates[\"causese_orbs\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 10,\n                expirationTime = 10 + GetTime(),\n            }\n            return true\n        elseif subEvent == \"SPELL_AURA_REMOVED\"\n        and spellID == 382630 then\n            if aura_env.timer then\n                aura_env.timer:Cancel()\n            end\n            local state = allstates[\"causese_orbs\"]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    elseif event == \"CAUSESE_ORBS\" and ... then\n        if aura_env.timer then\n            aura_env.timer:Cancel()\n        end\n        \n        aura_env.timer = C_Timer.NewTimer(10, function() WeakAuras.ScanEvents(\"CAUSESE_ORBS\", \"nilcheck\") end)\n        PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\Orb.ogg\", \"MASTER\")\n        \n        allstates[\"causese_orbs\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 10,\n            expirationTime = 10 + GetTime(),\n        }\n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        if aura_env.timer then\n            aura_env.timer:Cancel()\n        end\n        return true\n    end\nend",
