["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_AURA_APPLIED\"\n        and spellID == 374350 then\n            local unit = UnitTokenFromGUID(destGUID)\n            if unit then\n                local _,_, count,_,duration,expirationTime = WA_GetUnitDebuff(unit, 389011)\n                allstates[destGUID] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 6,\n                    expirationTime = 6 + GetTime(),\n                    unit = unit,\n                    count = count or 0,\n                    autoHide = true,\n                }\n                return true\n            end\n        elseif subEvent == \"SPELL_AURA_REMOVED\"\n        and spellID == 374350 then\n            local state = allstates[destGUID]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
