["cooldownSwipe"] = true,
["customTextUpdate"] = "event",
["cooldownEdge"] = false,
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "---- Constants ----\n\nlocal aura = aura_env\nlocal config = aura.config\nlocal batch = config.batch\nlocal combine = config.combine\nlocal hasted = config.hasted\nlocal clump = config.clump\nlocal longTyrantDur = config.adv.tyrext\nlocal shortTyrantDur = longTyrantDur / 4\nlocal maximumDuration = 40\nlocal leeway = config.adv.leeway\nlocal persistent = config.persistent\nlocal topleft = config.topleft\nlocal limit = config.limit\nlocal IMP_EVENT = \"WILD_IMP_CHECK\"\nlocal impCasts = (UnitLevel(\"player\") >= 56 and 6) or 5\nlocal playerGuid = UnitGUID(\"player\")\n\nlocal colourTable\nif config.colourenabled then\n    local r1, g1, b1, a1 = unpack(config.startcolour)\n    local r2, g2, b2, a2 = unpack(config.endcolour)\n    colourTable = { }\n    for i = 1, 9 do\n        local p = 1 - min((i - 1) / 9, 1)\n        colourTable[i] = { WeakAuras.GetHSVTransition(1 - (p * p * p),\n                r1, g1, b1, a1,\n                r2, g2, b2, a2\n        ) }\n    end\nend\n\n---- Variables ----\n\nlocal impTable = {}\nlocal tyrants = {}\nlocal actualImps = 0\nlocal longTyrant\nlocal recheckHandle = nil\n\n---- Functions ----\n\nlocal callback = function()\n    if recheckHandle then\n        recheckHandle:Cancel()\n        recheckHandle = nil\n    end\n    WeakAuras.ScanEvents(IMP_EVENT, nil)\nend\n\nlocal impSort = function(a, b)\n    return a.curEnd < b.curEnd\nend\n\nlocal groupSort = function(a,b)\n    return #a.imps > #b.imps\nend\n\n-- Event(s):\n--   WILD_IMP_CHECK, \n--   CLEU:SPELL_SUMMON:SPELL_CAST_SUCCESS:SPELL_CAST_START,\n--   TRIGGER:2\naura.trigger1 = function(allstates, event, _, msg, _, sGuid, _,_,_, dGuid, _,_,_, spellId)\n    local check, update\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        if sGuid == playerGuid then\n            if msg == \"SPELL_SUMMON\" then\n                if spellId == 265187 then\n                    \n                    -- Mark Tyrant as active - Imps are extended separately on empowerment.\n                    \n                    local duration = (longTyrant and longTyrantDur or shortTyrantDur)\n                    local timestamp = GetTime()\n                    \n                    tyrants[timestamp + duration] = true\n                    longTyrant = false\n                    \n                    for _, imp in pairs(impTable) do\n                        imp.ext = max(timestamp, imp.ext) + duration\n                        imp.curEnd = imp.curEnd + duration\n                        imp.maxEnd = imp.maxEnd + duration\n                    end\n                    \n                    update = true\n                    \n                elseif spellId == 104317 or spellId == 279910 then\n                    \n                    -- Spawn Imp with default traits, extend if during Tyrant.\n                    \n                    local lifespan, extension = (spellId == 279910) and 20.2 or maximumDuration, 0\n                    local timestamp = GetTime()\n                    for tyrant, _ in pairs(tyrants) do\n                        if timestamp < tyrant then\n                            extension = extension + (tyrant - timestamp)\n                        else\n                            tyrants[tyrant] = nil\n                        end\n                    end\n                    \n                    local expiration = timestamp + lifespan + extension\n                    \n                    impTable[dGuid] = {\n                        guid = dGuid,\n                        casts = impCasts,\n                        act = timestamp, \n                        maxEnd = expiration,\n                        ext = timestamp + extension,\n                        curEnd = expiration,\n                        show = false\n                    }\n                    \n                    update = true\n                    check = true\n                end\n            elseif msg == \"SPELL_CAST_SUCCESS\" and spellId == 265187 then\n                longTyrant = true\n            end\n        elseif spellId == 104318 then\n            local imp = impTable[sGuid]\n            if imp then\n                if msg == \"SPELL_CAST_START\" then\n                    \n                    -- Cast time, and remaining casts.\n                    \n                    local timestamp = GetTime()\n                    local castTime, remainingCasts = 2 / (1 + UnitSpellHaste(\"player\") / 100), max(imp.casts, 1)\n                    \n                    -- Compute free casts if in extension window.\n                    \n                    if timestamp < imp.ext then\n                        remainingCasts = remainingCasts + floor((imp.ext - timestamp) / castTime)\n                    end\n                    \n                    -- Compute remaining time based on remaining casts, and total remaining duration.\n                    \n                    local remainingTime = castTime * min(floor((imp.maxEnd + leeway - timestamp) / castTime), remainingCasts)\n                    \n                    imp.cast = timestamp + castTime\n                    imp.curEnd = timestamp + remainingTime + leeway\n                    imp.act = imp.cast\n                    \n                    if not imp.show then\n                        imp.show = true\n                        check = true\n                    end\n                    \n                    C_Timer.After(castTime + 0.5, function()\n                            if imp and imp.cast and GetTime() > imp.cast then\n                                imp.cast = nil\n                                imp.curEnd = imp.maxEnd\n                                WeakAuras.ScanEvents(IMP_EVENT, nil)\n                            end\n                    end)\n                    \n                elseif msg == \"SPELL_CAST_SUCCESS\" then\n                    \n                    -- Imp cast finished, decrement energy if not in extension.\n                    \n                    if GetTime() > (imp.ext or 0) then\n                        imp.casts = imp.casts - 1\n                    end\n                    \n                    if imp.casts <= 0 then\n                        imp.cast = nil\n                    end\n                    \n                    update = true\n                end\n            end\n        end\n        \n        -- Ignore all other CLEUs\n        if not check and not update then\n            return false\n        end\n    end\n    \n    check = check or (event == IMP_EVENT) or (event == \"TRIGGER\")\n    update = update or (event == IMP_EVENT)\n    \n    if check then\n        local timestamp = GetTime()\n        \n        -- Check for changes in numbers of imps.\n        \n        local count = C_Spell.GetSpellCastCount(196277)\n        if count ~= actualImps then\n            WeakAuras.ScanEvents(\"WILD_IMP_COUNT\", count)\n            actualImps = count\n            \n            if count == 0 then\n                \n                -- No more imps, clear state table and exit early so that we don't \n                -- create another callback.\n                \n                impTable = {}\n                for _, state in pairs(allstates) do\n                    state.show = false\n                    state.changed = true\n                end\n                \n                if recheckHandle then\n                    recheckHandle:Cancel()\n                    recheckHandle = nil\n                end\n                \n                return true\n            end\n            \n            update = true\n        end\n        \n        -- Count imps, timeout imp casts and remove expired Imps.\n        \n        local impCount = 0\n        local totalImps = 0\n        for guid, imp in pairs(impTable) do\n            if timestamp + 0.5 > imp.maxEnd then\n                impTable[guid] = nil\n            else\n                if imp.show then  \n                    impCount = impCount + 1\n                end\n                \n                totalImps = totalImps + 1\n            end\n        end\n        \n        -- If not enough imps shown, show most active hidden imp; \n        -- else if too many, hide least active.\n        \n        while impCount < actualImps do\n            update = true\n            local newest = nil\n            \n            for _, imp in pairs(impTable) do\n                if not imp.show and (not newest or imp.act > newest.act) then\n                    newest = imp\n                end\n            end\n            \n            if newest then\n                newest.show = true\n                impCount = impCount + 1\n            else\n                break\n            end\n        end\n        \n        while impCount > actualImps do\n            update = true\n            local lowest = nil\n            \n            for _, imp in pairs(impTable) do\n                if imp.show and (not lowest or imp.act < lowest.act) then\n                    lowest = imp\n                end\n            end\n            \n            if lowest then \n                lowest.show = false\n                \n                impCount = impCount - 1\n            else\n                break\n            end\n        end\n    end\n    \n    -- Update Icons if update.\n    \n    if not update then\n        return false\n    end\n    \n    local timestamp = GetTime()\n    local haste = 1 + UnitSpellHaste(\"player\") / 100\n    local duration = 2 * impCasts / haste\n    local cap = timestamp + duration\n    local throttle = batch / (hasted and haste or 1)\n    local lastEndTime = 0\n    \n    -- Get expiration times and sort earliest first.\n    \n    local sorted = {}\n    for _, imp in pairs(impTable) do\n        if imp.show and imp.curEnd > timestamp then\n            sorted[#sorted + 1] = imp\n        end\n    end\n    table.sort(sorted, impSort)\n    \n    local groups, curGroup = {}, nil\n    for _, imp in ipairs(sorted) do\n        if not curGroup \n        or ((not combine or curGroup.endTime < cap) \n            and (limit == 0 or #groups < limit)\n        and imp.curEnd >= lastEndTime + throttle) then\n            \n            curGroup = {\n                endTime = max(imp.curEnd, timestamp),\n                size = 1,\n                imps = { imp },\n                casts = max(0, imp.casts),\n                indexes = { },\n                indexPop = 0\n            }\n            \n            groups[#groups + 1] = curGroup\n            \n            if not persistent then\n                curGroup.index = #groups\n            elseif imp.index then\n                curGroup.indexes[imp.index] = 1\n                curGroup.index = imp.index\n                curGroup.indexPop = 1\n            end\n            \n            lastEndTime = imp.curEnd\n        else\n            curGroup.size = curGroup.size  + 1\n            curGroup.casts = curGroup.casts + max(0, imp.casts)\n            curGroup.imps[#curGroup.imps + 1] = imp\n            \n            if clump then\n                lastEndTime = imp.curEnd\n            end\n            \n            -- If Imp not new, then add contribution to curGroup index.\n            \n            if persistent and imp.index then\n                local pop = (curGroup.indexes[imp.index] or 0) + 1\n                curGroup.indexes[imp.index] = pop\n                \n                -- Update modal index and popularity.\n                \n                if imp.index == curGroup.index then\n                    curGroup.indexPop = pop\n                elseif pop > curGroup.indexPop or (pop == curGroup.indexPop and imp.index > curGroup.index) then\n                    curGroup.indexPop = pop\n                    curGroup.index = imp.index\n                end\n            end\n        end\n    end\n    \n    table.sort(groups, groupSort)\n    for _, group in ipairs(groups) do\n        local state = group.index and allstates[group.index]\n        \n        if not state or state.changed then\n            \n            local index = #allstates + 1\n            \n            state = {\n                progressType = \"timed\",\n                autoHide = false,\n                duration = duration,\n                show = true,\n                index = index,\n            }\n            \n            allstates[index] = state\n        end\n        \n        -- Update Imp last group index.\n        \n        for _, imp in ipairs(group.imps) do\n            imp.index = state.index\n        end\n        \n        -- Update state to match group.\n        \n        state.expirationTime = group.endTime\n        state.imps = group.imps\n        state.changed = true\n        \n        -- Set colour if enabled.\n        \n        if colourTable and group.size ~= state.stacks then\n            state.colour = colourTable[min(group.size, 9)] \n        end\n        \n        -- Set Top-Left Display text.\n        \n        if topleft == 1 then\n            local casts = floor(group.casts / group.size)\n            state.topleft = group.size..(casts > 0 and \"/\"..casts or \"\")\n        elseif topleft == 2 then\n            state.topleft = group.size\n        elseif topleft == 3 then\n            state.topleft = group.casts > 0 and group.casts or \"\"\n        else\n            local casts = floor(group.casts / group.size)\n            state.topleft = casts > 0 and casts or \"\"\n        end\n    end\n    \n    -- Clear up unused states.\n    \n    for _, state in pairs(allstates) do\n        if not state.changed then\n            state.show = false\n        end\n    end\n    \n    -- Callback to update progress values every 0.5s.\n    \n    if not recheckHandle then\n        if recheckHandle then\n            recheckHandle:Cancel()\n        end\n        recheckHandle = C_Timer.NewTimer(0.5, callback)\n    end\n    \n    return true\nend",
