["tocversion"] = 90002,
["alpha"] = 1,
["config"] = {
["ignorekeyword"] = "{spell:123}",
["dbm"] = true,
["duration"] = 10,
["filterNote"] = true,
["internalCounterOnly"] = false,
["bw"] = true,
["bossmoddebug"] = false,
["personalEnable"] = true,
["sharedEnable"] = true,
["customkeyword"] = "<всем>,<камни>,<поты>",
