["custom"] = "function(e, ...)\n    if e == \"PLAYER_ENTERING_WORLD\" then\n        local reloadUI = select(2, ...)\n        if not reloadUI then\n            aura_env.requestReset({hard = true, event = e})\n        end\n    end\n    \n    --[[ disabled until the spell is hotfixed to reset on raid pull\n    if e == \"ENCOUNTER_START\" then\n        local difficultyID = select(3, ...)\n        if difficultyID then\n            local _, groupType = GetDifficultyInfo(difficultyID)\n            if groupType and groupType == \"raid\" then\n                print(difficultyID)\n                aura_env.requestReset({hard = true, event = e, subEvent = \"difficultyID: \" .. difficultyID})\n                aura_env.debugReset(e)\n            end\n        end\n    end\n    ]]\n    \n    if e == \"PLAYER_SPECIALIZATION_CHANGED\" and not (aura_env.currentSpec == GetSpecialization()) then\n        aura_env.requestReset({hard = true, event = e}) \n        aura_env.currentSpec = GetSpecialization()\n    end\n    \n    if e == \"LEARNED_SPELL_IN_SKILL_LINE\" then\n        local spellID = select(1, ...)\n        if spellID == 450615 then\n            aura_env.requestReset({hard = true, event = e}) \n        end\n    end\n    \n    if e == \"CHALLENGE_MODE_START\" or e == \"PLAYER_ENTERING_BATTLEGROUND\" or e == \"PLAYER_JOINED_PVP_MATCH\" then\n        aura_env.requestReset({hard = true, event = e})\n    end\n    \n    return true\nend",
