["names"] = {
},
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, id)\n    if(aura_env.config.hideIfComplete and C_QuestLog.IsQuestFlaggedCompleted(70866)) then\n        return false\n    end\n    if event == \"DRAGONFLIGHT_EVENT_TRACKER\" and id == aura_env.id\n    or event == \"STATUS\" or event == \"OPTIONS\"\n    then\n        local regionTimers = {\n            [1] = 1670338860, -- NA\n            [2] = 1670698860, -- KR\n            [3] = 1670342460, -- EU\n            [4] = 1670698860, -- TW\n            [5] = 1670677260 -- CN\n        }\n        \n        local firstKeepEpochTime = regionTimers[GetCurrentRegion()]\n        local interval = 7200\n        local duration = 600\n        local time_to_next_keep = interval - ((GetServerTime() - firstKeepEpochTime) % interval)\n        local active = interval - time_to_next_keep < duration\n        local remaining = duration - (interval - time_to_next_keep)\n        \n        allstates[\"\"] = {\n            changed = true,\n            show = aura_env.config.trackDragonbane,\n            progressType = \"timed\",\n            autoHide = true,\n            duration = active and duration or interval-duration,\n            expirationTime = GetTime() + (active and remaining or time_to_next_keep),\n            icon = 236469,\n            active = active\n        }\n        \n        return true\n    end\nend\n\n\n\n\n\n\n",
