["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(states, event, ...)\n    if event == \"GLOBAL_MOUSE_UP\" and ... then\n        local button = ...\n        if button == \"LeftButton\" then\n            \n            -- print loot to chat window\n            if IsShiftKeyDown() then\n                local lootLink = \"\"\n                for cloneID, region in pairs(aura_env.regions) do\n                    local over = MouseIsOver(region.icon)\n                    if over and states[cloneID] then\n                        for _, link in ipairs(states[cloneID].links) do\n                            lootLink = lootLink .. link .. \" \"\n                        end\n                        print(states[cloneID].disp .. \": \" .. lootLink)\n                    end\n                end \n            elseif IsControlKeyDown() then\n                for cloneID, region in pairs(aura_env.regions) do\n                    local over = MouseIsOver(region.icon)\n                    if over and states[cloneID] then\n                        local x, y = states[cloneID].X, states[cloneID].Y\n                        if x ~= 0 and y ~=0 then\n                            \n                            if IsAddOnLoaded(\"TomTom\") then\n                                local TomTom = TomTom\n                                TomTom:AddWaypoint(states[cloneID].zoneID, x/100, y/100, {title=states[cloneID].disp,from=\"WA_Haldu\"})\n                            else\n                                C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(states[cloneID].zoneID, x/100, y/100, 0))\n                                C_SuperTrack.SetSuperTrackedUserWaypoint(true)\n                            end\n                        end\n                        break\n                    end\n                end\n            end\n            \n            -- Clear map pins\n        elseif button == \"RightButton\" and IsControlKeyDown() then\n            for cloneID, region in pairs(aura_env.regions) do\n                local over = MouseIsOver(region.icon)\n                if over and states[cloneID] then\n                    if IsAddOnLoaded(\"TomTom\") then\n                        local TomTom = TomTom\n                        TomTom.waydb:ResetProfile()\n                    else\n                        C_Map.ClearUserWaypoint()\n                    end\n                    break\n                end\n            end\n        end\n    else\n        local cfg = aura_env.config\n        local rs  = cfg.rareSettings\n        local map = C_Map.GetBestMapForUnit(\"player\")\n        local class = select(3, UnitClass(\"player\"))\n        local lang = GetLocale()\n        local update\n        \n        if not rs.rareEnable then return end\n        \n        for i, rare in ipairs(cfg.rares) do\n            \n            -- check zones\n            local rareZone = aura_env.zones[rare.zone]\n            local inZone = rareZone.zoneID == map and true or false\n            \n            -- check completion\n            local isCompleted = C_QuestLog.IsQuestFlaggedCompleted(rare.questID)\n            \n            -- skip logic\n            -- PLEASE CLEAN THIS UP IN THE FUTURE ITS UGLY\n            local skip = false\n            if not rare.enabled then skip = true\n            elseif rs.hideComplete and isCompleted then skip = true\n            elseif rs.currentZone and map ~= rareZone.zoneID then skip = true\n            elseif rs.onlyShow[1] == false and rare.isElite then skip = true\n            elseif rs.onlyShow[2] == false and rareZone.zoneID == 2151 then skip = true\n            elseif rs.onlyShow[3] == false and rareZone.zoneID == 2133 then skip = true   \n            elseif rs.onlyShow[4] == false and rareZone.zoneID == 2200 then skip = true\n            end\n            \n            if skip and states[rare.questID] then\n                states[rare.questID] = { changed = true, show = false }\n                update = true\n                \n            elseif not skip and not states[rare.questID] then\n                \n                -- how are we organizing this?\n                local index = rare.lang[lang] ~= \"\" and rare.lang[lang] or rare.name\n                if cfg[\"rareSettings\"].rareSort == 2 then\n                    index = (inZone and 0 or 10) + rare.zone^2 + (rare.isElite and 0 or 1)\n                end\n                \n                local tooltip = rare.name .. \" (\" .. rareZone.zone .. \")\"\n                \n                states[rare.questID] = {\n                    icon = rare.isElite and \"vignetteeventelite\" or \"vignetteevent\",\n                    disp = rare.lang[lang] ~= \"\" and rare.lang[lang] or rare.name,\n                    zone = rareZone.zoneShort,\n                    zoneID = rareZone.zoneID,\n                    inZone = inZone,\n                    currentZone = cfg[\"rareSettings\"].currentZone,\n                    isCompleted = isCompleted,\n                    tooltip = tooltip,\n                    tooltipWrap = false,\n                    index = index,\n                    links = {},\n                    X = rare.X,\n                    Y = rare.Y,\n                    changed = true,\n                    show = true\n                }\n                \n                -- check loot\n                for _, a in ipairs(cfg.rares[i].loot) do\n                    local itemID    = a.itemID\n                    local itemSlot  = a.itemSlot\n                    local itemClass = a.class\n                    local item = Item:CreateFromItemID(itemID)\n                    local link\n                    local slot = aura_env.slots[itemSlot]\n                    \n                    if item and not item:IsItemEmpty() then\n                        \n                        -- check relevant only\n                        if cfg.rareSettings.relOnly and not itemClass[class] then\n                            tooltip = tooltip\n                        else\n                            \n                            item:ContinueOnItemLoad(function()\n                                    tooltip = tooltip .. \"\\n|cFFFFFFFF[\" .. slot .. \"] \" .. item:GetItemLink()\n                                    link = item:GetItemLink()\n                                end\n                            )\n                            table.insert(states[rare.questID].links, link)\n                        end\n                    end\n                end\n                \n                \n                states[rare.questID].tooltip = tooltip .. \"|n|nControl + Left Click to set a waypoint.\"\n                update = true\n            elseif states[rare.questID] and states[rare.questID].isCompleted ~= isCompleted then\n                states[rare.questID].isCompleted = isCompleted\n                states[rare.questID].changed = true\n                update = true\n            elseif states[rare.questID] and states[rare.questID].inZone ~= inZone then\n                states[rare.questID].inZone = inZone\n                states[rare.questID].changed = true\n                update = true\n            end            \n        end\n        \n        return update\n    end\nend",
["events"] = "PLAYER_REGEN_ENABLED, PLAYER_TARGET_CHANGED, ZONE_CHANGED_NEW_AREA, ZONE_CHANGED, ZONE_CHANGED_INDOORS GLOBAL_MOUSE_UP, QUEST_COMPLETE, QUEST_AUTOCOMPLETE",
