["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, id)\n  \n  \n  if not aura_env.config.Feast then \n    return false \n  end\n  if aura_env.config.hideComplete and aura_env.isComplete() then \n    return    false \n  end\n  \n  if event == \"DRAGONFLIGHT_EVENT_TRACKER\" and id == aura_env.id or event == \"STATUS\" or event == \"OPTIONS\" then\n    local regionTimers = {\n      [1] = 1670333460, -- NA\n      [2] = 1670703360, -- KR\n      [3] = 1670331660, -- EU\n      [4] = 1670702460, -- TW\n    }\n    \n    \n    local settime1 = regionTimers[GetCurrentRegion()]\n    \n    local resettimer = 90 --aura_env.config.fbre -- need to finish adding this varibles in custom  options\n    local Rtime = resettimer * 60 -- multiply mins by secs and assign total secs\n    local interval = Rtime\n    \n    local ActiveDrutation = 15 --aura_env.config.sdur  -- need to finish adding this varibles in custom  options\n    local Atime = ActiveDrutation *60 -- multiply mins by secs and assign total secs\n    local duration = Atime\n    \n    \n    local Offsetmins = aura_env.config.fOffsetammout -- get off set amount in mins\n    local Otime = Offsetmins * 60-- multiply mins by secs and assign total secs\n    local offset = Otime\n    \n    settime1 = aura_env.config.feastoffset and settime1+offset or settime1\n    \n    local TtNK = interval - ((GetServerTime() - settime1) % interval)\n    \n    local active = interval - TtNK < duration\n    local remaining = duration - (interval - TtNK)\n    \n    allstates[\"\"] = {\n      changed = true,\n      show = true,\n      progressType = \"timed\",\n      autoHide = true,\n      duration = active and duration or interval-duration,\n      expirationTime = GetTime() + (active and remaining or TtNK),\n      icon = 4687629,\n      active = active\n    }\n    return true\n  end\nend",
