["custom"] = "aura_env.zone = \"\"\n\n-- transliteration\naura_env.langDB = {\n    \n    -- Chinese (Simplified)\n    [\"zhCN\"] = {\n        [\"title\"] = \"洪荒狩猎\",\n        [\"poi\"] = {\n            [7342] = \"欧恩哈拉平原\",\n            [7343] = \"觉醒海岸\",\n            [7344] = \"索德拉苏斯\",\n            [7345] = \"碧蓝林海\",\n        }\n    },\n    \n    -- Chinese (Taiwan)\n    [\"zhTW\"] = {\n        [\"title\"] = \"大狩獵\",\n        [\"poi\"] = {\n            [7342] = \"雍亞拉平原\",\n            [7343] = \"甦醒海岸\",\n            [7344] = \"薩爪祖斯\",\n            [7345] = \"蒼藍高地\",\n        }\n    },\n    \n    -- English (US)\n    [\"enUS\"] = {\n        [\"title\"] = \"Grand Hunt\",\n        [\"poi\"] = {\n            [7342] = \"Ohn'ahran Plains\",\n            [7343] = \"Waking Shores\",\n            [7344] = \"Thaldraszus\",\n            [7345] = \"Azure Span\",\n        }\n    },\n    \n    -- French (FR)\n    [\"frFR\"] = {\n        [\"title\"] = \"Grandes chasses\",\n        [\"poi\"] = {\n            [7342] = \"Plaines d'Ohn'ahra\",\n            [7343] = \"Rivages de l'Éveil\",\n            [7344] = \"Thaldraszus\",\n            [7345] = \"Travée d'Azur\",\n        }\n    },\n    \n    -- German\n    [\"deDE\"] = {\n        [\"title\"] = \"Die Große Jagd\",\n        [\"poi\"] = {\n            [7342] = \"Ebenen von Ohn'ahra\",\n            [7343] = \"Küste des Erwachens\",\n            [7344] = \"Thaldraszus\",\n            [7345] = \"Azurblaues Gebirge\",\n        }\n    },\n    \n    -- Korean (KR)\n    [\"koKR\"] = {\n        [\"title\"] = \"사냥의 제전\",\n        [\"poi\"] = {\n            [7342] = \"온아라 평야\",\n            [7343] = \"깨어나는 해안\",\n            [7344] = \"탈드라서스\",\n            [7345] = \"하늘빛 평원\",\n        }\n    },\n    \n    -- Russian (RU)\n    [\"ruRU\"] = {\n        [\"title\"] = \"Великая охота\",\n        [\"poi\"] = {\n            [7342] = \"Равнины Он'ары\",\n            [7343] = \"Берега Пробуждения\",\n            [7344] = \"Тальдразус\",\n            [7345] = \"Лазурный Простор\",\n        }\n    },\n}",
["do_custom"] = true,
},
},
