["use_unit"] = true,
["customDuration"] = "function()\n    return 0, 100, true\nend",
["subeventPrefix"] = "SPELL",
["events"] = "START, CHAT_MSG_LOOT,PARTY_KILL,BAG_UPDATE,QUEST_COMPLETE,QUEST_AUTOCOMPLETE,WORLD_QUEST_COMPLETED_BY_SPELL,UPDATE_FACTION,QUEST_LOG_UPDATE,ENCOUNTER_LOOT_RECEIVED,QUEST_TURNED_IN,QUEST_LOG_UPDATE",
["custom_type"] = "status",
["check"] = "event",
["custom"] = "function()\n    local cfg = aura_env.config.activities\n    local langDB = aura_env.langDB[GetLocale()] or aura_env.langDB[\"enUS\"]\n    if not cfg.activityEnable or not cfg.grandHunt then return false end\n    \n    -- find the hunt zone, scrape from Dragon Isles (zoneID 1978)\n    for _, poi in ipairs(C_AreaPoiInfo.GetAreaPOIForMap(1978)) do\n        if langDB.poi[poi] then\n            aura_env.zone = langDB.poi[poi]\n            aura_env.zone = poi\n            return true\n        end  \n    end\nend",
