["animate"] = false,
["customGrow"] = "function(newPositions, activeRegions)\n    local cfg = aura_env.child_envs[1].config\n    local spacing = 1\n    local limit = 5\n    local countX, countY = 0, 0\n    local total = #activeRegions\n    \n    for i, regionData in ipairs(activeRegions) do\n        local region = regionData.region\n        local xOffset = 0 + (region.width + spacing) * countX\n        local yOffset = 0 - (region.height + spacing) * countY\n        \n        countY = countY + 1\n        if countY == limit and countX == 0 then\n            countY = 0\n            countX = countX + 1\n        end\n        newPositions[i] = {xOffset, yOffset}\n    end\nend",
