["displayText"] = "%c Soak in %p",
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return \"1.\" end\n    if aura_env.state and aura_env.state.count then\n        return string.format(\"%s.\", aura_env.state.count)\n    end\nend\n\n",
