["init"] = {
["custom"] = "--[[\nReport bugs on discord to anDe#0001 on discord or on wago.\n\nNot finding a mob you want marked?\nsimply add a row like this:\n[\"42069\"] = true,\nwhere \"42069\" is the NPC id. MAKE SURE YOU INCLUDE THE \"\"\nDon't bother with config stuff. that's just for custom config tab\nAlso, thanks for reading this comment. Not a lot of people bother. Hope you're having a swell day :)\n\n1=star, 2=circle, 3=diamond, 4=triangle, 5=moon, 6=square, 7=cross, 8=skull\n\n]]\n\naura_env.orderList = {\n    [\"defaultOrder\"] = {1,2,3,4,5,6,7,8},\n    [\"caster1\"] = {4,3,2,1,5,6,7,8},\n    [\"caster2\"] = {6,7,1,3,5,4,2,2},\n    [\"nonCaster1\"] = {5,7,6,8,4,3,2,1},\n    [\"nonCaster2\"] = {6,8,5,7,4,3,2,1},\n    [\"prio\"] = {8,7,5,4,3,2},    \n}\n\n\n\naura_env.mobList = {\n    --VP\n    [\"45912\"] = aura_env.config.npc45912, --Wild vortex\n    [\"45922\"] = aura_env.config.npc45922, --Empyrean Assassin\n    [\"45928\"] = aura_env.config.npc45928, --Executor of the Caliph\n    [\"45924\"] = aura_env.config.npc45924, --Turbulent Squall (bolt caster)\n    [\"45935\"] = aura_env.config.npc45935, --Temple Adept\n    [\"45930\"] = aura_env.config.npc45930, --Minister of Air\n    [\"45915\"] = aura_env.config.npc45915, --Armored Mistral\n    [\"45477\"] = aura_env.config.npc45477, --Gust Soldier (stun before it charges your tank to recieve a crisp high five)\n    [\"45704\"] = aura_env.config.npc45704, --Lurking Tempest (Look at mob)\n    \n    --Freehold\n    [\"128551\"] = aura_env.config.npc128551, --Irontide Mastiff\n    [\"129788\"] = aura_env.config.npc129788, --Irontide Bonesaw\n    [\"127111\"] = aura_env.config.npc127111 and \"caster1\", --Irontide Oarsman\n    [\"129529\"] = aura_env.config.npc129529, --Irontide Scrapper\n    [\"129547\"] = aura_env.config.npc129547, --Blacktooth Knuckleduster\n    [\"129600\"] = aura_env.config.npc129600 and \"caster1\", --Bilge Rat Brinescale\n    [\"129527\"] = aura_env.config.npc129527, --Bilge Rat  Buccaneer\n    [\"130012\"] = aura_env.config.npc130012, --Irontide Ravager\n    [\"126919\"] = aura_env.config.npc126919 and \"caster1\", --Irontide Stormcaller\n    \n    --The Underrot\n    [\"131436\"] = aura_env.config.npc131436, --Chosen Blood Matron\n    [\"131492\"] = aura_env.config.npc131492 and \"caster1\", --Devout Blood Priest\n    [\"130909\"] = aura_env.config.npc130909, --Fetid Maggot\n    [\"133685\"] = aura_env.config.npc133685, --Befouled Spirit\n    [\"133835\"] = aura_env.config.npc133835, --Feral Bloodswarmer\n    [\"133870\"] = aura_env.config.npc133870 and \"caster1\", --Diseased Lasher\n    [\"134284\"] = aura_env.config.npc134284 and \"caster1\", --Fallen Deathspeaker\n    [\"133836\"] = aura_env.config.npc133836, --Reanimated Guardian\n    [\"138187\"] = aura_env.config.npc138187 and \"caster1\", --Grotesque Horror\n    [\"133912\"] = aura_env.config.npc133912 and \"caster2\", --Bloodsworn Defiler\n    \n    --Neltharion's Lair\n    [\"91006\"] = aura_env.config.npc91006, --Rockback Gnasher\n    [\"91000\"] = aura_env.config.npc91000, --Vileshard hulk (stun)\n    [\"92538\"] = aura_env.config.npc92538, --Tarspitter grub (prio)\n    [\"90998\"] = aura_env.config.npc90998, --Blightshard shaper\n    [\"102232\"] = aura_env.config.npc102232, --Rockbound Trapper\n    [\"91001\"] = aura_env.config.npc91001, --Tarspitter Lurker \n    \n    --neltharus\n    [\"189464\"] = aura_env.config.npc189464, --Qalashi Irontorch\n    [\"189470\"] = aura_env.config.npc189470, --Lava Flare\n    [\"189265\"] = aura_env.config.npc189265, --Qalashi Bonetender\n    [\"189235\"] = aura_env.config.npc189235, --Overseer Lahar\n    [\"192788\"] = aura_env.config.npc192788, --Qalashi Thaumaturge\n    [\"189247\"] = aura_env.config.npc189247, --Tamed Phoenix\n    [\"193944\"] = aura_env.config.npc193944, --Qalashi Lavamancer\n    \n    \n    --brackenhide\n    [\"193799\"] = aura_env.config.npc193799, --Rotchanting Totem\n    [\"186191\"] = aura_env.config.npc186191, --Decay Speaker\n    [\"185528\"] = aura_env.config.npc185528, --Trickclaw Mystic\n    [\"193352\"] = aura_env.config.npc193352, --Hextrick Totem\n    [\"186125\"] = aura_env.config.npc186125, --Tricktotem\n    [\"185529\"] = aura_env.config.npc195135, --Bracken Warscourge (duplicate for some reason. idk... blizz be weird at times)\n    [\"195135\"] = aura_env.config.npc195135, --Bracken Warscourge\n    [\"186246\"] = aura_env.config.npc186246, --Fleshripper Vulture\n    [\"186208\"] = aura_env.config.npc186208, --Rotbow Stalker\n    [\"185656\"] = aura_env.config.npc185656, --Filth Caller\n    [\"186226\"] = aura_env.config.npc186226, --Fetid Rotsinger\n    [\"189531\"] = aura_env.config.npc189531, --Decayed Elder\n    [\"189299\"] = aura_env.config.npc189299, --Decaying Slime (tree boss adds)\n    [\"189363\"] = aura_env.config.npc189363, --Infected Lasher\n    [\"186220\"] = aura_env.config.npc186220, --Brackenhide Shaper\n    [\"186229\"] = aura_env.config.npc186229, --Wilted Oak\n    \n    --uldaman legacy of tyr\n    [\"186658\"] = aura_env.config.npc186658, --stonevault-geomancer\n    [\"184023\"] = aura_env.config.npc184023, --Vicious Basilisk\n    [\"186420\"] = aura_env.config.npc186420, --earthen-weaver\n    [\"184301\"] = aura_env.config.npc184301, --cavern-seeker\n    [\"184132\"] = aura_env.config.npc184132, --Earthen Warder\n    [\"184319\"] = aura_env.config.npc184319, --Refti Custodian\n    [\"184331\"] = aura_env.config.npc184331, --infinite-timereaver\n    [\"184580\"] = aura_env.config.npc184580, --olaf\n    [\"184022\"] = aura_env.config.npc184022, --stonevault-geomancer(2nd boss)\n    \n    --halls of infusion\n    [\"190345\"] = aura_env.config.npc190345, --primalist-geomancer\n    [\"190342\"] = aura_env.config.npc190342, --containment-apparatus\n    [\"199037\"] = aura_env.config.npc199037, --primalist-shocktrooper\n    [\"190362\"] = aura_env.config.npc190362, --dazzling-dragonfly\n    [\"190368\"] = aura_env.config.npc190368, --flamecaller-aymi\n    [\"190340\"] = aura_env.config.npc190340, --refti-defender\n    [\"190373\"] = aura_env.config.npc190373, --primalist-galesinger\n    [\"190377\"] = aura_env.config.npc190377, --primalist-icecaller\n    [\"190407\"] = aura_env.config.npc190407, --aqua-rager\n    [\"190405\"] = aura_env.config.npc190405, --infuser-sariya     \n}\n\n--includes mobs that should be marked by nameplate appearing. You can either add mobs uniquely OR add both in the table above and here\naura_env.mobListNameplate = {\n    --Halls of Infusion\n    [\"196043\"] = aura_env.config.npc196043, --Primalist Infuser (last boss adds) \n    \n}\n\n\n--DO NOT TOUCH\naura_env.marks = {}\naura_env.assigned = {}\n\n\naura_env.getOrder = function(unitId, isNameplate) \n    local orderName\n    if (isNameplate) then\n        orderName = aura_env.mobListNameplate[unitId]\n    else        \n        orderName = aura_env.mobList[unitId]\n    end\n    return  aura_env.orderList[orderName] or aura_env.orderList[\"defaultOrder\"]\nend\n\n--marks the tank with the mark from config IF they don't have a mark already\naura_env.setTankMark = function()\n    if aura_env.config.settingsGroup.markTank == 1 then return end\n    for unit in WA_IterateGroupMembers() do\n        if UnitGroupRolesAssigned(unit) == \"TANK\" and not GetRaidTargetIndex(unit) and not aura_env.assigned[aura_env.config.settingsGroup.markTank - 1] then \n            SetRaidTarget(unit, aura_env.config.settingsGroup.markTank - 1) \n            return\n        end\n    end\nend\naura_env.setTankMark()\n\n\n--marks the Healer with the mark from config IF they don't have a mark already\naura_env.setHealMark = function()\n    if aura_env.config.settingsGroup.markHeal == 1 then return end\n    for unit in WA_IterateGroupMembers() do\n        if UnitGroupRolesAssigned(unit) == \"HEALER\" and not GetRaidTargetIndex(unit) and not aura_env.assigned[aura_env.config.settingsGroup.markTank - 1] then \n            SetRaidTarget(unit, aura_env.config.settingsGroup.markHeal - 1) \n            return\n        end\n    end\nend\naura_env.setHealMark()\n\n\n--checks marks on players in party. DOES NOT empty the list of marked mobs or marks in use\naura_env.checkPremarkedPlayers = function ()\n    for unit in WA_IterateGroupMembers() do\n        if GetRaidTargetIndex(unit) then\n            aura_env.assigned[GetRaidTargetIndex(unit)] = true\n            aura_env.marks[unit] = GetRaidTargetIndex(unit)\n        end\n    end\nend\n\n\n--checks nameplates on screen and adds them to the tracked list if not already in it. DOES NOT empty the list of marked mobs or marks in use\naura_env.checkPremarkedMobs = function ()\n    for i = 1,40 do\n        local unit = \"nameplate\"..i\n        if UnitExists(unit) and GetRaidTargetIndex(unit) and not UnitPlayerControlled(unit) then\n            aura_env.assigned[GetRaidTargetIndex(unit)] = true\n            aura_env.marks[UnitGUID(unit)] = GetRaidTargetIndex(unit) \n        end\n    end\nend\n\n--checks if the unit should be marked\naura_env.isUnitValid = function (unit)\n    if unit == \"player\" then return end\n    local guid = UnitGUID(unit)\n    if not guid then return end\n    local unitid = select(6, strsplit(\"-\", guid))\n    \n    return UnitExists(unit) and not GetRaidTargetIndex(unit) and not aura_env.marks[guid] and aura_env.mobList[unitid] and not UnitIsDead(unit)\nend\n\n--special case for nameplate marking, but same as the function above. Should merge them in the future\naura_env.isUnitValidNameplate = function (unit)\n    if unit == \"player\" then return end\n    local guid = UnitGUID(unit)\n    if not guid then return end\n    local unitid = select(6, strsplit(\"-\", guid))\n    \n    return UnitExists(unit) and not GetRaidTargetIndex(unit) and not aura_env.marks[guid] and aura_env.mobListNameplate[unitid] and not UnitIsDead(unit)\nend\n\n--takes in a unit and the order to mark it with. function checks the marks in the order to find the first availible marker from that order\naura_env.markUnit = function (unit, order)\n    local guid = UnitGUID(unit)\n    for i=1, #order do\n        if not aura_env.assigned[order[i]] and aura_env.config.settingsGroup.enabledMarks[order[i]] then\n            aura_env.marks[guid] = order[i]\n            aura_env.assigned[order[i]] = true\n            SetRaidTarget(unit, order[i])\n            return\n        end\n    end\nend    \n\n\n\n\n\n\n\n--megawatt sync NYI\n\naura_env.specializationName = {\n    [250] = \"TANK\",\n    [581] = \"TANK\",\n    [104] = \"TANK\",\n    [268] = \"TANK\",\n    [66] = \"TANK\",\n    [73] = \"TANK\",\n    [105] = \"HEALER\",\n    [270] = \"HEALER\",\n    [65] = \"HEALER\",\n    [256] = \"HEALER\",\n    [257] = \"HEALER\",\n    [264] = \"HEALER\",\n    [251] = \"DAMAGER\",\n    [252] = \"DAMAGER\",\n    [577] = \"DAMAGER\",\n    [102] = \"DAMAGER\",\n    [103] = \"DAMAGER\",\n    [253] = \"DAMAGER\",\n    [254] = \"DAMAGER\",\n    [255] = \"DAMAGER\",\n    [62] = \"DAMAGER\",\n    [63] = \"DAMAGER\",\n    [64] = \"DAMAGER\",\n    [269] = \"DAMAGER\",\n    [70] = \"DAMAGER\",\n    [258] = \"DAMAGER\",\n    [259] = \"DAMAGER\",\n    [260] = \"DAMAGER\",\n    [261] = \"DAMAGER\",\n    [262] = \"DAMAGER\",\n    [263] = \"DAMAGER\",\n    [265] = \"DAMAGER\",\n    [266] = \"DAMAGER\",\n    [267] = \"DAMAGER\",\n    [71] = \"DAMAGER\",\n    [72] = \"DAMAGER\",\n}\naura_env.GetChatType = function()\n    -- Returns a STRING with the Chat Type for 'SendAddonMessage'\n    return IsInGroup(LE_PARTY_CATEGORY_INSTANCE) and \"INSTANCE_CHAT\" or \"PARTY\"\nend\n\n--sends info regarding marking preferences to megawatt's WA\naura_env.sendPlayerInfo = function()\n    -- ROLE - MarkMobs - MarkPlayers - LEADER - TankIcon - HealerIcon - Decider\n    local role = UnitGroupRolesAssigned(\"player\") == \"NONE\" and aura_env.specializationName[GetSpecializationInfo(GetSpecialization())] or UnitGroupRolesAssigned(\"player\")\n    local leader, score = UnitIsGroupLeader(\"player\"), C_PlayerInfo.GetPlayerMythicPlusRatingSummary(\"player\").currentSeasonScore\n    local markMobs = true\n    local markPlayers = aura_env.config.settingsGroup.markTank > 1\n    local msg = string.format(\"%s:%s:%s:%s:%s:%s\", role, tostring(markMobs), tostring(markPlayers), tostring(leader), score, 2) -- Sending 2 as build to differenciate my WA\n    return C_ChatInfo.SendAddonMessage(\"MYTHICAUTOMARK\", \"WHO_MARK^\"..msg, aura_env.GetChatType())\nend\naura_env.sendPlayerInfo()\n\n\n\n\n\n\n\n\n\n",
["do_custom"] = true,
},
},
