["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region and region.state and region.state.show then\n    WeakAuras.ScanEvents(\"HDH_WEEK\", region.state.event, 1)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local auraID, cloneID  = aura_env.id, aura_env.cloneId\nlocal region = WeakAuras.GetRegion(auraID, cloneID)\nif region then\n    WeakAuras.ScanEvents(\"HDH_WEEK\", region.state.event, 0)\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.db = {\n    \n    [72826] = {\n        [\"ID\"] = 194967,\n        [\"name\"] = {\n            [\"enUS\"] = \"Aileron Seamoth\",\n            [\"koKR\"] = \"날개돋이 해마\",\n            [\"ruRU\"] = \"Мелкокрылая рыба-пегас\",\n            [\"zhCN\"] = \"副翼海蛾鱼\",\n            [\"zhTW\"] = \"副翼海娥魚\",\n        }\n    },\n    \n    [72825] = {\n        [\"ID\"] = 194968,\n        [\"name\"] = {\n            [\"enUS\"] = \"Cerulean Spinefish\",\n            [\"koKR\"] = \"하늘빛 가시고기\",\n            [\"ruRU\"] = \"Лазурная иглоспинка\",\n            [\"zhCN\"] = \"天蓝刺皮鱼\",\n            [\"zhTW\"] = \"天藍棘魚\",\n        }\n    },\n    \n    [72823] = {\n        [\"ID\"] = 194970,\n        [\"name\"] = {\n            [\"enUS\"] = \"Islefin Dorado\",\n            [\"koKR\"] = \"섬지느러미 황새치\",\n            [\"ruRU\"] = \"Островная дорадо\",\n            [\"zhCN\"] = \"岛鳍剑鱼\",\n            [\"zhTW\"] = \"島鰭劍魚\",\n        }\n    },\n    \n    [72828] = {\n        [\"ID\"] = 194730,\n        [\"name\"] = {\n            [\"enUS\"] = \"Scalebelly Mackerel\",\n            [\"koKR\"] = \"비늘배 고등어\",\n            [\"ruRU\"] = \"Чешуебрюхая скумбрия\",\n            [\"zhCN\"] = \"鳞腹鲭鱼\",\n            [\"zhTW\"] = \"鱗肚鯖魚\",\n        }\n    },\n    \n    [72824] = {\n        [\"ID\"] = 194969,\n        [\"name\"] = {\n            [\"enUS\"] = \"Temporal Dragonhead\",\n            [\"koKR\"] = \"시간의 용머리\",\n            [\"ruRU\"] = \"Темпоральная драконоголовка\",\n            [\"zhCN\"] = \"时光龙头鱼\",\n            [\"zhTW\"] = \"時光龍頭魚\",\n        }\n    },\n    \n    [72827] = {\n        [\"ID\"] = 194966,\n        [\"name\"] = {\n            [\"enUS\"] = \"Thousandbite Piranha\",\n            [\"koKR\"] = \"일천이빨 피라냐\",\n            [\"ruRU\"] = \"Тысячезубая пиранья\",\n            [\"zhCN\"] = \"千噬水虎鱼\",\n            [\"zhTW\"] = \"千咬食人魚\",\n        }\n    },\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "START,CHAT_MSG_LOOT,BAG_UPDATE,QUEST_COMPLETE,QUEST_TURNED_IN,UNIT_INVENTORY_CHANGED,ITEM_COUNT_CHANGED",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates)\n    local cfg  = aura_env.config.weekly\n    local db = aura_env.db\n    local lang = GetLocale()\n    \n    if cfg.weeklyEnable and cfg.catchRelease then\n        for questID in pairs(db) do\n            -- build vars\n            local count      = GetItemCount(db[questID].ID,true,true,true)\n            local IsComplete = C_QuestLog.IsQuestFlaggedCompleted(questID)\n            local name       = db[questID].name[lang] or db[questID].name[\"enUS\"]\n            \n            -- are we already done?\n            if cfg.hideComplete and IsComplete then\n                if allstates and allstates[questID] then\n                    allstates[questID] = {\n                        show       = false,\n                        changed    = true,\n                        Count      = count,\n                        event      = questID,\n                        IsComplete = true,\n                        questID    = questID\n                    }\n                end\n                \n                -- build the bar\n            else\n                allstates[questID] = {\n                    changed = true,\n                    show = true,\n                    progressType = \"static\",\n                    autoHide = true,\n                    value = 0,\n                    total = 100,\n                    index = name,\n                    name = name,\n                    Count = count,\n                    IsComplete = IsComplete,\n                    ShowFish = cfg.crCount,\n                    questID  = questID,\n                    event    = questID,\n                }\n            end\n        end\n        \n        return true\n    end\nend\n\n\n",
["custom_type"] = "stateupdate",
["check"] = "event",
["names"] = {
},
["unit"] = "player",
["customVariables"] = "{\n    Count = 'number',\n    IsComplete = 'bool',\n    questID = 'number',\n    ShowFish = 'bool',\n}",
