["init"] = {
["custom"] = "aura_env.db = {}\n\n-- transliteration\naura_env.langDB = {\n    \n    -- Chinese (Simplified)\n    [\"zhCN\"] = \"专业知识\",\n    \n    -- Chinese (Taiwan)\n    [\"zhTW\"] = \"專業知識\",\n    \n    -- English (US)\n    [\"enUS\"] = \"Professions\",\n    \n    -- German\n    [\"deDE\"] = \"Beruf\",\n    \n    -- French\n    [\"frFR\"] = \"Professions\",\n    \n    -- Korean (KR)\n    [\"koKR\"] = \"전문 기술\",\n    \n    -- Russian (RU)\n    [\"ruRU\"] = \"Профессии\",\n}",
