["wagoID"] = "Jp563BG-w",
["parent"] = "Group 1 (HDH)",
["preferToUpdate"] = false,
["customText"] = "function()\n    local item = aura_env.item\n    \n    -- completion coloring\n    local color = aura_env.isComplete() and \"|cFFaad372\" or \"|cFFffffff\"\n    \n    -- fish count\n    local count = aura_env.config.weekly.crCount and item.Count .. \"/20\" or \"\"\n    \n    -- output\n    return color .. item.Name, color .. count\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["width"] = 190,
["iconSource"] = -1,
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://wago.io/HalduDFHelper/151",
["icon"] = false,
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "START, CHAT_MSG_LOOT, BAG_UPDATE, QUEST_COMPLETE, QUEST_TURNED_IN, UNIT_INVENTORY_CHANGED, ITEM_COUNT_CHANGED, GLOBAL_MOUSE_UP",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates, evt, ...)\n    \n    if evt == \"GLOBAL_MOUSE_UP\" and ... then\n        local button = ...\n        if button == \"LeftButton\" and IsShiftKeyDown() then\n            for cloneID, region in pairs(aura_env.regions) do\n                local over = MouseIsOver(region.icon)\n                if over and allstates[cloneID] and allstates[cloneID].event == \"treatise\" then\n                    for _, link in ipairs(allstates[cloneID].links) do\n                        C_TradeSkillUI.SetRecipeTracked(link,true,false)\n                    end\n                end\n            end\n        end\n        \n    else\n        -- build vars\n        local cfg = aura_env.config.profSettings\n        local db  = aura_env.db\n        \n        -- is this thing even on?\n        if not cfg.profEnable then return end\n        \n        -- start checking weekly events\n        for event, v in pairs(db.event) do\n            local lang = GetLocale()\n            local name = v.name[lang] or v.name[\"enUS\"]\n            local info = \"\"\n            local tooltip = name .. \"|n\"\n            local links = {}\n            \n            -- should we care about this event?\n            if cfg[event] then\n                local sort = v.sort\n                for profID, x in pairs(v.questDB) do\n                    \n                    -- do we even have this profession?\n                    local prof1, prof2 = GetProfessions()\n                    prof1 = prof1 and select(7, GetProfessionInfo(prof1))\n                    prof2 = prof2 and select(7, GetProfessionInfo(prof2))\n                    if (profID == prof1 and not cfg.profIgnore.ignore[db.prof[profID].idx]) or (profID == prof2 and not cfg.profIgnore.ignore[db.prof[profID].idx]) then\n                        local completed = 0\n                        local required = x.questReq\n                        local profName = db.prof[profID].name[lang] or db.prof[profID].name[\"enUS\"]\n                        \n                        -- grab profession skill points\n                        local configID = C_ProfSpecs.GetConfigIDForSkillLine(db.prof[profID].skillID)\n                        local profTree = configID and C_Traits.GetConfigInfo(configID) and C_Traits.GetConfigInfo(configID).treeIDs\n                        local skillC, skillT = 0, 0\n                        if profTree then\n                            for _, tree in pairs(profTree) do\n                                for _, node in pairs(C_Traits.GetTreeNodes(tree)) do\n                                    local nodeDB = C_Traits.GetNodeInfo(configID, node)\n                                    skillT = skillT + nodeDB.maxRanks - 1\n                                    skillC = nodeDB.ranksPurchased > 1 and skillC + nodeDB.currentRank - 1 or skillC\n                                end\n                            end\n                        end\n                        if cfg.hideMax and skillC == skillT then else\n                            \n                            -- calculate completion\n                            local questComplete = false\n                            for _, questID in pairs(x.questID) do\n                                if event == \"profQuest\" and (C_TaskQuest.GetQuestTimeLeftSeconds(questID) ~= \"\" or C_QuestLog.IsQuestFlaggedCompleted(questID)) then\n                                    questComplete = C_QuestLog.IsQuestFlaggedCompleted(questID)\n                                else\n                                    questComplete = C_QuestLog.IsQuestFlaggedCompleted(questID)\n                                end\n                                \n                                -- add tooltip info for treatise & drops\n                                if event == \"treatise\" and not questComplete then\n                                    if v.extra[questID] and GetItemInfo(v.extra[questID].itemID) then\n                                        tooltip = tooltip .. \"|n\" .. select(2,GetItemInfo(v.extra[questID].itemID))\n                                        table.insert(links,v.extra[questID].recipeID)\n                                    end\n                                elseif event == \"drops\" and not questComplete then\n                                    local enemy = v.extra[questID].enemy[lang] or v.extra[questID].enemy[\"enUS\"]\n                                    if v.extra[questID] and GetItemInfo(v.extra[questID].itemID) then\n                                        tooltip = tooltip .. \"|n\" .. select(2,GetItemInfo(v.extra[questID].itemID)) .. \" \" .. enemy\n                                    end\n                                end\n                                \n                                if questComplete then completed = completed + 1 or completed end\n                            end\n                            \n                            -- done?\n                            if completed < required then\n                                if v.showCount then info = info == \"\" and profName .. \" \" .. completed .. \"/\" .. required or info .. \" | \" .. profName .. \" \" .. completed .. \"/\" .. required\n                                else info = info == \"\" and profName or info .. \" | \" .. profName end\n                            end\n                        end\n                    end\n                end\n                \n                -- add tooltip footer\n                if v.extra then\n                    tooltip = tooltip .. v.extra.foot\n                end\n                \n                -- update the bar?\n                if allstates[event] then\n                    if info == \"\" then\n                        allstates[event] = { changed = true, show = false, event = event }\n                    else\n                        allstates[event] = {\n                            autoHide     = true,\n                            changed      = true,\n                            event        = event,\n                            icon         = \"vignetteloot\",\n                            index        = sort,\n                            info         = info,\n                            links        = links,\n                            name         = name,\n                            progressType = \"static\",\n                            show         = true,\n                            tooltip      = tooltip,\n                            total        = 100,\n                            value        = 0,\n                        }\n                    end                \n                    \n                    -- build the bars\n                elseif info ~= \"\" then\n                    allstates[event] = {\n                        autoHide     = true,\n                        changed      = true,\n                        event        = event,\n                        icon         = \"vignetteloot\",\n                        index        = sort,\n                        info         = info,\n                        links        = links,\n                        name         = name,\n                        progressType = \"static\",\n                        show         = true,\n                        tooltip      = tooltip,\n                        total        = 100,\n                        value        = 0,\n                    }\n                end\n            end  \n        end\n        \n        return true   \n    end\nend",
