      [\"treatise\"] = {\n            [\"name\"] = aura_env.langDB.treatise,\n            [\"showCount\"] = false,\n            [\"sort\"] = 7,            \n            [\"questDB\"] = {\n                [171] = { [\"questReq\"] = 1, [\"questID\"] = { 74108 } },\n                [164] = { [\"questReq\"] = 1, [\"questID\"] = { 74109 } },\n                [333] = { [\"questReq\"] = 1, [\"questID\"] = { 74110 } },\n                [202] = { [\"questReq\"] = 1, [\"questID\"] = { 74111 } },\n                [182] = { [\"questReq\"] = 1, [\"questID\"] = { 74107 } },\n                [773] = { [\"questReq\"] = 1, [\"questID\"] = { 74105 } },\n                [755] = { [\"questReq\"] = 1, [\"questID\"] = { 74112 } },\n                [165] = { [\"questReq\"] = 1, [\"questID\"] = { 74113 } },\n                [186] = { [\"questReq\"] = 1, [\"questID\"] = { 74106 } },\n                [393] = { [\"questReq\"] = 1, [\"questID\"] = { 74114 } },\n                [197] = { [\"questReq\"] = 1, [\"questID\"] = { 74115 } }\n            },\n            [\"extra\"] = {\n                [\"foot\"] = \"|n|nShift + Left Click to track recipe.\",\n                [74108] = { [\"itemID\"] = 194697, [\"recipeID\"] = 383522 },\n                [74109] = { [\"itemID\"] = 198454, [\"recipeID\"] = 383517 },\n                [74110] = { [\"itemID\"] = 194702, [\"recipeID\"] = 383523 },\n                [74111] = { [\"itemID\"] = 198510, [\"recipeID\"] = 383844 },\n                [74107] = { [\"itemID\"] = 194704, [\"recipeID\"] = 383515 },\n                [74105] = { [\"itemID\"] = 194699, [\"recipeID\"] = 383759 },\n                [74112] = { [\"itemID\"] = 194703, [\"recipeID\"] = 383524 },\n                [74113] = { [\"itemID\"] = 194700, [\"recipeID\"] = 383519 },\n                [74106] = { [\"itemID\"] = 194708, [\"recipeID\"] = 383516 },\n                [74114] = { [\"itemID\"] = 201023, [\"recipeID\"] = 392944 },\n                [74115] = { [\"itemID\"] = 194698, [\"recipeID\"] =