["key"] = "spelltimer",
["length"] = 10,
["multiline"] = false,
["useLength"] = false,
},
{
["type"] = "input",
["useDesc"] = true,
["width"] = 2,
["name"] = "Progressive Timer",
["default"] = "0",
["desc"] = "Changing timers based on cast count. Put Numbers seperated by space. First number is the time from 1st to 2nd cast, then 2nd to 3rd cast and so on.",
