["custom"] = "aura_env.db = {}\n\n-- transliteration\naura_env.langDB = {\n    \n    -- Chinese (Simplified)\n    [\"zhCN\"] = \"活动\",\n    \n    -- Chinese (Taiwan)\n    [\"zhTW\"] =\"活動\",\n    \n    -- English (US)\n    [\"enUS\"] =\"Activities\",\n    \n    -- French (FR)\n    [\"frFR\"] =\"Activités\",\n    \n    -- German\n    [\"deDE\"] = \"Aktivitäten\",\n    \n    -- Korean (KR)\n    [\"koKR\"] = \"활동\",\n    \n    -- Russian (RU)\n    [\"ruRU\"] = \"Деятельности\",\n}",
