["event"] = "Health",
["unit"] = "player",
["custom"] = "function(event, ...)\n    -- parse input\n    if event == \"HDH_ACTIVITY\" then\n        local clone, value = ...\n        aura_env.db = { [clone] = value }\n    end\n    \n    -- check if anything is showing\n    local count = 0\n    for _, i in pairs(aura_env.db) do\n        count = i == 1 and count + 1\n    end    \n    \n    if count == 0 then return end\n    \n    if aura_env.config.activities.activityEnable then return true end\nend",
