["Keystones (HDH)"] = {
["sparkWidth"] = 10,
["iconSource"] = -1,
["wagoID"] = "Jp563BG-w",
["xOffset"] = 0,
["preferToUpdate"] = false,
["customText"] = "function()\n    local item = aura_env.item\n    \n    -- completion coloring\n    local color = aura_env.isComplete() and \"|cFFaad372\" or \"|cFFffffff\"\n    \n    -- fish count\n    local count = aura_env.config.weekly.crCount and item.Count .. \"/20\" or \"\"\n    \n    -- output\n    return color .. item.Name, color .. count\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["semver"] = "2.4.28",
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://wago.io/HalduDFHelper/151",
["actions"] = {
["start"] = {
["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region and region.state and region.state.show then\n    local color = region.state.color\n    region:SetBackgroundColor(color[\"r\"],color[\"g\"],color[\"b\"],.8)\n    WeakAuras.ScanEvents(\"HDH_MPLUS\", region.state.event, 1)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local auraID, cloneID  = aura_env.id, aura_env.cloneId\n\nlocal region = WeakAuras.GetRegion(auraID, cloneID)\nif region then\n    WeakAuras.ScanEvents(\"HDH_MPLUS\", region.state.event, 0)\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.GuildRoster = {}\n\nfunction aura_env.PopulateGuildRoster()\n    for i = 1, GetNumGuildMembers() do\n        local memberName = GetGuildRosterInfo(i)\n        if memberName then\n            aura_env.GuildRoster[memberName] = true\n        end\n    end\nend\n\naura_env.PopulateGuildRoster()\n\naura_env.db = {\n    [0] = { [\"enUS\"] = \"\" },\n    -- dragonflight\n    [402] = {\n        [\"enUS\"] = \"AA\",\n        [\"koKR\"] = \"대학\",\n        [\"zhCN\"] = \"艾杰斯亚学院\",\n        [\"zhTW\"] = \"學院\",\n    },\n    [401] = {\n        [\"enUS\"] = \"AV\",\n        [\"koKR\"] = \"하늘빛\",\n        [\"zhCN\"] = \"碧蓝魔馆\",\n        [\"zhTW\"] = \"蒼藍\",\n    },\n    [405] = {\n        [\"enUS\"] = \"BH\",\n        [\"koKR\"] = \"담쟁이\",\n        [\"zhCN\"] = \"蕨皮山谷\",\n        [\"zhTW\"] = \"蕨皮谷\",\n    },\n    [463] = {\n        [\"enUS\"] = \"FALL\",\n        [\"koKR\"] = \"몰락\",\n        [\"zhCN\"] = \"永恒：陨落\",\n        [\"zhTW\"] = \"黎明前\",\n    }, \n    [406] = {\n        [\"enUS\"] = \"HOI\",\n        [\"koKR\"] = \"주입\",\n        [\"zhCN\"] = \"注能大厅\",\n        [\"zhTW\"] = \"灌注\",\n    },\n    [404] = {\n        [\"enUS\"] = \"NELT\",\n        [\"koKR\"] = \"넬루\",\n        [\"zhCN\"] = \"奈萨鲁斯\",\n        [\"zhTW\"] = \"柰堡\",\n    },\n    [400] = {\n        [\"enUS\"] = \"NO\",\n        [\"koKR\"] = \"노쿠드\",\n        [\"zhCN\"] = \"诺库德阻击战\",\n        [\"zhTW\"] = \"諾庫德\",\n    },\n    [464] = {\n        [\"enUS\"] = \"RISE\",\n        [\"koKR\"] = \"현신\",\n        [\"zhCN\"] = \"永恒：崛起\",\n        [\"zhTW\"] = \"黎明後\",\n    },\n    [399] = {\n        [\"enUS\"] = \"RLP\",\n        [\"koKR\"] = \"루비\",\n        [\"zhCN\"] = \"红玉新生法池\",\n        [\"zhTW\"] = \"晶紅\",\n    },\n    [403] = {\n        [\"enUS\"] = \"ULD\",\n        [\"koKR\"] = \"울다만\",\n        [\"zhCN\"] = \"奥达曼\",\n        [\"zhTW\"] = \"奧達曼\",\n    },\n    \n    -- shadowlands\n    \n    -- battle for azeroth\n    [244] = {\n        [\"enUS\"] = \"AD\",\n        [\"koKR\"] = \"아탈\",\n        [\"zhCN\"] = \"阿塔达萨\",\n        [\"zhTW\"] = \"阿塔\",\n    },\n    [245] = {\n        [\"enUS\"] = \"FH\",\n        [\"koKR\"] = \"자유\",\n        [\"zhCN\"] = \"自由镇\",\n        [\"zhTW\"] = \"自由港\",\n    },\n    [251] = {\n        [\"enUS\"] = \"UR\",\n        [\"koKR\"] = \"썩은굴\",\n        [\"zhCN\"] = \"地渊孢林\",\n        [\"zhTW\"] = \"幽腐\",\n    },\n    [248] = {\n        [\"enUS\"] = \"WM\",\n        [\"koKR\"] = \"웨이\",\n        [\"zhCN\"] = \"维克雷斯庄园\",\n        [\"zhTW\"] = \"莊園\",\n    },\n    \n    -- legion\n    [199] = {\n        [\"enUS\"] = \"BRH\",\n        [\"koKR\"] = \"검떼\",\n        [\"zhCN\"] = \"黑鸦堡垒\",\n        [\"zhTW\"] = \"玄鴉\",\n    },\n    [210] = {\n        [\"enUS\"] = \"COS\",\n        [\"koKR\"] = \"별궁\",\n        [\"zhCN\"] = \"群星庭院\",\n        [\"zhTW\"] = \"眾星\",\n    },\n    [198] = {\n        [\"enUS\"] = \"DHT\",\n        [\"koKR\"] = \"어심\",\n        [\"zhCN\"] = \"黑心林地\",\n        [\"zhTW\"] = \"暗心\",\n    },\n    [206] = {\n        [\"enUS\"] = \"NL\",\n        [\"koKR\"] = \"넬둥\",\n        [\"zhCN\"] = \"巢穴\",\n        [\"zhTW\"] = \"巢穴\",\n    },\n    \n    -- warlords of draenor\n    [168] = {\n        [\"enUS\"] = \"EB\",\n        [\"koKR\"] = \"상록숲\",\n        [\"zhCN\"] = \"永茂林地\",\n        [\"zhTW\"] = \"永茂\",\n    },\n    \n    -- mists of pandaria\n    \n    -- cataclysm\n    [456] = {\n        [\"enUS\"] = \"TOTT\",\n        [\"koKR\"] = \"파도\",\n        [\"zhCN\"] = \"潮汐王座\",\n        [\"zhTW\"] = \"海潮\",\n    },\n    [438] = {\n        [\"enUS\"] = \"VP\",\n        [\"koKR\"] = \"누각\",\n        [\"zhCN\"] = \"旋云之巅\",\n        [\"zhTW\"] = \"漩渦\",\n    },\n}",
