["url"] = "https://wago.io/HalduDFHelper/151",
["actions"] = {
["start"] = {
["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region and region.state and region.state.show then\n    WeakAuras.ScanEvents(\"HDH_ACTIVITY\", region.state.event, 1)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local auraID, cloneID  = aura_env.id, aura_env.cloneId\nC_Timer.After(0, function() WeakAuras.ScanEvents(\"DRAGONFLIGHT_EVENT_TRACKER\", auraID) end)\n\nlocal region = WeakAuras.GetRegion(auraID, cloneID)\nif region then\n    WeakAuras.ScanEvents(\"HDH_ACTIVITY\", region.state.event, 0)\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.zone = 0\n\naura_env.db = {\n    [\"zone\"] = {\n        [0] = {\n            [\"enUS\"] = \"GM Island\"\n        },\n        [2023] = {\n            [\"deDE\"] = \"Ebenen von Ohn'ahra\",\n            [\"enUS\"] = \"Ohn'ahran Plains\",\n            [\"frFR\"] = \"Plaines d'Ohn'ahra\",\n            [\"koKR\"] = \"온아라 평야\",\n            [\"ruRU\"] = \"Равнины Он'ары\",\n            [\"zhCN\"] = \"欧恩哈拉平原\",\n            [\"zhTW\"] = \"雍亞拉平原\"\n        },\n        [2022] = {\n            [\"deDE\"] = \"Küste des Erwachens\",\n            [\"enUS\"] = \"Waking Shores\",\n            [\"frFR\"] = \"Rivages de l'Éveil\",\n            [\"koKR\"] = \"깨어나는 해안\",\n            [\"ruRU\"] = \"Берега Пробуждения\",\n            [\"zhCN\"] = \"觉醒海岸\",\n            [\"zhTW\"] = \"甦醒海岸\"\n        },\n        [2025] = {\n            [\"deDE\"] = \"Thaldraszus\",\n            [\"enUS\"] = \"Thaldraszus\",\n            [\"frFR\"] = \"Thaldraszus\",\n            [\"koKR\"] = \"탈드라서스\",\n            [\"ruRU\"] = \"Тальдразус\",\n            [\"zhCN\"] = \"索德拉苏斯\",\n            [\"zhTW\"] = \"薩爪祖斯\"\n        },\n        [2024] = {\n            [\"deDE\"] = \"Azurblaues Gebirge\",\n            [\"enUS\"] = \"Azure Span\",\n            [\"frFR\"] = \"Travée d'Azur\",\n            [\"koKR\"] = \"하늘빛 평원\",\n            [\"ruRU\"] = \"Лазурный Простор\",\n            [\"zhCN\"] = \"碧蓝林海\",\n            [\"zhTW\"] = \"蒼藍高地\"\n        }\n    },\n    [\"storms\"] = {\n        [\"air\"] = {\n            [\"name\"] = {\n                [\"deDE\"] = \"Sturm: Luft\",\n                [\"enUS\"] = \"Air Storm\",\n                [\"frFR\"] = \"Tempête aérienne\",\n                [\"koKR\"] = \"바람 폭풍\",\n                [\"ruRU\"] = \"Гроза\",\n                [\"zhCN\"] = \"雷暴\",\n                [\"zhTW\"] = \"雷霆風暴\"\n            },\n            [\"questID\"] = 70753,\n            [\"stormID\"] = {\n                [7249] = true, [7253] = true, [7257] = true, [7221] = true, [7225] = true, [7241] = true,\n                [7229] = true, [7233] = true, [7237] = true, [7245] = true, [7298] = true\n            }\n        },\n        [\"earth\"] = {\n            [\"name\"] = {\n                [\"deDE\"] = \"Sturm: Erde\",\n                [\"enUS\"] = \"Earth Storm\",\n                [\"frFR\"] = \"Tempête terrestre\",\n                [\"koKR\"] = \"대지 폭풍\",\n                [\"ruRU\"] = \"Самум\",\n                [\"zhCN\"] = \"沙暴\",\n                [\"zhTW\"] = \"沙塵風暴\"\n            },\n            [\"questID\"] = 70723,\n            [\"stormID\"] = {\n                [7250] = true, [7254] = true, [7258] = true, [7222] = true, [7226] = true, [7242] = true,\n                [7230] = true, [7234] = true, [7238] = true, [7246] = true, [7299] = true\n            }\n        },\n        [\"fire\"] = {\n            [\"name\"] = {\n                [\"deDE\"] = \"Sturm: Feuer\",\n                [\"enUS\"] = \"Fire Storm\",\n                [\"frFR\"] = \"Tempête de feu\",\n                [\"koKR\"] = \"화염 폭풍\",\n                [\"ruRU\"] = \"Огня\",\n                [\"zhCN\"] = \"火暴\",\n                [\"zhTW\"] = \"火焰風暴\",\n            },\n            [\"questID\"] = 70754,\n            [\"stormID\"] = {\n                [7251] = true, [7255] = true, [7259] = true, [7223] = true, [7227] = true, [7243] = true,\n                [7231] = true, [7235] = true, [7239] = true, [7247] = true, [7300] = true\n            }\n        },\n        [\"frost\"] = {\n            [\"name\"] = {\n                [\"deDE\"] = \"Sturm: Frost\",\n                [\"enUS\"] = \"Frost Storm\",\n                [\"frFR\"] = \"Tempête de givre\",\n                [\"koKR\"] = \"물 폭풍\",\n                [\"ruRU\"] = \"Метель\",\n                [\"zhCN\"] = \"雪暴\",\n                [\"zhTW\"] = \"雪風暴\",\n            },\n            [\"questID\"] = 70752,\n            [\"stormID\"] = {\n                [7252] = true, [7256] = true, [7260] = true, [7224] = true, [7228] = true, [7244] = true,\n                [7232] = true, [7236] = true, [7240] = true, [7248] = true, [7301] = true,\n            }\n        }\n    }\n}",
