["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "START, CHAT_MSG_LOOT,PARTY_KILL,BAG_UPDATE,QUEST_COMPLETE,QUEST_AUTOCOMPLETE,WORLD_QUEST_COMPLETED_BY_SPELL,UPDATE_FACTION,QUEST_LOG_UPDATE,ENCOUNTER_LOOT_RECEIVED,QUEST_TURNED_IN,QUEST_LOG_UPDATE",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates)\n    local cfg = aura_env.config.activities\n    local db = aura_env.db\n    \n    -- is this thing even on?\n    if not cfg.activityEnable or not cfg.primalStorm then return end\n    \n    -- iterate storms\n    for storm, x in pairs(db.storms) do\n        \n        -- iterate zones\n        for zoneID, zoneName in pairs(db.zone) do\n            \n            -- iterate points of interest\n            for _, poi in ipairs(C_AreaPoiInfo.GetAreaPOIForMap(zoneID)) do\n                if x.stormID[poi] and C_AreaPoiInfo.GetAreaPOIInfo(zoneID, poi).isPrimaryMapForPOI then\n                    \n                    -- force azure span for cobalt assembly\n                    aura_env.zone = poi == 7233 and 2024 or zoneID\n                    \n                    if cfg.hideComplete and C_QuestLog.IsQuestFlaggedCompleted(x.questID) then\n                        allstates[storm] = { show = false, changed = true, event = storm }\n                    else\n                        -- build the bar\n                        allstates[storm] = {\n                            changed = true,\n                            event = storm,\n                            name = x.name[GetLocale()] or x.name[\"enUS\"],\n                            show = true,\n                            zone = zoneName[GetLocale()] or zoneName[\"enUS\"]\n                        }\n                    end\n                end \n            end\n        end \n    end\n    \n    return true\nend",
["custom_type"] = "stateupdate",
["check"] = "event",
