["custom"] = "function(event, message, ...)\n    if event == \"UNIT_SPELLCAST_SENT\" then\n        local target, _, spellID = ...\n        if message == \"player\" and target == \"夺回的战利品箱\" and spellID == 306608 then\n            aura_env.flag = true\n        end\n    end\n    if event == \"CHEST_FOUND\" and aura_env.flag then\n        aura_env.crystal = 0\n        aura_env.flag = false\n    end\n    if event == \"CRYSTAL_FOUND\" then\n        aura_env.crystal = aura_env.crystal + 1\n    end\n    if event == \"HV_ZONECHANGED\" then\n        if message == 1 then\n            aura_env.zone = true\n        else\n            aura_env.zone = false\n        end\n    end\n    if aura_env.crystal >= 8 and aura_env.zone then\n        return true\n    end\nend",
