["parent"] = "S4-Bars (trash casts/misc)",
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        return ICON_LIST[1]..\"16|t SPELL ->\"..WA_ClassColorName(\"player\") --preview\n    elseif aura_env.state then\n        if aura_env.state.unit then\n            if aura_env.state.targetRole == \"TANK\" then\n                return aura_env.state.definedName\n            else\n                return aura_env.state.definedName .. \" ->\" .. WA_ClassColorName(aura_env.state.unit)\n            end\n        else\n            return aura_env.state.definedName\n        end\n    end\nend",
["sparkRotationMode"] = "AUTO",
["triggers"] = {
{
["trigger"] = {
["spellNames"] = {
},
["duration"] = "7.4",
["subeventPrefix"] = "SPELL",
["unit"] = "nameplate",
["names"] = {
},
["debuffType"] = "HELPFUL",
["use_spellIds"] = false,
["custom_hide"] = "timed",
["events"] = "UNIT_SPELLCAST_START:nameplate, UNIT_SPELLCAST_STOP:nameplate, UNIT_SPELLCAST_CHANNEL_START:nameplate, UNIT_SPELLCAST_CHANNEL_STOP:nameplate, UNIT_TARGET:nameplate, CLEU:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED, CAUSE_DELAY_CHANNEL, CAUSE_DELAY_CAST",
["use_raidMarkIndex"] = false,
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, ...)\n    if (event == \"CAUSE_DELAY_CAST\" or event == \"CAUSE_DELAY_CHANNEL\" or event == \"UNIT_TARGET\") then\n        local unit, guid = ...\n        guid = guid or UnitGUID(unit)\n        local name, duration, expirationTime, icon, notInterruptible, spellID = aura_env.getCastInfo(unit)\n        if spellID and allstates[guid] and not allstates[guid].unit then\n            local _, categoryNumber = unpack(aura_env.spellIDs[spellID])\n            local targetGUID = UnitGUID(unit..\"target\")\n            local role = UnitGroupRolesAssigned(unit..\"target\")\n            if role == \"TANK\" then\n                --exclude tank cause we dont want it to glow when tank gets casted on\n                allstates[guid].targetGUID = targetGUID\n                allstates[guid].targetIsMe = UnitIsUnit(unit..\"target\", \"player\")\n                allstates[guid].changed = true\n            else\n                --updates the cast's target and amount of cast on that target\n                local numCasts = 1\n                local states = {}\n                for key, state in pairs(allstates) do\n                    if state.targetGUID == targetGUID and state.categoryNumber == categoryNumber then\n                        numCasts = numCasts + 1\n                        table.insert(states, key)\n                    end\n                end\n                allstates[guid].numCastsTargetedBy = numCasts\n                allstates[guid].targetGUID = targetGUID\n                allstates[guid].targetIsMe = UnitIsUnit(unit..\"target\", \"player\")\n                allstates[guid].targetRole = UnitGroupRolesAssigned(unit..\"target\")\n                allstates[guid].unit = UnitExists(unit..\"target\") and unit..\"target\"\n                allstates[guid].changed = true\n                for _, state in ipairs(states) do\n                    if state ~= guid then\n                        allstates[state].numCastsTargetedBy = numCasts\n                        allstates[state].changed = true\n                    end\n                end\n            end\n            return true\n        end\n    elseif event == \"UNIT_SPELLCAST_START\"\n    or (event == \"UNIT_SPELLCAST_CHANNEL_START\" and aura_env.config.channel) then\n        local unit, _, spellID = ...\n        local keystoneLevel = C_ChallengeMode.GetActiveKeystoneInfo()\n        if aura_env.spellIDs[spellID] then\n            local role = UnitGroupRolesAssigned(\"player\")\n            local _, _, position = WeakAuras.SpecRolePositionForUnit(\"player\")\n            local customName, categoryNumber, customSound, requiredRole, minKeyLevel = unpack(aura_env.spellIDs[spellID])\n            if(\n                keystoneLevel == 0\n                or not minKeyLevel\n                or keystoneLevel >= minKeyLevel\n            )\n            and(\n                requiredRole == \"ALL\"\n                or\n                role == requiredRole\n                or\n                position == requiredRole\n            ) then\n                local name, duration, expirationTime, icon, notInterruptible, spellID, castType = aura_env.getCastInfo(unit)\n                if spellID then \n                    local guid = UnitGUID(unit)\n                    --scanevent to update correct unit that is being targeted by cast & cast count\n                    C_Timer.After(aura_env.config.delay,\n                        function() WeakAuras.ScanEvents(castType == \"cast\" and \"CAUSE_DELAY_CAST\" or \"CAUSE_DELAY_CHANNEL\", unit, guid)\n                    end)\n                    local mark = GetRaidTargetIndex(unit)\n                    local isRaging = WA_GetUnitBuff(unit, 228318) and true or false\n                    if not notInterruptible or aura_env.ragingExceptionSpellIDs[spellID] or (isRaging and aura_env.config.raging) or not isRaging then\n                        if customSound and aura_env.config.enableSounds then\n                            local onlyFocus = aura_env.config.onlyFocus\n                            if aura_env.config.singleSound then\n                                local duplicate = false\n                                for _, state in pairs(allstates) do\n                                    if state.spellID == spellID then\n                                        duplicate = true\n                                        break\n                                    end\n                                end\n                                if not duplicate then\n                                    if (onlyFocus and UnitGUID(\"focus\") == guid and not notInterruptible) or not onlyFocus or notInterruptible then\n                                        PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..customSound, \"MASTER\")\n                                    end\n                                end\n                            else\n                                if (onlyFocus and UnitGUID(\"focus\") == guid and not notInterruptible) or not onlyFocus or notInterruptible then\n                                    PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..customSound, \"MASTER\")\n                                end\n                            end\n                        end\n                        allstates[guid] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"timed\",\n                            duration = duration,\n                            expirationTime = expirationTime,\n                            castType = event == \"UNIT_SPELLCAST_START\" and \"cast\" or \"channel\",\n                            raidMark = mark and ICON_LIST[mark]..\"16|t\" or \"\",\n                            notInterruptible = notInterruptible,\n                            isRaging = isRaging,\n                            definedName = customName or \"\",\n                            spellName = name,\n                            icon = icon,\n                            numCastsTargetedBy = 0,\n                            isRaging = isRaging,\n                            isFocus = UnitExists(\"focus\") and UnitGUID(\"focus\") == guid or false,\n                            spellID = spellID,\n                            categoryNumber = categoryNumber or -1,\n                            autoHide = true,\n                        } \n                        return true\n                    end\n                end\n            end\n        end\n        \n    elseif event == \"UNIT_SPELLCAST_STOP\" or event == \"UNIT_SPELLCAST_CHANNEL_STOP\" then\n        local unit, _, spellID = ...\n        local state = allstates[UnitGUID(unit)]\n        if state then\n            state.show = false\n            state.changed = true\n            return true\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        if subEvent == \"SPELL_AURA_APPLIED\"\n        and spellID == 228318 then\n            --set raging to true when applied and hide bar if custom option disabled\n            local state = allstates[destGUID]\n            if state then\n                if not aura_env.config.raging then\n                    state.show = false\n                end\n                state.isRaging = true\n                state.changed = true\n                return true\n            end\n        elseif subEvent == \"SPELL_AURA_REMOVED\"\n        and spellID ==  228318 then\n            --set raging to false when removed\n            local state = allstates[destGUID]\n            if state then\n                state.isRaging = false\n                state.changed = true\n                return true\n            else\n                --reshow bar if raging custom option is disabled and raging was dispelled/removed\n                if not aura_env.config.raging then\n                    local unit = UnitTokenFromGUID(destGUID)\n                    if unit then\n                        local name, duration, expirationTime, icon, notInterruptible, spellID, castType = aura_env.getCastInfo(unit)\n                        if spellID and aura_env.spellIDs[spellID] and (castType == \"channel\" and aura_env.config.channel or castType == \"cast\") then\n                            local keystoneLevel = C_ChallengeMode.GetActiveKeystoneInfo()\n                            local customName, categoryNumber, customSound, requiredRole, minKeyLevel = unpack(aura_env.spellIDs[spellID])\n                            local role = UnitGroupRolesAssigned(\"player\")\n                            local _, _, position = WeakAuras.SpecRolePositionForUnit(\"player\")\n                            if (\n                                keystoneLevel == 0\n                                or not minKeyLevel\n                                or keystoneLevel >= minKeyLevel\n                            )\n                            and\n                            (\n                                requiredRole == \"ALL\"\n                                or\n                                role == requiredRole\n                                or\n                                position == requiredRole\n                            ) then\n                                C_Timer.After(aura_env.config.delay,\n                                    function() WeakAuras.ScanEvents(castType == \"cast\" and \"CAUSE_DELAY_CAST\" or \"CAUSE_DELAY_CHANNEL\", unit, destGUID, categoryNumber)\n                                end)\n                                local mark = GetRaidTargetIndex(unit)\n                                local isRaging = WA_GetUnitBuff(unit, 228318) and true or false\n                                if not notInterruptible or aura_env.ragingExceptionSpellIDs[spellID] or (isRaging and aura_env.config.raging) or not isRaging then\n                                    if customSound and aura_env.config.enableSounds then\n                                        local onlyFocus = aura_env.config.onlyFocus\n                                        if aura_env.config.singleSound then\n                                            local duplicate = false\n                                            for _, state in pairs(allstates) do\n                                                if state.spellID == spellID then\n                                                    duplicate = true\n                                                    break\n                                                end\n                                            end\n                                            if not duplicate then\n                                                if (onlyFocus and UnitGUID(\"focus\") == destGUID and not notInterruptible) or not onlyFocus or notInterruptible then\n                                                    PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..customSound, \"MASTER\")\n                                                end\n                                            end\n                                        else\n                                            if (onlyFocus and UnitGUID(\"focus\") == destGUID and not notInterruptible) or not onlyFocus or notInterruptible then\n                                                PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..customSound, \"MASTER\")\n                                            end\n                                        end\n                                    end\n                                    allstates[destGUID] = {\n                                        show = true,\n                                        changed = true,\n                                        progressType = \"timed\",\n                                        duration = duration,\n                                        expirationTime = expirationTime,\n                                        castType = UnitCastingInfo(unit) and \"cast\" or \"channel\",\n                                        raidMark = mark and ICON_LIST[mark]..\"16|t\" or \"\",\n                                        notInterruptible = notInterruptible,\n                                        isRaging = isRaging,\n                                        definedName = customName or \"\",\n                                        spellName = name,\n                                        icon = icon,\n                                        numCastsTargetedBy = 0,\n                                        isRaging = isRaging,\n                                        isFocus = UnitExists(\"focus\") and UnitGUID(\"focus\") == destGUID or false,\n                                        spellID = spellID,\n                                        categoryNumber = categoryNumber or -1,\n                                        autoHide = true,\n                                    } \n                                    return true\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\nend",
