["custom"] = "--[[\n\n1. customName can be used to give the bar a name that you defined.\n2. categoryNumber can be used to differentiate between casts in the conditions. (coloring etc, see examples in conditions)\n3. soundfile (leave it blank like this: \"\" if you don't need a sound.)\n4. role (makes bar for specific cast only appear for either \"ALL\", \"TANK\", \"DAMAGER\", \"HEALER\", \"RANGED\", \"MELEE\")\n5. minimumKeystoneLevel (*optional*) can be used to only show the cast in the specified keystone level or higher. m0 shows all\n\nexample1: \n\n[367500] = {\"Fear\",0,\"Kick.ogg\",\"ALL\"} shows a bar named Fear, assigns category 0 to it, fires a Kick.ogg sound and shows it for everyone.\n\nexample2: \n\n[370764] = {\"Shards\",2,\"CC.ogg\",\"TANK\"} shows a bar named Shards, assigns category 2 to it, fires a CC.ogg sound and shows it for tank only.\n\n\ndefault logic:\n- category 0 is for important stuff\n- category 1 is for casts that deal damage to a specific player (earth bolts etc)\n- category 2 is for stuff that heals enemies\n- category 3 is for stuff that buffs enemies or debuffs friendlies (shouts etc)\n- category 4 is for curses\n- category 5,7 is for random stuff you wanna see\n- category 6 is for important interrupts that are not part of other categories\n\ntbh didnt think much bout this so customize it yourself\n]]\n\n--[spellID] = {\"customName\", categoryNumber, \"soundFile\", \"role\" (ALL/DAMAGER/HEALER/TANK), minimumKeystoneLevel (optional)},\naura_env.spellIDs = {\n    --Brackenhide\n    [367484] = {\"FIXATE\",0,\"CC.ogg\",\"ALL\",}, --Vicious Clawmangle\n    [367500] = {\"FEAR\",6,\"Kick.ogg\",\"ALL\",}, --Hideous Crackle\n    [372711] = {\"INFUSE\",1,\"Kick.ogg\",\"ALL\",}, --Infuse Corruption\n    [382249] = {\"BOLT\",1,\"\",\"ALL\",11}, --Earth Bolt\n    --Halls of Infusion\n    [374339] = {\"SHOUT\",3,\"Kick.ogg\",\"ALL\",}, --Demoralizing Shout\n    --[374020] = {\"BEAM\",1,\"\",\"ALL\",11}, --Containment Beam\n    [374045] = {\"EXPULSE\",6,\"Interrupt.ogg\",\"ALL\",}, --Expulse\n    [395694] = {\"FOCUS\",0,\"CC.ogg\",\"ALL\",}, --Elemental Focus\n    [374563] = {\"DAZZLE\",0,\"CC.ogg\",\"ALL\",}, --Dazzle\n    [374699] = {\"HEAL\",2,\"Kick.ogg\",\"ALL\",}, --Cauterize\n    [376171] = {\"HEAL\",2,\"Kick.ogg\",\"ALL\",}, --Refreshing Tides\n    [375950] = {\"SHARD\",0,\"CC.ogg\",\"ALL\",}, --Ice Shard\n    [377402] = {\"BARRIER\",2,\"Kick.ogg\",\"ALL\",}, --Aqueous Barrier\n    --Uldaman\n    [369823] = {\"SPIKES\",0,\"CC.ogg\",\"ALL\",}, --Spiked Carapace\n    [369365] = {\"CURSE\",4,\"Kick.ogg\",\"ALL\",}, --Curse of Stone\n    [369411] = {\"SONIC\",0,\"CC.ogg\",\"ALL\",}, --Sonic Burst\n    [369811] = {\"SLAM\",7,\"Feet.ogg\",\"MELEE\",}, --BRUTAL SLAM\n    [369675] = {\"LIGHTNING\",1,\"Kick.ogg\",\"ALL\",}, --Chain Lightning\n    [369465] = {\"HAIL\",0,\"CC.ogg\",\"ALL\",}, --Hail of Stone\n    [369399] = {\"BOLT\",1,\"\",\"ALL\",11}, --Stone Bolt\n    --Neltharus\n    [378282] = {\"MOLTEN CORE\",6,\"Kick.ogg\",\"ALL\",}, --Molten Core\n    [378818] = {\"MAGMA\",0,\"CC.ogg\",\"ALL\",}, --Magma Conflagration\n    [372561] = {\"SPEAR\",0,\"CC.ogg\",\"ALL\",}, --Binding Spear\n    [372223] = {\"HEAL\",2,\"Kick.ogg\",\"ALL\",}, --Mending Clay\n    [372538] = {\"MELT\",1,\"\",\"ALL\"}, --Melt\n    [372225] = {\"AXE\",1,\"CC.ogg\",\"ALL\",}, --Dragonbone Axe\n    [372311] = {\"FIST\",0,\"CC.ogg\",\"ALL\",}, --Magma Fist\n    --Ruby Life Pools\n    [372735] = {\"AOE\",0,\"CC.ogg\",\"ALL\",}, --Tectonic Slam\n    [372743] = {\"SHIELD\",2,\"Kick.ogg\",\"ALL\",}, --Ice Shield\n    [384194] = {\"BOLT\",1,\"\",\"ALL\",11}, --Cinderbolt #1\n    [384197] = {\"BOLT\",1,\"\",\"ALL\",11}, --Cinderbolt #2\n    [385536] = {\"DANCE\",0,\"CC.ogg\",\"ALL\",}, --Flame Dance\n    [392451] = {\"FLASH\",2,\"Kick.ogg\",\"ALL\",}, --Flashfire\n    --Nokhud Offensive\n    [384365] = {\"SHOUT\",6,\"Kick.ogg\",\"ALL\",}, --Disruptive Shout\n    [383823] = {\"RALLY\",3,\"CC.ogg\",\"ALL\",}, --Rally the Clan\n    [386024] = {\"TEMPEST\",6,\"Kick.ogg\",\"ALL\",}, --Tempest\n    [387125] = {\"THUNDER\",1,\"Kick.ogg\",\"ALL\",}, --Thunderstrike\n    [387411] = {\"VOLLEY\",0,\"Kick.ogg\",\"ALL\",}, --Death Bolt Volley\n    [436841] = {\"ROTTING\",0,\"CC.ogg\",\"ALL\",}, --Rotting Wind\n    [373395] = {\"SHOUT\",6,\"Kick.ogg\",\"ALL\",}, --Bloodcurdling Shout\n    [376725] = {\"BOLT\",1,\"\",\"ALL\",11}, --Storm Bolt\n    --Azure Vault\n    [387564] = {\"VAPORS\",0,\"CC.ogg\",\"ALL\",}, --Mystic Vapors\n    [375596] = {\"GROWTH\",6,\"Kick.ogg\",\"ALL\",}, --Erratic Growth\n    [386546] = {\"SLEEP\",0,\"Kick.ogg\",\"ALL\",}, --Waking Bane\n    [377488] = {\"BINDINGS\",6,\"Kick.ogg\",\"ALL\",}, --Icy Bindings\n    [370764] = {\"SHARDS\",0,\"CC.ogg\",\"ALL\",}, --Piercing Shards\n    --Algeth'ar Academy\n    [396812] = {\"AOE\",0,\"CC.ogg\",\"ALL\",}, --Mystic Blast\n    [377389] = {\"CALL\",3,\"Kick.ogg\",\"ALL\",}, --Call of the Flock\n    [388392] = {\"SLEEP\",0,\"CC.ogg\",\"ALL\",}, --Monotonous Lecture\n    [387910] = {\"WHIRL\",0,\"CC.ogg\",\"ALL\",}, --Astral Whirlwind\n    [388862] = {\"SURGE\",1,\"\",\"ALL\"}, --Surge\n    [388863] = {\"MANA\",1,\"\",\"ALL\",11}, --Mana Void\n    [387974] = {\"MISSILES\",1,\"\",\"ALL\",11}, --Arcane Missiles\n    [390912] = {\"FEET\",5,\"Feet.ogg\",\"ALL\"}, --Detonating Seeds\n    [388911] = {\"BLEED\",0,\"\",\"ALL\"}, --Severing Slash\n    [389054] = {\"LUNGE\",11,\"\",\"ALL\"}, --Vicious Lunge\n}\n\n--spellIDs listed here will not hide when the mob is affected by raging.\n--this is for special cases that can't be CCd anyway. (interruptible raging casts show anyway)\naura_env.ragingExceptionSpellIDs = {\n    [390912] = true, --Detonating Seeds\n}\n\naura_env.getCastInfo = function(unit)\n    local name, startC, endC, icon, notInterruptible, spellID, duration, expirationTime, _, castType\n    if UnitCastingInfo(unit) then\n        name, _, icon, startC, endC, _, _, notInterruptible, spellID = UnitCastingInfo(unit)\n        castType = \"cast\"\n    elseif UnitChannelInfo(unit) then\n        name, _, icon, startC, endC, _, notInterruptible, spellID = UnitChannelInfo(unit)\n        castType = \"channel\"\n    end\n    if startC and endC then\n        duration = (endC - startC) / 1000\n        expirationTime = endC / 1000\n    end\n    return name, duration, expirationTime, icon, notInterruptible, spellID, castType\nend\n\n\n\n",
["do_custom"] = true,
},
