["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    unit = {\n        display = \"Party Member\",\n        type = \"select\",\n        values = {\n            [\"party1\"] = \"Party1\",\n            [\"party2\"] = \"Party2\",\n            [\"party3\"] = \"Party3\",\n            [\"party4\"] = \"Party4\",\n        }\n    },\n    pp = {\n        display = \"Powerpercent\",\n        type = \"number\"\n    },\n    gift = {\n        display = \"Gift of the Titans\",\n        type = \"number\"\n    },\n    death = {\n        display = \"Cheat Death\",\n        type = \"bool\"\n    }\n}",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, e, u, p, ...)\n    if e == \"UNIT_POWER_BAR_SHOW\" or e == \"STATUS\" then\n        local guid\n        aura_env.unit = {}\n        aura_env.active_widget = nil\n        aura_env.checked = nil\n        aura_env.tracked_widgets = {}\n        \n        for unit in WA_IterateGroupMembers() do\n            guid = UnitGUID(unit)\n            aura_env.unit[guid] = unit\n            aura_env.losses[unit] = {}\n            aura_env.avg[unit] = {}\n            \n            if UnitIsPlayer(unit) then\n                states[guid] = aura_env.get_state(guid)\n                aura_env.cloaks[guid] = aura_env.reduction(unit)\n            end\n        end\n        return true\n    elseif e == \"UNIT_POWER_UPDATE\" and p == \"ALTERNATE\" then\n        local guid = UnitGUID(u)\n        if states[guid] then\n            local s = states[guid]\n            local power, max_power = UnitPower(u, 10), UnitPowerMax(u, 10)\n            local pp = max_power and power/max_power\n            local cloak = aura_env.cloaks[guid]\n            local active_widget = aura_env.active_widget\n            local tracked_widgets = aura_env.tracked_widgets[active_widget]\n            \n            if not cloak then\n                aura_env.cloaks[guid] = aura_env.reduction(u)\n                cloak = aura_env.cloaks[guid]\n            end\n            \n            local loss = power<s.value and s.value-power\n            \n            if active_widget and tracked_widgets and (cloak or (aura_env.avg[u] and aura_env.avg[u][tracked_widgets])) then\n                s.loss = max(1, cloak and tracked_widgets*cloak or aura_env.avg[u][tracked_widgets])\n                s.avg = \"\"\n            else\n                if loss and loss<=12 then\n                    tinsert(aura_env.losses[u], loss)\n                    s.loss = aura_env.average(u)\n                    s.avg = \"~\"\n                end\n            end\n            \n            -- after a dc the maximum sanity can be off\n            if s.total ~= max_power then\n                s.total = max_power\n            end\n            \n            s.value = power\n            s.pp = aura_env.dec and pp and string.format(aura_env.dec, pp*100)\n            s.changed = true\n            return true\n        else\n            states[guid] = aura_env.get_state(guid)\n            return true\n        end\n    elseif e == \"UNIT_MAXPOWER\" and p == \"ALTERNATE\" then\n        local guid = UnitGUID(u)\n        \n        if states[guid] then\n            local s = states[guid]\n            local power, max_power = UnitPower(u, 10), UnitPowerMax(u, 10)\n            \n            s.value = power\n            s.total = max_power\n            s.changed = true\n            return true\n        end\n        \n    elseif e == \"GROUP_ROSTER_UPDATE\" then\n        aura_env.unit = {}\n        aura_env.checked = nil\n        \n        local guid\n        for unit in WA_IterateGroupMembers() do\n            if UnitIsPlayer(unit) then\n                guid = UnitGUID(unit)\n                aura_env.unit[guid] = unit\n                aura_env.losses[unit] = {}\n                aura_env.avg[unit] = aura_env.avg[unit] or {}\n                \n                states[guid] = states[guid] or aura_env.get_state(guid)\n                states[guid].unit = unit\n                aura_env.cloaks[guid] = aura_env.reduction(unit)\n            end\n        end\n        \n        for guid, s in pairs(states) do\n            if not aura_env.unit[guid] then\n                s.show = false\n                s.changed = true\n            end\n        end\n        \n        return true\n    elseif e == \"UNIT_POWER_BAR_HIDE\" and u then\n        if u == \"player\" then\n            for k,v in pairs(states) do\n                v.show = false\n                v.changed = true\n            end\n            return true            \n        else\n            local guid = UnitGUID(u)\n            if states[guid] then\n                local s = states[guid]\n                s.show = false\n                s.changed = true\n                return true\n            end\n        end\n    end\n    \n    if e == \"TRIGGER\" then\n        local triggerNum, triggerStates = u, p\n        \n        if triggerNum == 3 then\n            for _, s in pairs(states) do\n                if not triggerStates[s.unit] then\n                    s.gift = 2\n                end\n            end\n            \n            for unit, tState in pairs(triggerStates) do\n                if states[tState.GUID] then\n                    local s = states[tState.GUID]\n                    if s.gift ~= 1 then\n                        s.changed = true\n                        s.gift = 1\n                        \n                        C_Timer.After(80, function() WeakAuras.ScanEvents(\"PRMK_GIFT_UPDATE\", tState.GUID) end)\n                    end\n                end\n            end\n            \n            return true\n        elseif triggerNum == 4 and triggerStates[\"\"] then\n            for guid, s in pairs(states) do\n                s.gift = 0\n                s.changed = true\n            end\n            \n            return true\n        end\n    elseif e == \"PRMK_GIFT_UPDATE\" then\n        local guid = u\n        if states[guid] then\n            local s = states[guid]\n            s.gift = 0\n            s.changed = true\n            return true\n        end\n    elseif e == \"PRMK_CHEAT_DEATH\" then\n        if u and states[u] then\n            states[u].death = true\n            states[u].changed = true\n            return true\n        end\n    end\n    \n    if e == \"OPTIONS\" then\n        local names = {\n            player = \"player\",\n            party1 = \"party1\",\n            party2 = \"party2\",\n            party3 = \"party3\",\n            party4 = \"party4\",\n        }\n        \n        local i = 0\n        for unit, name in pairs(names) do\n            i = i + 1\n            local pp = (i*300/2500)\n            \n            states[unit] = {\n                index = (unit==\"player\") and 1 or tonumber(unit:match(\"%d\")),\n                progressType = \"static\",\n                value = i*300,\n                total = 2500,\n                gift = i==5 and 1 or i==4 and 0 or 2,\n                death = i == 5,\n                pp = aura_env.config.percent_power and string.format(aura_env.dec,pp*100),\n                loss = 6,\n                unit = unit,\n                name = aura_env.cc_text and UnitExists(name) and WA_ClassColorName(name) or name,\n                show = true,\n                changed = true\n            }\n        end\n    end\nend",
