["customText"] = "function()\n    if aura_env.config.time_left then\n        if aura_env.state and aura_env.state.loss and aura_env.state.loss > 0 and aura_env.state.value then\n            local value = aura_env.state.value\n            local loss = aura_env.state.loss\n            \n            local time_left = value/loss\n            return string.format(\" - %s%02d:%02d\",\"\",floor(time_left/60),floor(time_left%60))\n        end\n    end\nend",
["icon_side"] = "RIGHT",
["color"] = {
},
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "local c = aura_env.config\nlocal aura_env = aura_env\naura_env.active_widget = nil\naura_env.tracked_widgets = nil\naura_env.checked = nil\naura_env.cloaks = {}\naura_env.losses = {}\naura_env.avg = {}\naura_env.cc_text = c.class_color_text\naura_env.cc_bar = c.class_color_bar\naura_env.dec = c.percent_power and \" | %.\".. (c.decimals-1) ..\"f%%\"\naura_env.unit = {}\n\naura_env.get_state = function(guid)\n    local unit = aura_env.unit[guid]\n    \n    if unit then\n        local power, max_power = UnitPower(unit, 10), UnitPowerMax(\"player\", 10)\n        local pp = max_power > 0 and power/max_power or 0\n        \n        local s = {\n            index = (unit==\"player\") and 1 or tonumber(unit:match(\"%d\")),\n            progressType = \"static\",\n            value = power or UnitPower(\"player\", 10),\n            total = max_power,\n            pp = aura_env.dec and pp and string.format(aura_env.dec,pp*100),\n            gift = 2,\n            unit = unit,\n            guid = guid,\n            name = aura_env.cc_text and WA_ClassColorName(unit) or UnitName(unit),\n            show = true,\n            changed = true\n        }\n        return s \n    end\nend\n\naura_env.cloak_rank = function()\n    local cloak = GetInventoryItemLink(\"player\",15)\n    local cloak_id = cloak:match(\":(%d+)\")\n    \n    if cloak_id == \"169223\" then\n        local bonus_ids = {strsplit(\":\",cloak)}\n        local cloak_upgrade = bonus_ids[15]\n        return aura_env.sanity_multi[cloak_upgrade]\n    end\nend\n\naura_env.reduction = function(unit)\n    local auraData = C_UnitAuras.GetAuraDataBySpellName(unit, C_Spell.GetSpellName(1216153), \"HELPFUL\")\n    if auraData then\n        return 1 - auraData.points[1] / 100\n    end\nend\n\naura_env.average = function(u)\n    local total = 0\n    for i, v in ipairs(aura_env.losses[u]) do\n        total = total+v\n    end\n    \n    return #aura_env.losses[u]>0 and total/#aura_env.losses[u]\nend\n\naura_env.update_widgets = function()\n    local setIds = {261, 262, 263, 264, 265, 245, 246, 247, 248, 253}\n    local drain = {}\n    local info = {}\n    aura_env.tracked_widgets = {}\n    \n    for _, setId in ipairs(setIds) do\n        local childs = C_UIWidgetManager.GetAllWidgetsBySetID(setId)\n        \n        for _, child in ipairs(childs) do\n            if child.widgetType == 13 then\n                \n                local type_info = UIWidgetManager:GetWidgetTypeInfo(child.widgetType)\n                local widget_info = type_info.visInfoDataFunction(child.widgetID)\n                local spell_info = widget_info and widget_info.spellInfo\n                \n                if widget_info and spell_info then\n                    if spell_info.stackDisplay > 0 then\n                        drain[setId] = spell_info.stackDisplay\n                    else\n                        info[child.widgetID] = {spellId = spell_info.spellID, setId = setId}\n                    end\n                end\n            end\n        end\n    end\n    \n    for widgetId, widget_info in pairs(info) do\n        local stacks = drain[widget_info.setId]\n        aura_env.tracked_widgets[widget_info.spellId] = stacks\n    end\n    \n    aura_env.checked = true\nend",
