["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["custom_type"] = "stateupdate",
["event"] = "Conditions",
["names"] = {
},
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, id)\n    \n    \n    if not aura_env.config.Fury then \n        return false \n    end\n    if aura_env.config.hideComplete and aura_env.isComplete() then \n        return    false \n    end\n    \n    if event == \"DRAGONFLIGHT_EVENT_TRACKER\" and id == aura_env.id or event == \"STATUS\" or event == \"OPTIONS\" then\n        local regionTimers = {\n            [1] = 1679572800, -- NA\n            [2] = 1679572800, -- KR\n            [3] = 1679572800, -- EU\n            [4] = 1679572800, -- TW\n            [5] = 1679572800} -- CN \n        \n        local settime1 = regionTimers[GetCurrentRegion()]\n        \n        local resettimer = 60 --aura_env.config.fbre -- need to finish adding this varibles in custom  options\n        local Rtime = resettimer * 120 -- multiply mins by secs and assign total secs\n        local interval = Rtime\n        \n        local ActiveDrutation = 5 --aura_env.config.sdur  -- need to finish adding this varibles in custom  options\n        local Atime = ActiveDrutation *5 -- multiply mins by secs and assign total secs\n        local duration = Atime\n        \n        \n        local Offsetmins = aura_env.config.Offsetammout -- get off set amount in mins\n        local Otime = Offsetmins * 5-- multiply mins by secs and assign total secs\n        local offset = Otime\n        \n        settime1 = aura_env.config.Furyoffset and settime1+offset or settime1\n        \n        local TtNK = interval - ((GetServerTime() - settime1) % interval)\n        \n        local active = interval - TtNK < duration\n        local remaining = duration - (interval - TtNK)\n        \n        allstates[\"\"] = {\n            changed = true,\n            show = true,\n            progressType = \"timed\",\n            autoHide = true,\n            duration = active and duration or interval-duration,\n            expirationTime = GetTime() + (active and remaining or TtNK),\n            icon = 236469,\n            active = active\n        }\n        return true\n    end\nend",
