["custom"] = "function(event, ...)\n    if event ~= 'PLAYER_TOTEM_UPDATE' then \n        return false\n    end\n    \n    local index = select(1, ...)\n    local haveTotem, totemName, startTime, duration, icon = GetTotemInfo(index)\n    \n    if haveTotem then\n        -- Icon IDs for Summon Vilefiend, Charhound, and Gloomhound\n        local validIcons = {\n            [1616211] = true, -- Summon Vilefiend\n            [1709931] = true, -- Summon Charhound\n            [1709932] = true  -- Summon Gloomhound\n        }\n        \n        if validIcons[icon] then\n            aura_env.start = startTime\n            aura_env.duration = duration\n            aura_env.icon = icon\n            return true\n        end\n    end\n    \n    return false\nend",
