["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, id)\n    if event == \"DRAGONFLIGHT_EVENT_TRACKER\" and id == aura_env.id\n    or event == \"STATUS\" or event == \"OPTIONS\"\n    then\n        local regionTimers = {\n            [1] = 1671314400, -- NA\n            [2] = nil, -- KR\n            [3] = 1671307200, -- EU\n            [4] = nil, -- TW\n            [5] = nil -- CN\n        }\n        \n        local firstEvent = regionTimers[GetCurrentRegion()]\n        --Return early if we don't have data on the specific region\n        if(firstEvent == nil) then\n            return\n        end\n        \n        local interval = 18000\n        local duration = 7200\n        local time_to_next = interval - ((GetServerTime() - firstEvent) % interval)\n        local active = interval - time_to_next < duration\n        local remaining = duration - (interval - time_to_next)\n        \n        allstates[\"\"] = {\n            changed = true,\n            show = aura_env.config.trackStormsFury,\n            progressType = \"timed\",\n            autoHide = true,\n            duration = active and duration or interval-duration,\n            expirationTime = GetTime() + (active and remaining or time_to_next),\n            icon = 1394949,\n            active = active\n        }\n        \n        return true\n    end\nend\n\n\n\n\n\n\n",
