["duration"] = "3.5",
["custom"] = "function(allstates, event, ...)    \n    if event == \"UNIT_TARGET\" then\n        local unit = ...\n        local spellID = select(9, UnitCastingInfo(unit))\n        if spellID == 374839 then\n            aura_env.counter = aura_env.counter + 1\n            if aura_env.counter == 2 and UnitIsUnit(unit..\"target\", \"player\") then\n                local state = allstates[\"blazing\"]\n                if state then\n                    state.targeted = true\n                    state.changed = true\n                    return true\n                end\n            else\n                local state = allstates[\"blazing\"]\n                if state then\n                    state.targeted = false\n                    state.changed = true\n                    return true\n                end\n            end\n        end\n    elseif event == \"UNIT_SPELLCAST_START\" then\n        local _, _, spellID = ...\n        if spellID == 374839 then\n            aura_env.counter = 0\n        end\n    elseif event == \"UNIT_SPELLCAST_STOP\" then\n        local _, _, spellID = ...\n        if spellID == 374839 then\n            local state = allstates[\"blazing\"]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ...\n        if subEvent == \"SPELL_AURA_APPLIED\"\n        and spellID == 374842\n        and destGUID == WeakAuras.myGUID then\n            allstates[\"blazing\"] = {\n                show = true,\n                changed =  true,\n                progressType = \"timed\", \n                duration = 3.5,\n                expirationTime = 3.5 + GetTime(),\n                autoHide = true,\n            }\n            return true\n        end\n    end\nend",
