["actions"] = {
["start"] = {
["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region and region.state and region.state.show then\n    WeakAuras.ScanEvents(\"HDH_WEEK\", region.state.event, 1)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local auraID, cloneID  = aura_env.id, aura_env.cloneId\nlocal region = WeakAuras.GetRegion(auraID, cloneID)\nif region then\n    WeakAuras.ScanEvents(\"HDH_WEEK\", region.state.event, 0)\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.db = {\n    [\"whelp\"] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Whelpling Crests\",\n            [\"koKR\"] = \"새끼용 파편\",\n            [\"ruRU\"] = \"Фрагмент дракончика\",\n            [\"zhCN\"] = \"雏龙纹章碎片\",\n            [\"zhTW\"] = \"幼龍紋章碎片\",\n        },\n        [\"ID\"] = 2706,\n    },\n    [\"drake\"] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Drake Crests\",\n            [\"koKR\"] = \"비룡 파편\",\n            [\"ruRU\"] = \"Фрагмент дракона\",\n            [\"zhCN\"] = \"幼龙纹章碎片\",\n            [\"zhTW\"] = \"飛龍紋章碎片\",\n        },\n        [\"ID\"] = 2707,\n    },\n    [\"wyrm\"] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Wyrm Crests\",\n            [\"koKR\"] = \"고룡 파편\",\n            [\"ruRU\"] = \"Фрагмент змея\",\n            [\"zhCN\"] = \"魔龙纹章碎片\",\n            [\"zhTW\"] = \"巨龍紋章碎片\",\n        },\n        [\"ID\"] = 2708,\n    },\n    [\"aspect\"] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Aspect Crests\",\n            [\"koKR\"] = \"위상 파편\",\n            [\"ruRU\"] = \"Фрагмент Аспекта\",\n            [\"zhCN\"] = \"守护巨龙纹章碎片\",\n            [\"zhTW\"] = \"守護巨龍紋章碎片\",\n        },\n        [\"ID\"] = 2709,\n    },\n}",
