["sparkRotationMode"] = "AUTO",
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "START,CHAT_MSG_LOOT,BAG_UPDATE,UNIT_INVENTORY_CHANGED,ITEM_COUNT_CHANGED",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates)\n    local cfg  = aura_env.config.weekly\n    local db   = aura_env.db\n    local lang = GetLocale()\n    \n    for frag, x in pairs(db) do\n        \n        -- calculating...\n        local cur   = C_CurrencyInfo.GetCurrencyInfo(x.ID)\n        local count = cur.totalEarned\n        local max   = cur.maxQuantity\n        local prog = cfg.fragPercent and math.floor((count / max) * 100) .. \"%\" or count .. \"/\" .. max \n        \n        -- dont bother showing the caps if there isnt one\n        if cur.maxQuantity == 0 then return end\n        \n        -- do we hide or show the bar?\n        if cfg.hideComplete and count == max or not cfg[frag] then\n            allstates[x.ID] = { show = false, changed = true, event = x.ID }\n        else\n            allstates[x.ID] = {\n                changed      = true,\n                event        = x.ID,\n                frag         = frag,\n                index        = x.ID,\n                info         = prog,\n                name         = x.name[lang] or x.name[\"enUS\"],\n                progressType = \"static\",\n                show         = true,\n                total        = max,\n                value        = count,\n            }\n        end\n    end\n    \n    return true\nend",
["custom_type"] = "stateupdate",
