["custom"] = "aura_env.allowlist = {\n    [183539] = true, --Barbed Tongue (Neltharion)\n    [200154] = true, --Burning Hatred (Neltharion)\n    [372225] = true, --Dragonbone Axe (Neltharion)\n    [378818] = true, --Magma Conflagration (Neltharion)\n    [374073] = true, --Seismic Slam (Halls of Infusion)\n    [374724] = true, --Molten Subduction (Halls of Infusion)\n    --[382593] = true, --Crushing Smash (Brackenhide Hollow)\n    [385832] = true, --Bloodthirsty Charge (Brackenhide Hollow)\n    [368287] = true, --Toxic Trap (Brackenhide Hollow)\n    [388060] = true, --Stink Breath (Brackenhide Hollow)\n    [367484] = true, --Vicious Clawmangle (Brackenhide Hollow)\n    [391136] = true, --Shoulder Slam (Azure Vault)\n    --[391723] = true, --Flame Breath (Ruby Life Pools)\n    --[391726] = true, --Storm Breath (Ruby Life Pools)\n    [387127] = true, --Chain Lightning (The Nokhud Offensive)\n    [382077] = true, --Command: Seek (The Nokhud Offensive)\n    [381683] = true, --Swift Stab (The Nokhud Offensive)\n    --[389054] = true, --Vicious Lunge (Algeth'ar Academy)\n}",
