["custom"] = "function(allstates, event, ...)\n    if event == \"UNIT_SPELLCAST_START\" then\n        local unit, _, spellID = ...\n        if spellID == 388537 then\n            local isOverlap\n            for unit in WA_IterateGroupMembers() do\n                if WA_GetUnitDebuff(unit, 386181) then\n                    isOverlap = true\n                    break\n                end\n            end\n            local _, _, _, startMS, endMS, _, _, _, spellId = UnitCastingInfo(unit)\n            if spellId then\n                allstates[spellID] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = ((endMS-startMS)/1000),\n                    expirationTime = (endMS/1000),\n                    overlap = isOverlap or false,\n                    autoHide = true,\n                } \n                return true\n            end\n        end\n    end\nend",
