["Faction Progress (HDH)"] = {
["sparkWidth"] = 10,
["iconSource"] = -1,
["wagoID"] = "Jp563BG-w",
["xOffset"] = 0,
["preferToUpdate"] = false,
["customText"] = "function()\n    local item = aura_env.item\n    \n    -- completion coloring\n    local color = aura_env.isComplete() and \"|cFFaad372\" or \"|cFFffffff\"\n    \n    -- fish count\n    local count = aura_env.config.weekly.crCount and item.Count .. \"/20\" or \"\"\n    \n    -- output\n    return color .. item.Name, color .. count\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["semver"] = "2.4.28",
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://wago.io/HalduDFHelper/151",
["actions"] = {
["start"] = {
["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region and region.state and region.state.show then\n    local color = region.state.color\n    region:Color(color[1]/255,color[2]/255,color[3]/255,.8)\n    WeakAuras.ScanEvents(\"HDH_FACTION\", region.state.event, 1)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local auraID, cloneID  = aura_env.id, aura_env.cloneId\n\nlocal region = WeakAuras.GetRegion(auraID, cloneID)\nif region then\n    WeakAuras.ScanEvents(\"HDH_MPLUS\", region.state.event, 0)\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.colors = {\n    [2507] = { 165, 73, 66 },\n    [2574] = { 37, 154, 151 },\n    [2564] = { 152, 106, 80 },\n    [2511] = { 104, 190, 255 },\n    [2510] = { 213, 169, 227 },\n    [2503] = { 239, 200, 69 }\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "START, CHAT_MSG_LOOT, UNIT_INVENTORY_CHANGED",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates)\n    \n    local cfg = aura_env.config.factions\n    \n    -- is this thing even on?\n    if not cfg.factionEnable then return end\n    \n    -- check which factions we care about\n    for key, value in pairs(cfg) do\n        \n        -- only care about factions (ignore other settings)\n        if tonumber(key) and value then\n            key = tonumber(key)\n            \n            -- grab information\n            local data = C_MajorFactions.GetMajorFactionData(key)\n            local name = string.match(data.name, \"^(.-)%-\") and string.match(data.name, \"^(.-)%-\") or data.name\n            local progress = cfg.percent and math.floor(data.renownReputationEarned / data.renownLevelThreshold * 100) .. \"%\" or data.renownReputationEarned .. \"/\" .. data.renownLevelThreshold\n            \n            -- build the bar\n            allstates[key] = {\n                show = true,\n                changed = true,\n                progressType = \"static\",\n                name = name,\n                index = name,\n                info = data.renownLevel .. \" (\" .. progress .. \")\",\n                value = data.renownReputationEarned,\n                total = data.renownLevelThreshold,\n                color = aura_env.colors[key],\n                event = key\n            }\n            \n        end\n    end\n    \n    return true\nend",
["custom_type"] = "stateupdate",
["check"] = "event",
["names"] = {
},
["unit"] = "player",
["customVariables"] = "\n\n",
