},
["init"] = {
["custom"] = "--code is a modified version of Korthia Checklist https://wago.io/cyRj6ikQz by Dorovon#1260 for the original todo lists in korthia\n-- Default Locale --\naura_env.defaultLocale = 'enUS'\n-- User Locale Var--\naura_env.userLocale = GetLocale()\n-- Get Text sinppet --\naura_env.get_text_snippet = function(name)\n  if aura_env.textSnippets[name] and aura_env.textSnippets[name][aura_env.userLocale] then\n    return aura_env.textSnippets[name][aura_env.userLocale]\n  end\n  if aura_env.textSnippets[name] and aura_env.textSnippets[name][aura_env.defaultLocale] then\n    return aura_env.textSnippets[name][aura_env.defaultLocale]\n  end\n  return name\nend\n-- World quest Availibility --\naura_env.is_world_quest_available = function(quest)\n  if not C_TaskQuest.GetQuestTimeLeftSeconds(quest) then\n    return true\n  end\n  return false\nend\n-- Quest Completion check --\naura_env.is_quest_completed = function(quest)\n  if C_QuestLog.IsQuestFlaggedCompleted(quest) then\n    return true\n  end\n  return false\nend\n\n-- Title items --\n--Norah#21256 thank you for French Tranlations\n--Beatrice#2650 & Podwiznaia#2373 thank you both for help with the Russian Translations\n--Shokuhou (Orillion), Lars, phoi thank you all for your japanese Translations\n--Shokuhou (Orillion) thank you for your Dutch Translations\n--Zamy thank you for your Koreran Translations\n--三皈依#3388 thank you for your Translations\n--hohunide thank you for your Translations\n--N3cro#92 thank you for your Translations\naura_env.textSnippets = {\n  overviewHeadline = { enUS = ' Todo list:',\n    deDE = 'Aufgabenliste:',\n    zhTW = '的任務列表: ', \n    zhCN = ' 任务列表:', \n    ruRU = 'Список дел ' ,\n    frFR = 'Liste de choses à faire :' ,\n    jaJP = 'タマのやること帳・ ',\n    koKR = '숙제 리스트 ',\n  },\n  \n  worldBoss = { \n    enUS = 'World Boss: ',\n    deDE = 'Weltboss: ',\n    zhTW = '世界首領', \n    zhCN = '世界BOSS: ',\n    ruRU = 'Мировой босс:',\n    frFR = 'Boss mondial: ',\n    nlNL = 'Wereld Baas',\n    jaJP = 'ワールドボス',\n    koKR = '필드보스',\n  },\n  \n  worldQuests = {\n    enUS = 'World Quests: ',\n    deDE = 'Welt-Quests: ',\n    zhTW = '世界任務', \n    zhCN = '世界任务: ',\n    ruRU = 'МЛокальные задания:',\n    frFR = 'Quêtes mondiales: ',\n    nlNL = 'World Quests',\n    jaJP = 'アコードを手伝う',\n    koKR = '전역 퀘스트',\n  },\n  \n  weeklyQuest = {\n    enUS = 'Aiding the Accord: ',\n    deDE = 'Unterstützung des Abkommens ',\n    zhTW = '支援協調者：', \n    zhCN = '协助援军： ',\n    ruRU = 'Содействие Соглашению: ',\n    frFR = 'Aider le concordat: ',\n    nlNL = 'Accord Assistentie',\n    jaJP='アコードを手伝う',\n    koKR = '협의회 지원',\n  },\n  \n  CommunityFeast = {\n    enUS = 'Community Feast: ',\n    deDE = ' Gemeinschaftliches Festmahl: ',\n    zhTW = '集體盛宴：', \n    zhCN = '社区盛宴： ',\n    ruRU = 'Большое пиршество: ',\n    frFR = 'Festin tribal:  ',\n    nlNL = 'Gemeenschap`s Feestmaal',\n    jaJP = 'コミュニティの宴会',\n    koKR = '공동체 잔치',\n  },\n  \n  elements = {\n    enUS = 'Trial of Elements: ',\n    deDE = 'Prüfung der Elemente:',\n    zhTW = '元素的試煉: ', \n    zhCN = '元素审判:  ',\n    ruRU = 'Испытание элементов: ',\n    frFR = 'L’épreuve des éléments: ',\n    nlNL = 'Test van de Elementen',\n    jaJP = '五大の試し',\n    koKR = '원소의 시험',\n  },\n  \n  flood = {\n    enUS = 'Trial of Flood: ',\n    deDE = 'Prüfung der Flut:',\n    zhTW = '洪流的試煉: ', \n    zhCN = '洪水的审判： ',\n    ruRU = 'Испытание наводнения: ', \n    frFR = 'L’épreuve du déluge:  ',\n    nlNL = 'Test van de Overstroming',\n    jaJP = '洪水の試し',\n    koKR = '홍수의 시험',\n  },\n  \n  SoDK = {\n    enUS = 'Siege of Dragonscale Keep: ',\n    deDE = 'Belagerung der Drachenfluchfestung: ',\n    zhTW = '攻打龍禍要塞： ', \n    zhCN = '围攻灭龙要塞: ',\n    ruRU = 'Осада драконьей погибели: ',\n    frFR = 'Siege du Fleau-des-dragons: ',\n    nlNL = 'Belegering van Fort Dragonscale',\n    jaJP =' ドラゴンスケール天守の包囲',\n    koKR = '용의 파멸 성채 공성전',\n  },\n  \n  Hunt = {\n    enUS = 'Grand Hunts: ',\n    deDE = 'Große Jagd: ',\n    zhTW = '大狩獵: ', \n    zhCN = '洪荒狩猎: ',\n    ruRU = 'Великая охота: ',\n    frFR = 'Grandes Chasses: ',\n    nlNL = 'Grootse Jachten',\n    jaJP = '盛大狩り',\n    koKR = '사냥의 제전',\n  },\n  Chests = {\n    enUS = 'Supply Chest (warmode): ',\n    deDE = 'Versorgungstruhe (Kriegsmodus): ',\n    zhTW = '补给箱（战争模式): ', \n    zhCN = '补给箱（战争模式): ',\n    ruRU = 'Сундук питания (теплоход): ',\n    frFR = 'Coffre d\\'approvisionnement (mode guerre): ',\n    nlNL = 'Forsyningskiste (krigstilstand):',\n    jaJP = '補給箱(ウォーモード)',\n    koKR = '보급 상자 (전쟁 모드)',\n  },\n  Chests = {\n    enUS = 'Sparks of life (warmode): ',\n    deDE = 'Sparks of life (warmode):  ',\n    zhTW = 'Sparks of life (warmode): ', \n    zhCN = 'Sparks of life (warmode):  ',\n    ruRU = 'Sparks of life (warmode): ',\n    frFR = 'Sparks of life (warmode): ',\n    nlNL = 'Sparks of life (warmode): ',\n    jaJP = 'Sparks of life (warmode): ',\n    koKR = 'Sparks of life (warmode): ',\n  },\n  Catalyst = {\n    enUS = 'Revival Catalyst: ',\n    deDE = 'Revival Catalyst: ',\n    zhTW = 'Revival Catalyst: ', \n    zhCN = 'Revival Catalyst: ',\n    ruRU = 'Revival Catalyst: ',\n    frFR = 'Revival Catalyst: ',\n    nlNL = 'Revival Catalyst: ',\n    jaJP = 'Revival Catalyst: ',\n    koKR = 'Revival Catalyst: ',\n  },\n}\n-- TODO - Items --\naura_env.todoList = {\n  {name = \"weeklyQuest\", maximum = 1,\n    quests = {\n      {questId = 70750,},--Aiding the Accord-- \n    },\n  },\n  \n  {name = \"Catalyst\", maximum = 1,\n    quests = {\n      {questId = 72528,},--revival-catalyst\n    },\n  },\n  \n  {name = \"CommunityFeast\",maximum = 1,\n    quests = {\n      {questId = 70893,},-- Hidden quest ID 70893--\n    },\n  },\n  \n  {name = \"SoDK\",maximum = 1,\n    quests = {\n      {questId = 70866,},-- confirm this Hidden ID72025 0r 70866--\n    },\n  },\n  \n  {name = \"Hunt\",maximum = 3,\n    quests = {\n      {questId = 70906,},\n      {questId = 71136,},\n      {questId = 71137,},\n    },\n  },\n  {name = \"flood\",maximum = 1,\n    quests = {\n      {questId = 71033,}, --Raging Torrent mobID 197221 hidden ID 71033 --\n    },\n  },\n  {name = \"elements\",maximum = 1,\n    quests = {\n      {questId = 71995,}, --Therrocite mob id 197749--\n    },\n  },\n  { name = \"worldBoss\",  maximum = 1,\n    quests = {\n      {questId = 69927,}, -- Bazual mobID 193532, hidden ID####--\n      {questId = 69928,},-- Liskanoth  mobID 193533, hidden ID####--\n      {questId = 69929,},-- Strunraan mobID 193534, hidden ID####--\n      {questId = 69930,},-- Basrikron mobID 193535, hidden ID####--\n      \n    },\n  },\n  {name = \"Chests\",maximum = 1,\n    quests = {\n      {questId = 72376,}, --Supply Chest (warmode)\n    },\n  },\n  {name = \"SparksOfLife\", maximum = 1,\n    quests = {\n      {questId = 72646,},--Sparks of Life: The Waking Shores\n      {questId = 72647,},--Sparks of Life: Ohn'ahran Plains\n      {questId = 72648,},--Sparks of Life: The Azure Span\n      {questId = 72649,},--Sparks of Life: Thaldraszus\n    },\n  },\n  \n  \n}\n\n--Output Varible--\naura_env.text = '';\n--Output Main function--\naura_env.update_overview_display = function()\n  local text = ''\n  --Include switchesCatalyst\n  local todov = aura_env.config.TD.showOverview\n  local wbv = aura_env.config.TD.includeWorldBoss\n  local Cfv = aura_env.config.TD.includeCommunityFeast\n  local elev = aura_env.config.TD.includeelements\n  local floodv = aura_env.config.TD.includeFlood\n  local SoDKv = aura_env.config.TD.includeSoDK\n  local huntv = aura_env.config.TD.includeHunt\n  local Catav = aura_env.config.TD.includeCatalyst\n  local Warv = aura_env.config.TD.includeWar\n  local WQv = aura_env.config.TD.includeWeeklyQuest\n  --Hide switches\n  local wbh = aura_env.config.TD.hide\n  local Cfh = aura_env.config.TD.hide\n  local eleh = aura_env.config.TD.hide\n  local floodh = aura_env.config.TD.hide\n  local SoDKh = aura_env.config.TD.hide\n  local hunth = aura_env.config.TD.hide\n  local WQh = aura_env.config.TD.hide\n  local Warh = aura_env.config.TD.hide\n  local Catah = aura_env.config.TD.hide\n  local tracking = 0\n  -----------------------------------------------------Todo list Prep--------------------------------------------------------------------------- \n  for _, todoEntry in ipairs(aura_env.todoList) do\n    -- PINK --\n    local entry, color, completed, maximum = '', 'ffff00ff', 0, #todoEntry.quests\n    if \n    --set up the items to displaySparksOfLife\n    todoEntry.name == 'SparksOfLife' and Warv or--Sparks of Life (warmode)--\n    todoEntry.name == 'Chests' and Warv or--Supply Chest (warmode)--\n    todoEntry.name == 'worldBoss' and wbv or -- world boss\n    todoEntry.name == 'CommunityFeast' and Cfv or-- Tuskarr Community Feast--\n    todoEntry.name == 'elements' and elev or--Trial of Elements --\n    todoEntry.name == 'flood' and floodv or--Trial of Floods --\n    todoEntry.name == 'SoDK' and SoDKv or--Siege of Dragonscale Keep --\n    todoEntry.name == 'Hunt' and huntv or--Grand Hunts\n    todoEntry.name == 'Catalyst' and Catav or--Catalyst\n    todoEntry.name == 'weeklyQuest' and WQv then--Aiding the Accord--\n      if todoEntry.maximum then\n        maximum = todoEntry.maximum\n      end\n      for _, todoQuest in ipairs(todoEntry.quests) do\n        if todoEntry.name == 'worldBoss' then\n          if aura_env.is_quest_completed(todoQuest.questId) then\n            completed = completed + 1\n            tracking = tracking +1\n          end\n        else\n          if aura_env.is_quest_completed(todoQuest.questId) then\n            completed = completed + 1\n            tracking = tracking +1\n          end\n        end\n      end\n      if (maximum > 1) and (completed >= (maximum / 2)) then\n        -- Burnt Orange --\n        color = 'ffff7801'\n      end \n      if completed >= maximum then\n        -- JADE--\n        color = 'FF00ff96'\n      end\n      \n      if completed >= maximum then\n        if\n        --check if the use wants to hide the line after complete\n        todoEntry.name == 'SparksOfLife' and Warv or--Sparks of Life (warmode)--\n        todoEntry.name == 'Chests' and not Warh  or--Supply Chest (warmode)--\n        todoEntry.name == 'worldBoss' and not wbh or-- world boss\n        todoEntry.name == 'CommunityFeast' and not Cfh or -- Tuskarr Community Feast--\n        todoEntry.name == 'elements' and not eleh or --Trial of Elements --\n        todoEntry.name == 'flood' and not floodh or --Trial of Floods --\n        todoEntry.name == 'SoDK' and not SoDKh or--Siege of Dragonscale Keep --\n        todoEntry.name == 'Hunt' and not hunth or --Grand Hunts --\n        todoEntry.name == 'Catalyst' and not Catah or--Catalyst\n        todoEntry.name == 'weeklyQuest' and not WQh then --Aiding the Accord--\n          \n          entry ='    ' ..  aura_env.get_text_snippet(todoEntry.name) .. ' ' .. WrapTextInColorCode(completed .. ' / ' .. maximum, color) .. '\\r\\n'\n        end\n      else\n        entry ='    ' .. aura_env.get_text_snippet(todoEntry.name) .. ' ' .. WrapTextInColorCode(completed .. ' / ' .. maximum, color) .. '\\r\\n'\n      end\n      \n      text = text .. entry\n    end\n  end\n  \n  return text\nend\n\n--Update output varible--\naura_env.update_display = function()\n  local text = ''\n  ---todo list items update---\n  if aura_env.config.TD.showOverview then -- cheack if use want to show\n    -- if tracking <5 then\n    text ='  ' .. text .. WrapTextInColorCode(aura_env.get_text_snippet('overviewHeadline'), 'ff00ff96') .. '\\r\\n'--apped header\n    --   end\n    text = text .. aura_env.update_overview_display() .. '\\r' --append todo list items\n  end \n  return text\nend\naura_env.text = aura_env.update_display()",
