["stop_sound"] = false,
},
},
["triggers"] = {
{
["trigger"] = {
["duration"] = "2",
["subeventPrefix"] = "SPELL",
["destUnit"] = "target",
["spellName"] = {
"Battle Stance",
},
["debuffType"] = "HELPFUL",
["names"] = {
},
["type"] = "custom",
["use_destNpcId"] = false,
["subeventSuffix"] = "_CAST_SUCCESS",
["custom_type"] = "stateupdate",
["unevent"] = "timed",
["event"] = "Combat Log",
["use_unit"] = true,
["custom"] = "function(states, e, ...)\n    if e == \"STATUS\" then\n        for i=1, 40 do\n            local u = \"nameplate\"..i\n            if UnitExists(u) then\n                local G = UnitGUID(u)\n                aura_env.nameplates[u] = G\n                aura_env.guids[G] = u\n            end\n        end\n    elseif e == \"NAME_PLATE_UNIT_ADDED\" then\n        local unit = ...\n        local updatestate = false\n        if unit then\n            local GUID = UnitGUID(unit)\n            aura_env.nameplates[unit] = GUID\n            aura_env.guids[GUID] = unit\n            for k, state in pairs(aura_env.temp) do\n                if state.GUID == GUID then\n                    if UnitAffectingCombat(unit)\n                    then\n                        state.unit = unit\n                        state.show = true\n                        state.changed = true\n                        states[k] = state  \n                        aura_env.temp[k] = nil\n                        updatestate = true\n                    else\n                        aura_env.units[GUID] = nil\n                        states[k] = nil\n                        aura_env.temp[k] = nil\n                        updatestate = true\n                    end\n                end\n            end\n            return updatestate\n        end\n        \n    elseif e == \"NAME_PLATE_UNIT_REMOVED\" then\n        local unit = ...\n        local updatestate = false\n        if unit then\n            local GUID = UnitGUID(unit)\n            if GUID then\n                aura_env.nameplates[unit] = nil\n                aura_env.guids[GUID] = nil\n                for k, state in pairs(states) do\n                    if state.GUID == GUID then\n                        aura_env.temp[k] = state\n                        state.show = false\n                        state.changed = true\n                        updatestate = true\n                    end\n                end\n                return updatestate\n            end\n        end\n        \n    elseif e == \"RELOE_SPELLCD_STATE_CLEAN_HL\" then\n        local key, expires = ...\n        if (states[key] and states[key].expirationTime == expires and states[key].expirationTime < GetTime ()) or (aura_env.temp[key] and aura_env.temp[key].expirationTime < GetTime()) then\n            states[key] = nil\n            aura_env.temp[key] = nil\n            return true\n            \n        end\n        \n    elseif e == \"RELOE_SPELLCD_STATE_UPDATE_HL\" then\n        local spell, GUID, spellID, duration, combat, type, count, key = ...\n        if spell and duration then\n            local current = GetTime()\n            local icon = spell.overwrite ~= 0 and select(3, GetSpellInfo(spell.overwrite)) or select(3, GetSpellInfo(spellID))\n            if--[[ ((not states[key]) or states[key].expirationTime < current + duration-0.1 or not spell.loop) \n            and ]](combat \n                or (not aura_env.last[GUID] )\n                or current > aura_env.last[GUID][1]+3 or icon ~= aura_env.last[GUID][2]) or spellID ~= aura_env.last[GUID][3] then\n                local data\n                local updatestate = false\n                \n                if duration <= 0 then \n                    states[key] = nil\n                    aura_env.temp[key] = nil\n                    return true\n                end\n                \n                data = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = duration ,\n                    spellID = spellID,\n                    expirationTime = GetTime() + duration,\n                    icon = icon,\n                    hide = spell.hide,\n                    autoHide = false,\n                    GUID = GUID,\n                    count = count,\n                    unit = aura_env.guids[GUID],\n                    spellId = spellID,\n                }\n                if spell.hide == 0 or spell.loop then\n                    data.autoHide = true\n                end\n                aura_env.last[GUID] = {current, icon, spellID}\n                if aura_env.guids[GUID] then\n                    states[key] = data\n                    updatestate = true\n                else\n                    aura_env.temp[key] = data\n                end\n                \n                if spell.loop and not combat then\n                    local aura_env = aura_env\n                    C_Timer.After(duration, function()\n                            if aura_env.guids[GUID] then\n                                WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE_HL\", spell, GUID, spellID, duration, combat, type, count, key) \n                            end\n                            \n                    end)\n                end\n                return updatestate\n            end\n        end\n    end\nend",
