{
["trigger"] = {
["type"] = "custom",
["custom"] = "function(event, npcId, autoMarkOption, markDistance, build, buildOption1, buildOption2, buildOption3, buildOption4, buildOption5, buildOption6, buildOption7, buildOption8)\n    aura_env.mobs[npcId] = {\n        [\"autoMarkOption\"] = autoMarkOption,\n        [\"distance\"] = markDistance,\n        [\"build\"] = build,\n        [\"prio\"] = {},\n    }\n    if build == 2 then \n        aura_env.partyMembers[aura_env.GetPlayerName()].build = 2 -- Player has a modified entry, give higher prio\n        aura_env.mobs[npcId].step = 1\n        local mark1, type1, next1 = strsplit(\":\", buildOption1)\n        local mark2, type2, next2 = strsplit(\":\", buildOption2)\n        local mark3, type3, next3 = strsplit(\":\", buildOption3)\n        local mark4, type4, next4 = strsplit(\":\", buildOption4)\n        local mark5, type5, next5 = strsplit(\":\", buildOption5)\n        local mark6, type6, next6 = strsplit(\":\", buildOption6)\n        local mark7, type7, next7 = strsplit(\":\", buildOption7)\n        local mark8, type8, next8 = strsplit(\":\", buildOption8)\n        \n        aura_env.mobs[npcId].prio = {\n            [1] = {\n                [\"mark\"] = mark1,\n                [\"type\"] = type1,\n                [\"next\"] = next1,\n            },\n            [2] = {\n                [\"mark\"] = mark2,\n                [\"type\"] = type2,\n                [\"next\"] = next2,\n            },\n            [3] = {\n                [\"mark\"] = mark3,\n                [\"type\"] = type3,\n                [\"next\"] = next3,\n            },\n            [4] = {\n                [\"mark\"] = mark4,\n                [\"type\"] = type4,\n                [\"next\"] = next4,\n            },\n            [5] = {\n                [\"mark\"] = mark5,\n                [\"type\"] = type5,\n                [\"next\"] = next5,\n            },\n            [6] = {\n                [\"mark\"] = mark6,\n                [\"type\"] = type6,\n                [\"next\"] = next6,\n            },\n            [7] = {\n                [\"mark\"] = mark7,\n                [\"type\"] = type7,\n                [\"next\"] = next7,\n            },\n            [8] = {\n                [\"mark\"] = mark8,\n                [\"type\"] = type8,\n                [\"next\"] = next8,\n            },\n        }\n    else\n        aura_env.mobs[npcId].prio = {\n            [1] = buildOption1,\n            [2] = buildOption2,\n            [3] = buildOption3,\n            [4] = buildOption4,\n        }\n    end\nend\n\n-- AUTOMARK_ADD_MOBS",
