["init"] = {
["custom"] = "local config = aura_env.config\n\naura_env.accepted = {}\n\naura_env.questIds = {\n    [57039] = config.Spirits, --精神谷\n    [57129] = config.Wisdom, --智慧谷\n    [57372] = config.Drag, --暗巷区\n    [57001] = config.Honor, --荣誉谷\n    \n    [57271] = config.Trade, --贸易区\n}",
