["unit"] = "player",
["events"] = "QUEST_ACCEPTED QUEST_LOG_UPDATE",
["spellIds"] = {
},
["names"] = {
},
["check"] = "event",
["custom"] = "function(e, ...)\n    if e == \"QUEST_ACCEPTED\" then\n        local _, questId = ...\n        if questId and aura_env.questIds[questId] then\n            aura_env.accepted[questId] = true\n        end\n    else\n        local text = \"\"\n        local flag = false\n        for questId, _ in pairs(aura_env.accepted) do\n            local objectives = C_QuestLog.GetQuestObjectives(questId)\n            if objectives and #objectives > 1 then\n                for _, objective in ipairs(objectives) do\n                    if objective and not objective.finished then\n                        text = text..objective.text..\"\\n\"\n                        flag = true\n                    end\n                end\n            end\n        end\n        if flag then\n            aura_env.text = text\n            return true\n        end\n    end\nend",
