["do_custom"] = false,
},
["finish"] = {
["custom"] = "",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.db = {\n    [\"name\"] = {\n        [\"enUS\"] = \"Crests\",\n        [\"koKR\"] = \"문장\",\n        [\"ruRU\"] = \"Гребни\",\n        [\"zhCN\"] = \"纹章\",\n        [\"zhTW\"] = \"紋章\"\n    },\n    [\"info\"] = {\n        [1] = { [\"color\"] = \"|cFF79ae7c\", [\"icon\"] = 5309872, [\"id\"] = 2706 },\n        [2] = { [\"color\"] = \"|cFF949eb5\", [\"icon\"] = 5309870, [\"id\"] = 2707 },\n        [3] = { [\"color\"] = \"|cFFfde458\", [\"icon\"] = 5309874, [\"id\"] = 2708 },\n        [4] = { [\"color\"] = \"|cFF8d7bd1\", [\"icon\"] = 5309868, [\"id\"] = 2709 }\n    }\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "START, CHAT_MSG_LOOT, BAG_UPDATE, QUEST_COMPLETE, QUEST_TURNED_IN, UNIT_INVENTORY_CHANGED, ITEM_COUNT_CHANGED, SKILL_LINES_CHANGED",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates)\n    \n    local cfg = aura_env.config.tracking\n    local db = aura_env.db\n    local name = db.name[GetLocale()] or db.name[\"enUS\"]\n    \n    -- is this thing even on?\n    if not cfg.trackingEnable or not cfg.crestEnable then return end\n    \n    -- build crest info\n    local info = \"\"\n    for _, x in ipairs(db.info) do\n        if cfg.crestIconEnable then\n            info = info .. x.color .. \"|T\" .. x.icon .. \":0|t \" .. C_CurrencyInfo.GetCurrencyInfo(x.id).quantity .. \"|r \"\n        else\n            info = info .. x.color .. C_CurrencyInfo.GetCurrencyInfo(x.id).quantity .. \"|r / \"\n        end\n    end\n    \n    -- strip last \"/\" from non-icon mode\n    if not cfg.crestIconEnable then info = info:sub(1, -4) end\n    \n    allstates[\"crests\"] = {\n        changed = true,\n        show = true,\n        name = name,\n        info = info\n    }\n    \n    return true\nend",
