["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["names"] = {
},
["spellIds"] = {
},
["events"] = "CLEU:SPELL_CAST_SUCCESS:UNIT_DIED, NAME_PLATE_UNIT_ADDED, NAME_PLATE_UNIT_REMOVED",
["custom_type"] = "stateupdate",
["check"] = "event",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"NAME_PLATE_UNIT_ADDED\"\n    and ... then\n        local guid = UnitGUID(...)\n        if guid\n        and aura_env.guids[guid] then\n            allstates[guid] = {\n                show = true,\n                changed = true,\n                unit = ...,\n            }\n            return true\n        end\n    end\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ...\n        if subEvent == \"SPELL_CAST_SUCCESS\" \n        and spellID == 23881\n        and sourceGUID == WeakAuras.myGUID\n        and not aura_env.guids[destGUID] then\n            aura_env.guids[destGUID] = true\n            local totalPlates = #C_NamePlate.GetNamePlates()\n            if totalPlates then\n                for i = 1, totalPlates do\n                    local plate = C_NamePlate.GetNamePlates()[i]\n                    if plate then\n                        local unit = plate.namePlateUnitToken\n                        local guid = UnitGUID(plate.namePlateUnitToken)\n                        if guid\n                        and guid == destGUID\n                        and unit then\n                            allstates[guid] = {\n                                show = true,\n                                changed = true,\n                                unit = unit,\n                            }\n                            return true\n                        end\n                    end\n                end\n            end\n        end\n        if subEvent == \"UNIT_DIED\" then\n            if aura_env.guids[destGUID] then\n                aura_env.guids[destGUID] = nil\n                if allstates[destGUID] then\n                    allstates[destGUID].show = false\n                    allstates[destGUID].changed = true\n                    return true\n                end\n            end\n        end\n    end\n    if event == \"NAME_PLATE_UNIT_REMOVED\"\n    and ... then\n        local guid = UnitGUID(...)\n        if guid\n        and allstates[guid] then\n            allstates[guid].show = false\n            allstates[guid].changed = true\n            return true\n        end\n    end\nend",
