["Item / Currency Tracking (HDH)"] = {
["sparkWidth"] = 10,
["iconSource"] = -1,
["wagoID"] = "Jp563BG-w",
["xOffset"] = 0,
["preferToUpdate"] = false,
["customText"] = "function()\n    local item = aura_env.item\n    \n    -- completion coloring\n    local color = aura_env.isComplete() and \"|cFFaad372\" or \"|cFFffffff\"\n    \n    -- fish count\n    local count = aura_env.config.weekly.crCount and item.Count .. \"/20\" or \"\"\n    \n    -- output\n    return color .. item.Name, color .. count\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["semver"] = "2.4.28",
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://wago.io/HalduDFHelper/151",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "",
["do_custom"] = false,
},
["init"] = {
["custom"] = "function aura_env.addCommas(n)\n    n = tostring(n)\n    return n:reverse():gsub(\"(%d%d%d)\", \"%1,\"):reverse():gsub(\"^,\", \"\")\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["use_unit"] = true,
["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "START, CHAT_MSG_LOOT, BAG_UPDATE, QUEST_COMPLETE, QUEST_TURNED_IN, UNIT_INVENTORY_CHANGED, ITEM_COUNT_CHANGED, SKILL_LINES_CHANGED",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates)\n    \n    local cfg = aura_env.config.tracking\n    local lang = GetLocale()\n    \n    -- is this thing even on?\n    if not cfg.trackingEnable then return end\n    \n    for i, db in pairs(cfg.tracked) do\n        if db.enable and db.id ~= 0 then\n            \n            local count, iconID, percent\n            if db.type == 1 then\n                count = (GetItemCount(db.id, true, true, true) or 0)\n                iconID = GetItemInfo(db.id) and select(10, GetItemInfo(db.id))\n                percent = \"\"\n            else\n                local c = C_CurrencyInfo.GetCurrencyInfo(db.id)\n                count = c.quantity or 0\n                iconID = c.iconFileID\n                percent = (cfg.showCap and c.maxQuantity > 0) and \" (\" .. math.floor(c.quantity / c.maxQuantity * 100) .. \"%)\" or \"\"\n                \n            end\n            \n            -- show icon?\n            local icon = (cfg.iconEnable and iconID) and \" |T\" .. iconID .. \":0|t\" or \"\"\n            \n            -- build the bar\n            if (cfg.hideMissing and count > 0) or not cfg.hideMissing then\n                allstates[db.id] = {\n                    autoHide = true,\n                    changed  = true,\n                    index    = i,\n                    info     = aura_env.addCommas(count) .. percent .. icon,\n                    name     = db.lang[lang] ~= \"\" and db.lang[lang] or db.name,\n                    show     = true,\n                    \n                    -- colors\n                    r = db.r / 255,\n                    g = db.g / 255,\n                    b = db.b / 255,\n                }\n            end\n        end\n    end\n    \n    return true   \nend",
["custom_type"] = "stateupdate",
["check"] = "event",
["names"] = {
},
["unit"] = "player",
["customVariables"] = "\n\n",
},
