["customVariables"] = "{\n    expirationTime = true,\n    duration = true,\n    value = true,\n    total = true,\n    stacks = true,\n    additionalProgress = 1,\n    index = {\n        display = \"Shard Number\",\n        type = \"number\"\n    },\n    soulStrike = {\n        display = \"Soul Strike Shard\",\n        type = \"bool\",\n    },\n    cost = {\n        display = \"Consuming Shards\",\n        type = \"bool\",\n    },\n    powerGain = {\n        display = \"Gaining Shards\",\n        type = \"bool\",\n    },\n    full = {\n        display = \"Max Shards\",\n        type = \"bool\",\n    },\n    spec = {\n        display = \"Specialization\",\n        type = \"select\",\n        values = {\n            [\"Affliction\"] = \"Affliction\",\n            [\"Demonology\"] = \"Demonology\",\n            [\"Destruction\"] = \"Destruction\",\n        }\n    },\n    totalPower = {\n        display = \"Soul Shards\",\n        type = \"number\",     \n    }\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["genericShowOn"] = "showOnActive",
