["unit"] = "player",
["subeventPrefix"] = "SPELL",
["custom"] = "function(a, event, unit, ...)\n    if event == \"UNIT_POWER_UPDATE\" and (...) ~= \"SOUL_SHARDS\"\n    then return true end\n    \n    local e = aura_env\n    local c = e.config\n    local math = math\n    \n    if event == \"TRAIT_CONFIG_UPDATED\"\n    or event == \"PLAYER_ENTERING_WORLD\" then \n        e.currentSpec = e.SpecUpdate(GetSpecialization())\n        e.checkPredict()\n    end\n    \n    if event == \"UNIT_SPELLCAST_START\" then\n        local _, spellID = ...\n        if spellID then\n            if e.generativeSpells[spellID] and c.predGain then\n                local gainAmount = e.generativeSpells[spellID]\n                e.powerGain = gainAmount\n                e.gaining = gainAmount\n            elseif c.predCost then\n                local spellCost = C_Spell.GetSpellPowerCost(spellID) and C_Spell.GetSpellPowerCost(spellID)[1]\n                if spellCost and spellCost.type == 7 then\n                    e.cost = spellCost.cost\n                    e.consuming = e.cost\n                end\n            end\n        end\n    end\n    if event == \"UNIT_SPELLCAST_STOP\" then\n        e.cost = 0\n        e.consuming = 0\n        e.powerGain = 0 \n        e.gaining = 0\n    end\n    if event == \"SPELL_UPDATE_USABLE\" and IsPlayerSpell(428344) and c.predSpellList[6] then\n        local spellCD = C_Spell.GetSpellCooldown(264057)\n        if spellCD.duration > 2 then\n            e.strikeCD = spellCD.startTime + spellCD.duration - GetTime()\n            e.expires = spellCD.startTime + spellCD.duration\n            e.strikeDur = spellCD.duration\n        end\n    end\n    local shards = UnitPower(\"player\", 7, true)*0.1\n    \n    if not IsSpellKnown(116858) then shards = math.floor(shards) end\n    local frags = shards - math.floor(shards)\n    e.consuming = shards >= e.cost and e.cost or shards\n    e.gaining = e.powerGain\n    local remains = shards - e.cost\n    local gains = shards + e.gaining\n    local gainType = e.cost > 0 and \"cost\" or \"gain\"\n    e.strikeCheck = false\n    for i = 1, 5 do\n        --Casting prediction\n        local min, max = 0, 0\n        if e.powerGain > 0 and i > math.floor(shards) and i < gains + 1 then\n            if frags == 0 or shards + e.gaining < gains and e.gaining > 1 then\n                min, max = 0, 1\n            elseif shards + e.gaining == gains then \n                min, max = shards - math.floor(shards), 1\n            else\n                min, max = 0, e.gaining\n            end\n            e.gaining = e.gaining - (max - min) >= 0 and e.gaining - (max - min) or 0 \n        elseif e.cost > 0 and i > remains and i < math.min(shards - 0.01) + 1 then\n            if frags == 0 or shards - e.consuming > remains and e.consuming > 1 then\n                min, max = 0, 1\n            elseif shards - e.consuming == remains then\n                min, max = remains - math.floor(remains), 1\n            else\n                min, max = 0, e.consuming\n            end\n            e.consuming = e.consuming - (max - min)\n        end\n        a[i] = a[i] or {}\n        a[i].totalPower = shards\n        a[i].show = true\n        a[i].changed = true\n        a[i].progressType = \"static\"\n        a[i].value = shards >= i and 1 or shards + 1 > i and frags or 0\n        a[i].total = 1\n        a[i].index = i\n        a[i].spec = e.currentSpec\n        a[i].cost = e.cost > 0\n        a[i].powerGain = e.powerGain > 0\n        a[i].full = shards == 5\n        a[i].soulStrike = false\n        a[i].additionalProgress = {\n            [1] = {min = min, max = max}\n        }\n        if IsPlayerSpell(428344) and e.strikeCD > 0 then\n            if i > shards and i > shards + e.powerGain and not e.strikeCheck then\n                e.strikeCheck = true\n                a[i].progressType = \"timed\" \n                a[i].expirationTime = e.expires\n                a[i].duration = e.strikeDur\n                a[i].soulStrike = true\n            end\n        end\n        a[i].name = e.FormatCount(i, shards, e.cost > 0 and e.cost or e.powerGain, gainType, e.soulStrike)\n    end \n    return true\nend",
