["init"] = {
["custom"] = "--------------------------------------------\n--            SOUL SHARDS BAR             --\n--         Made by Kirin & Ipse           --\n-- \"The headless pigmy has terrible aim.\" --\n--              :PeepoHappy:              --\n--------------------------------------------\n--       For FREE distribution ONLY       --\n--------------------------------------------\n\nlocal e = aura_env\nlocal c = e.config\nlocal r = e.region\n\ne.cost = 0\ne.consuming = 0\ne.powerGain = 0\ne.gaining = 0\ne.strikeCD = 0\ne.expires = 0\n\nlocal spec = {\n    [1] = \"Affliction\",\n    [2] = \"Demonology\",\n    [3] = \"Destruction\"\n}\n\nfunction e.SpecUpdate(SpecNumber)\n    return spec[SpecNumber]\nend\ne.currentSpec = e.SpecUpdate(GetSpecialization())\nfunction e.checkPredict()\n    --make default table \n    e.generativeSpells = {}\n    for n, toPred in ipairs(c.predSpellList) do\n        if n == 1 and toPred then\n            e.generativeSpells[434506] = IsPlayerSpell(116858) and 2 or 3\n        elseif n == 2 and toPred then\n            e.generativeSpells[264178] = 2\n        elseif n == 3 and toPred then\n            e.generativeSpells[6353] = 1\n        elseif n == 4 and toPred and IsPlayerSpell(449638) then\n            e.generativeSpells[386997] = 3 -- Soul Rot Gain\n        elseif n == 5 and toPred and IsPlayerSpell(449638) then\n            e.generativeSpells[265187] = 3 -- Tyrant Gain\n        elseif n == 7 and toPred and IsPlayerSpell(426115) then\n            e.generativeSpells[686] = 1 -- Shadow Bolt\n        end\n    end\nend\n-- Probably a nicer way of doing this but I don't care\nfunction e.FormatCount(pos, shards, consumed, gainType)\n    if not c.showText then\n        return \"\"\n    end\n    \n    local selected = c[e.currentSpec .. \"Text\"]\n    local match = c.shardCountOnMiddle and 3 or math.floor(shards - 0.1) + 1\n    local pred = c.predGain or c.predCost\n    \n    if pos ~= match then\n        return \"\"\n    end\n    \n    consumed = pred and consumed or 0\n    local adjustedShards = shards\n    \n    if gainType == \"cost\" and c.predCost then\n        consumed = math.min(consumed, shards)\n        adjustedShards = shards - consumed\n    elseif gainType == \"gain\" and c.predGain then\n        adjustedShards = math.min(shards + consumed, 5)\n    end\n    \n    local result\n    \n    if selected == 1 then -- \"Simple\"\n        result = adjustedShards\n    elseif selected == 2 then -- \"Full\"\n        result = string.format(\"%.1f\", adjustedShards)\n        if result == \"0.0\" then result = 0 end\n    elseif selected == 3 then -- \"Tenths\"\n        result = adjustedShards * 10\n    else\n        return \"\"\n    end\n    \n    if c.predWrap and consumed > 0 then\n        result = \"*\" .. result .. \"*\"\n    end\n    \n    return tostring(result)\nend\ne.checkPredict()\ne.format = string.format\n\n",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
