["init"] = {
["custom"] = "aura_env.db = { }\n\n-- transliteration\naura_env.langDB = {\n    \n    -- Chinese (Simplified)\n    [\"zhCN\"] = \"每周任务\",\n    \n    -- Chinese (Taiwan)\n    [\"zhTW\"] = \"每週任務\",\n    \n    -- English (US)\n    [\"enUS\"] = \"Weekly\",\n    \n    -- French (FR)\n    [\"frFR\"] = \"Hebdomadaire\",\n    \n    -- German\n    [\"deDE\"] = \"Wöchentlich\",\n    \n    -- Korean (KR)\n    [\"koKR\"] = \"주간\",\n    \n    -- Russian (RU)\n    [\"ruRU\"] = \"Еженедельный\",\n}",
