["wagoID"] = "yaN0dfXwd",
["parent"] = "S4-Bars (trash timers)",
["customText"] = "function() if WeakAuras.IsOptionsOpen() then return ICON_LIST[math.random(1,8)]..\"16|t\" end end",
["sparkRotationMode"] = "AUTO",
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_hide"] = "timed",
["custom_type"] = "stateupdate",
["customVariables"] = "{expirationTime=true, timer_refreshed=\"bool\"}",
["duration"] = "7.4",
["event"] = "Combat Log",
["subeventPrefix"] = "SPELL",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, ...)\n    if event == \"FRAME_UPDATE\" then\n        --blizzard pls add better events for proximity pulled mobs\n        if not aura_env.last or aura_env.last < GetTime() - 0.5 then\n            aura_env.last = GetTime()\n            for guid, state in pairs(allstates) do\n                if (state.expirationTime < aura_env.last)\n                and (state.expirationTime < aura_env.last - 3) then\n                    if aura_env.timer[guid] then\n                        aura_env.timer[guid]:Cancel()\n                        aura_env.timer[guid] = nil\n                    end\n                    state.show = false\n                    state.changed = true\n                    return true\n                end\n            end\n            for _, plate in pairs(C_NamePlate.GetNamePlates()) do\n                local unit = plate.namePlateUnitToken\n                local guid = UnitGUID(unit)\n                if guid then\n                    local npcID = select(6, strsplit(\"-\", guid))\n                    if npcID\n                    and (npcID == \"196115\" or npcID == \"191164\")\n                    and UnitAffectingCombat(unit)\n                    and not (aura_env.timer[guid] ~= nil or allstates[guid]) then\n                        local mark = GetRaidTargetIndex(unit)\n                        allstates[guid] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"timed\",\n                            duration = 5.3,\n                            expirationTime = 5.3 + GetTime(),\n                            timer_refreshed = false,\n                            mark = (mark and ICON_LIST[mark]..\"16|t\") or \"\",\n                        }\n                        aura_env.timer[guid] = false\n                        return true\n                    end\n                end\n            end\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ...\n        if subEvent == \"UNIT_DIED\" then\n            if aura_env.timer[destGUID] then\n                aura_env.timer[destGUID]:Cancel()\n                aura_env.timer[destGUID] = nil\n            end\n            local state = allstates[destGUID]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local unit, _, spellID = ...\n        if spellID == 375596 then\n            local sourceGUID = UnitGUID(unit)\n            aura_env.timer[sourceGUID] = C_Timer.NewTimer(0, function() WeakAuras.ScanEvents(\"CAUSESE_TIMER\", sourceGUID, spellID) end)\n            local state = allstates[sourceGUID]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    elseif event == \"CAUSESE_TIMER\" and ... then\n        local guid, spellID = ...\n        if spellID == 375596 then\n            local unit = UnitTokenFromGUID(guid)\n            if unit and UnitAffectingCombat(unit) then\n                local mark = GetRaidTargetIndex(unit)\n                allstates[guid] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 23.1,\n                    expirationTime = 23.1 + GetTime(),\n                    timer_refreshed = true,\n                    mark = (mark and ICON_LIST[mark]..\"16|t\") or \"\",\n                    autoHide = true,\n                }\n                return true\n            end\n        end\n    elseif event == \"CHALLENGE_MODE_START\" then\n        aura_env.timer = {}\n    elseif event == \"RAID_TARGET_UPDATE\" then\n        for guid, state in pairs(allstates) do\n            local unit = UnitTokenFromGUID(guid)\n            if unit then\n                local mark = GetRaidTargetIndex(unit)\n                state.mark = (mark and ICON_LIST[mark]..\"16|t\") or \"\"\n                state.changed = true\n            end\n        end\n        return true\n    end\nend",
["events"] = "CHALLENGE_MODE_START, FRAME_UPDATE, CLEU:UNIT_DIED, UNIT_SPELLCAST_SUCCEEDED:nameplate, CAUSESE_TIMER, RAID_TARGET_UPDATE",
