["sparkRotation"] = 0,
["url"] = "https://wago.io/HalduDFHelper/151",
["actions"] = {
["start"] = {
["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region and region.state and region.state.show then\n    aura_env.regions[aura_env.cloneId] = region\n    WeakAuras.ScanEvents(\"HDH_ACTIVITY\", region.state.event, 1)\nend\n\n\n\n",
["do_sound"] = true,
["sound_kit_id"] = "9432",
["do_custom"] = true,
["sound"] = " KitID",
},
["finish"] = {
["custom"] = "local region = WeakAuras.GetRegion(aura_env.id, aura_env.cloneId)\nif region then\n    WeakAuras.ScanEvents(\"HDH_ACTIVITY\", region.state.event, 0)\nend\n\nif aura_env.regions[aura_env.cloneId] then\n    aura_env.regions[aura_env.cloneId] = nil\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.regions = {}\n\naura_env.db = {\n    -- Cascades Calling\n    [75612] = {\n        [\"name\"] = {\n            --[\"enUS\"] = \"Cascades Calling\",\n            [\"zhCN\"] = \"涌流召唤\",\n            [\"zhTW\"] = \"流瀑呼喚\",\n        },\n        [\"text\"] = {\n            --[\"enUS\"] = \"\",\n            [\"zhCN\"] = \"拜荒者开始从飞瀑之柱里召唤某些大型生物了！\",\n            [\"zhTW\"] = \"洪荒使者開始在流瀑之柱召喚大傢伙了！\",\n        },\n        [\"coords\"] = { [\"x\"] = 44.65, [\"y\"] = 75.15 }\n    },\n    \n    -- Champion's Challenge\n    [75624] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Champion's Challenge\",\n            [\"zhTW\"] = \"勇士的挑戰\",\n            [\"zhCN\"] = \"勇士的挑战\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"A weightlifting competition is about to begin in Glimmerogg!\",\n            [\"zhTW\"] = \"有場舉重比賽即將在葛利姆羅格舉行！\",\n            [\"zhCN\"] = \"举重比赛即将在格里梅罗格开始！\",\n        },\n        [\"coords\"] = { [\"x\"] = 44.97, [\"y\"] = 82.52 }\n    },\n    \n    -- Conspiracy of Flames\n    [75455] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Conspiracy of Flames\",\n            [\"zhCN\"] = \"烈焰阴谋\",\n            [\"zhTW\"] = \"火焰陰謀\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"Ancient djaradin chants echo from the caldera...\",\n            [\"zhCN\"] = \"上古贾拉丁魔咒回响在喷口……\",\n            [\"zhTW\"] = \"遠古加拉登的吟唱聲在火山口迴盪著...\",\n        },\n        [\"coords\"] = { [\"x\"] = 32.1, [\"y\"] = 42.7 }\n    },\n    \n    -- Crystalline Survey\n    [75471] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Crystalline Survey\",\n            [\"zhCN\"] = \"晶脉勘测\",\n            [\"zhTW\"] = \"晶化勘察\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"The sound of crystals ringing echoes through the cavern. The geological survey is about to begin near the Throughway!\",\n            [\"zhCN\"] = \"水晶的嗡鸣声在整个洞窟中回响，地质调查即将在直达通路开始！\",\n            [\"zhTW\"] = \"水晶的聲音在洞穴中響起迴音。這場地質勘察即將在連通道附近展開！\",\n        },\n        [\"coords\"] = { [\"x\"] = 63.04, [\"y\"] = 47.25 }\n    },\n    -- Discordant Crystals\n    [75664] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Discordant Crystals\",\n            [\"zhCN\"] = \"不谐水晶\",\n            [\"zhTW\"] = \"紛亂水晶\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"The delicate natural song of the cavern is disrupted by violent, discordant notes!\",\n            [\"zhCN\"] = \"洞窟中精妙的天然乐曲被剧烈的不谐音符扰乱了！\",\n            [\"zhTW\"] = \"洞穴優美的天然歌曲被刺耳、不和諧的音符干擾！\",\n        },\n        [\"coords\"] = { [\"x\"] = 56.56, [\"y\"] = 65.66 }\n    },\n    \n    -- Glimmerfish\n    [75611] = {\n        [\"name\"] = {\n            --[\"enUS\"] = \"Glimmerfish\",\n            --[\"zhCN\"] = \"马上就会消失的巨型微光鱼\",\n            [\"zhTW\"] = \"在微光魚消失前\"\n        },\n        [\"text\"] = {\n            --[\"enUS\"] = \"\",\n            --[\"zhCN\"] = \"\",\n            [\"zhTW\"] = \"有人在葛利姆羅格附近看到一隻超大的魚！\",\n        },\n        [\"coords\"] = { [\"x\"] = 46.42, [\"y\"] = 86.77 }\n    },\n    \n    -- Hungry Hungry Hydra\n    [75478] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Hungry Hungry Hydra\",\n            [\"zhCN\"] = \"饥肠辘辘的多头蛇\",\n            [\"zhTW\"] = \"飢腸轆轆的多頭蛇\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"A starving hydra emerges from the lava, looking for a quick meal!\",\n            [\"zhCN\"] = \"饥肠辘辘的多头蛇从熔岩里浮现，准备大快朵颐！\",\n            [\"zhTW\"] = \"飢餓的多頭蛇從熔岩中鑽出，想要飽餐一頓！\",\n        },\n        [\"coords\"] = { [\"x\"] = 46.8, [\"y\"] = 23.9 }\n    },\n    \n    -- Imperfect Balance\n    [75451] = {\n        [\"name\"] = {\n            --[\"enUS\"] = \"Imperfect Balance\",\n            [\"zhCN\"] = \"不完美平衡\",\n            [\"zhTW\"] = \"不完美平衡\"\n        },\n        [\"text\"] = {\n            --[\"enUS\"] = \"\",\n            [\"zhCN\"] = \"一阵恶毒的咆哮回荡在喷口。\",\n            [\"zhTW\"] = \"兇惡的咆哮迴盪在整個火山口。\",\n        },\n        [\"coords\"] = { [\"x\"] = 35.2, [\"y\"] = 51.4 }\n    },\n    \n    -- Magmaclaw Matriarch\n    [75461] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Magmaclaw Matriarch\",\n            [\"zhCN\"] = \"岩浆爪主母\",\n            [\"zhTW\"] = \"熔岩爪族母\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"A spawning swarm of magmaclaws begins to form, threatening the ecological balance of the caverns!\",\n            [\"zhCN\"] = \"一群增殖的岩浆爪开始聚集，洞窟的生态平衡岌岌可危！\",\n            [\"zhTW\"] = \"一整群的熔岩爪開始出現，威脅到洞穴的生態平衡！\",\n        },\n        [\"coords\"] = { [\"x\"] = 48.4, [\"y\"] = 23.6 }\n    },\n    \n    -- Mortar Warfare\n    [75454] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Mortar Warfare\",\n            [\"zhCN\"] = \"迫击战事\",\n            [\"zhTW\"] = \"迫擊砲戰爭\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"War cries erupt from the caldera as the djaradin begin to assemble their ballistae.\",\n            [\"zhCN\"] = \"战吼声在喷口中此起彼伏，贾拉丁开始组装他们的弩炮。\",\n            [\"zhTW\"] = \"火山口傳出響亮的戰吼，加拉登族開始排列他們的弩砲。\",\n        },\n        [\"coords\"] = { [\"x\"] = 40.32, [\"y\"] = 43.53 }\n    },\n    \n    -- Seismic Ceremony\n    [75450] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Seismic Ceremony\",\n            [\"zhCN\"] = \"地震仪式\",\n            [\"zhTW\"] = \"震地儀式\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"The caldera begins to rumble...\",\n            [\"zhCN\"] = \"喷口开始震动……\",\n            [\"zhTW\"] = \"火山口開始隆隆作響…\",\n        },\n        [\"coords\"] = { [\"x\"] = 34.39, [\"y\"] = 47.10 }\n    },\n    \n    -- Shellfire\n    [75222] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Shellfire\",\n            [\"zhCN\"] = \"螺火\",\n            [\"zhTW\"] = \"火燒殼\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"A fire elemental approaches Olfor and Big Bessie!\",\n            [\"zhCN\"] = \"一个火元素靠近了欧尔弗尔和大个子贝西！\",\n            [\"zhTW\"] = \"個火元素就要接近歐弗爾與大貝茜了！\",\n        },\n        [\"coords\"] = { [\"x\"] = 57.46, [\"y\"] = 49.38 }\n    },\n    \n    -- Smellincense\n    [75370] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Smellincense\",\n            [\"zhTW\"] = \"惡臭薰香\",\n            [\"zhCN\"] = \"臭香\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"Delvert is starting to heat up his smelly pot by Deephollow Lake!\",\n            [\"zhTW\"] = \"戴維特開始在深谷湖旁將他發臭的鍋子加熱！\",\n            [\"zhCN\"] = \"德尔威特开始在深洼湖旁加热难闻的罐子。\",\n        },\n        [\"coords\"] = { [\"x\"] = 60.54, [\"y\"] = 52.79 }\n    },\n    \n    -- Smelly Scramble\n    [75441] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Smelly Scramble\",\n            [\"zhCN\"] = \"恶臭急行\",\n            [\"zhTW\"] = \"臭雜燴\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"Muskmettle the Smellomancer is getting ready to brew!\",\n            [\"zhCN\"] = \"香术士麝梅特准备开始酿造了！\",\n            [\"zhTW\"] = \"『臭氣使者』穆斯梅托準備好釀造了！\",\n        },\n        [\"coords\"] = { [\"x\"] = 57.67, [\"y\"] = 57.21 }\n    },\n    \n    --Stress Express\n    [75156] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Stress Express\",\n            --[\"zhTW\"] = \"\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"Doopurt's wagon broke down in the Throughway!\",\n            --[\"zhTW\"] = \"\",\n        },\n        [\"coords\"] = { [\"x\"] = 64.5, [\"y\"] = 51.4 }\n    },\n    \n    -- Strike the Colors\n    [75494] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Strike the Colors\",\n            [\"zhCN\"] = \"倒戈卸甲\",\n            [\"zhTW\"] = \"五彩出擊\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"Neltharion loyalists unfurl giant banners proclaiming their loyalty to Deathwing's memory!\",\n            [\"zhCN\"] = \"奈萨里奥的死忠扬起巨大的战旗，宣称自己效忠于死亡之翼的回忆。\",\n            [\"zhTW\"] = \"奈薩里奧忠誠者展開巨大的旗幟，宣示他們效忠於死亡之翼的遺志！\",\n        },\n        [\"coords\"] = { [\"x\"] = 45.17, [\"y\"] = 20.90 }\n    },\n    \n    -- Whirling Zephyr\n    [74352] = {\n        [\"name\"] = {\n            [\"enUS\"] = \"Whirling Zephyr\",\n            [\"zhCN\"] = \"回旋的西风\",\n            [\"zhTW\"] = \"迴旋的輕風\",\n        },\n        [\"text\"] = {\n            [\"enUS\"] = \"The air hums with energy as the Primalists begin summoning a storm!\",\n            [\"zhCN\"] = \"能量在空气中嗡鸣，拜荒者开始召唤一场风暴！\",\n            [\"zhTW\"] = \"當洪荒使者開始召喚風暴時，空氣裡充滿了能量！\",\n        },\n        [\"coords\"] = { [\"x\"] = 58.16, [\"y\"] = 67.94 }\n    },\n    \n    --[\"Monument Maintenance\"] = \"\", ## NO ANNOUNCEMENT\n}",
["do_custom"] = true,
},
