["custom_hide"] = "custom",
["event"] = "Conditions",
["events"] = "CHAT_MSG_MONSTER_EMOTE, GLOBAL_MOUSE_UP",
["customDuration"] = "function()\n    return 0, 100, true\nend",
["spellIds"] = {
},
["custom"] = "function(allstates, event, ...)\n    \n    local cfg = aura_env.config.activities\n    local db = aura_env.db\n    local lang = GetLocale()\n    if not cfg.activityEnable or not cfg.zaralekCaverns then return end\n    \n    if event == \"GLOBAL_MOUSE_UP\" and ... then\n        local button = ...\n        if button == \"LeftButton\" then\n            \n            if IsControlKeyDown() then\n                for cloneID, region in pairs(aura_env.regions) do\n                    local over = MouseIsOver(region.icon)\n                    if over and allstates[cloneID] then\n                        local x, y = allstates[cloneID].X, allstates[cloneID].Y\n                        if x ~= 0 and y ~=0 then\n                            \n                            if IsAddOnLoaded(\"TomTom\") then\n                                local TomTom = TomTom\n                                TomTom:AddWaypoint(2133, x/100, y/100, {title=allstates[cloneID].name,from=\"WA_Haldu\"})\n                            else\n                                C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(2133, x/100, y/100, 0))\n                                C_SuperTrack.SetSuperTrackedUserWaypoint(true)\n                            end\n                        end\n                        break\n                    end\n                end\n            end\n            \n            -- Clear map pins\n        elseif button == \"RightButton\" and IsControlKeyDown() then\n            for cloneID, region in pairs(aura_env.regions) do\n                local over = MouseIsOver(region.icon)\n                if over and allstates[cloneID] then\n                    if IsAddOnLoaded(\"TomTom\") then\n                        local TomTom = TomTom\n                        TomTom.waydb:ResetProfile()\n                    else\n                        C_Map.ClearUserWaypoint()\n                    end\n                    break\n                end\n            end\n        end\n        \n    elseif event == \"CHAT_MSG_MONSTER_EMOTE\" then\n        local name = \"\"\n        local x,y = 0,0\n        local text = ...\n        \n        for _, info in pairs(db) do\n            local l = info.text[lang] or info.text[\"enUS\"]\n            if text == l then\n                name = info.name[lang] or info.name[\"enUS\"]\n                x = info.coords.x\n                y = info.coords.y\n            end\n        end\n        \n        if name == \"\" then return end\n        \n        allstates[name] = {\n            autoHide = true,\n            changed = true,\n            show = true,\n            name = name,\n            progressType = \"timed\",\n            duration = 120,\n            expiration = GetTime() + 120,\n            X = x,\n            Y = y,\n            tooltip = name .. \" (Zaralek Caverns)|n|nControl + Left Click to create a waypoint.\",\n            event = name,\n        }\n        \n        return true\n    end\nend\n\n\n",
