["custom"] = "function(states, event, ...)\n    if event == \"OPTIONS\" or event == \"STATUS\" then\n        local mapID = event == \"OPTIONS\" and 2403 or C_Map.GetBestMapForUnit(\"player\")\n        for i=1, 5 do\n            local key = format(\"%s-chest\", i)              \n            states:Update(key, {\n                    name = aura_env.names[mapID][i],\n                    ICON = i == 1 and \"|A:delves-scenario-treasure-available:0:0|a\" or \"\",\n                    value = 0,\n                    total = i == 1 and 3 or 2,\n                    index = i,\n                    progressType = \"static\",\n            })\n        end\n        if aura_env.config.crystals then\n            for i=1, 5 do\n                local key = format(\"%s-crystal\", i) \n                states:Update(key, {\n                        ICON = i == 1 and \"|A:poi-nzothpylon:0:0|a\" or \"\",\n                        value = 0,\n                        total = 2,\n                        index = 5+i,\n                        progressType = \"static\",\n                })\n            end\n            states:Update(\"spoils\", {\n                    name = format(\"|T%s:14|tSpoils\", 132053),\n                    value = 0,\n                    total = 1,\n                    index = 11,\n                    progressType = \"static\",\n            })\n        end\n    elseif event == \"UNIT_SPELLCAST_START\" and ... then\n        local unit, _, spellID = ...\n        if spellID == 143394 then --crystal/mount stuff\n            local tooltip = C_TooltipInfo.GetWorldCursor()\n            if tooltip and tooltip.lines then\n                local text = tooltip.lines[1].leftText\n                if text:match(aura_env.locale) then\n                    aura_env.crystal = true\n                    return\n                end\n            end\n            \n            local interact = UnitGUID(\"softinteract\")\n            if interact then\n                local id = select(6, strsplit(\"-\", interact))\n                if id == \"341367\" then\n                    aura_env.crystal = true\n                    return\n                end\n            end\n        end\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" and ... then\n        local unit, _, spellID = ...\n        if spellID == 306608 then --cache \n            aura_env.chestOpened = true\n        elseif spellID == 143394 and aura_env.crystal then --crystal/mount stuff\n            local quartal = aura_env.GetLocation()\n            local key = quartal and format(\"%s-crystal\", quartal)\n            if quartal then\n                if states[key] then\n                    local value = states[key].value + 1\n                    value = value > states[key].total and states[key].total or value\n                    states:Update(key, {value = value})\n                end\n                \n                local message = format(\"%s*%s*%s\", quartal, UnitGUID(\"player\"), key)\n                C_ChatInfo.SendAddonMessage(\"TVISIONS_LOOT\", message, \"INSTANCE_CHAT\")\n                aura_env.crystal = false\n            end\n        end\n    elseif event == \"UNIT_SPELLCAST_STOP\" and ... and aura_env.crystal then\n        aura_env.crystal = false \n    elseif event == \"LOOT_READY\" and ... then\n        local icon, _, _, currencyType = GetLootSlotInfo(1)\n        if icon == 646678 and (currencyType == 1744 or currencyType == 3149) then\n            aura_env.mementos = true\n        end\n    elseif event == \"LOOT_SLOT_CLEARED\" and aura_env.chestOpened and aura_env.mementos then\n        local spoils = aura_env.GetSpoilsLocation()\n        if spoils and states[\"spoils\"] then\n            states:Update(\"spoils\", {value = 1})\n            aura_env.mementos = false \n            aura_env.chestOpened = false \n            aura_env.last = nil\n        else\n            local quartal = aura_env.GetLocation()\n            local key = quartal and format(\"%s-chest\", quartal)\n            if quartal then\n                if states[key] then\n                    local value = states[key].value + 1\n                    value = value > states[key].total and states[key].total or value\n                    states:Update(key, {value = value})\n                end\n                \n                local message = format(\"%s*%s*%s\", quartal, UnitGUID(\"player\"), key)\n                C_ChatInfo.SendAddonMessage(\"TVISIONS_LOOT\", message, \"INSTANCE_CHAT\")\n                aura_env.mementos = false \n                aura_env.chestOpened = false\n                aura_env.last = nil\n            end\n        end\n    elseif event == \"LOOT_CLOSED\" and aura_env.chestOpened then\n        aura_env.mementos = false\n        aura_env.chestOpened = false\n        aura_env.last = GetTime()\n    elseif event == \"CURRENCY_DISPLAY_UPDATE\" and aura_env.last then\n        local currencyType, quantity, quantityChange, quantityGainSource, destroyReason = ...\n        \n        if (currencyType == 1744 or currencyType == 3149)\n        and quantityGainSource == 9\n        and destroyReason == 16\n        and (GetTime() - aura_env.last) < 1 \n        then\n            local spoils = aura_env.GetSpoilsLocation()\n            if spoils and states[\"spoils\"] then\n                states:Update(\"spoils\", {value = 1})\n                aura_env.last = nil\n            else\n                local quartal = aura_env.GetLocation()\n                local key = quartal and format(\"%s-chest\", quartal)\n                if quartal then\n                    if states[key] then\n                        local value = states[key].value + 1\n                        value = value > states[key].total and states[key].total or value\n                        states:Update(key, {value = value})\n                    end\n                    \n                    local message = format(\"%s*%s*%s\", quartal, UnitGUID(\"player\"), key)\n                    C_ChatInfo.SendAddonMessage(\"TVISIONS_LOOT\", message, \"INSTANCE_CHAT\")\n                    aura_env.last = nil\n                end\n            end\n        end\n    elseif event == \"CHAT_MSG_ADDON\" then\n        local prefix, message, channel = ...\n        if prefix == \"TVISIONS_LOOT\" and message and channel == \"INSTANCE_CHAT\" then\n            local quartal, GUID, key = strsplit(\"*\", message)\n            if quartal and GUID ~= UnitGUID(\"player\") and states[key] then --cba comapring sender field \n                local value = states[key].value + 1\n                value = value > states[key].total and states[key].total or value \n                states:Update(key, {value = value})\n            end\n        end\n    end\nend\n\n\n",
