["init"] = {
["custom"] = "C_ChatInfo.RegisterAddonMessagePrefix(\"TVISIONS_LOOT\")\n\naura_env.names = {\n    [1469] = {\n        \"Strength\",\n        \"Spirits\",\n        \"Wisdom\",\n        \"Drag\",\n        \"Honor\",\n    },\n    [2403] = {\n        \"Strength\",\n        \"Spirits\",\n        \"Wisdom\",\n        \"Drag\",\n        \"Honor\",\n    },\n    [1470] = {\n        \"Cathedral\",\n        \"Dwarven D\",\n        \"Old Town\",\n        \"Trade D\",\n        \"Mage Q\",\n    },\n    [2404] = {\n        \"Cathedral\",\n        \"Dwarven D\",\n        \"Old Town\",\n        \"Trade D\",\n        \"Mage Q\",\n    },\n}\n\naura_env.visions = {\n    [2403] = { --Orgrimmar\n        { --The Valley of Strength\n            {43.74, 64.27},\n            {47.72, 87.79},\n            {58.38, 86.36},\n            {53.44, 67.78},\n            {49.11, 59.98},\n        },\n        { --The Valley of Spirits\n            {21.99, 62.97},\n            {25.54, 72.84},\n            {35.59, 90.26},\n            {43.39, 85.58},\n            {42.09, 63.36},\n            {36.81, 58.68},\n        },\n        { --The Valley of Wisdom\n            {38.54, 38.02},\n            {35.51, 55.22},\n            {53.01, 57.38},\n            {53.79, 40.10},\n        },\n        { --The Drag\n            {52.49, 60.50},\n            {55.00, 68.43},\n            {65.31, 60.89},\n            {59.51, 45.03},\n            {55.69, 45.42},\n            {53.44, 51.92},\n            {54.83, 59.98},\n        },\n        { --The Valley of Honor\n            {60.72, 43.73},\n            {65.92, 56.08},\n            {77.53, 49.06},\n            {77.53, 28.14},\n            {65.22, 25.41},\n            {59.51, 30.09},\n        },\n    },\n    [2404] = { --Stormwind\n        {--Stormwind Cathedral\n            {43.81, 50.47},\n            {51.94, 65.89},\n            {63.18, 54.95},\n            {55.89, 40.06},\n        },\n        { --The Dwarven District\n            {55.64, 31.64},\n            {65.45, 52.98},\n            {72.98, 43.65},\n            {66.04, 23.39},\n        },\n        { --Old Town\n            {66.16, 56.74},\n            {78.24, 75.93},\n            {85.89, 64.28},\n            {75.85, 47.50},\n        },\n        { --Trade District\n            {54.93, 67.32},\n            {61.62, 82.93},\n            {71.66, 73.60},\n            {64.49, 59.07},\n        },\n        { --The Mage Quarter\n            {37.11, 79.34},\n            {46.68, 97.99},\n            {60.07, 85.08},\n            {52.65, 67.50},\n        },\n    },\n}\n--BFA Visions\naura_env.visions[1469] = aura_env.visions[2403]\naura_env.visions[1470] = aura_env.visions[2404]\n\naura_env.spoils = {\n    [2403] = { --Orgrimmar\n        {55.22, 69.46},\n        {52.86, 70.94},\n        {53.80, 71.51},\n        {55.22, 70.91},\n    },\n    [2404] = { --Stormwind\n        {57.54, 47.38},\n        {56.89, 48.13},\n        {57.28, 48.89},\n        {57.94, 48.26},\n    },\n}\n\naura_env.spoils[1469] = aura_env.spoils[2403]\naura_env.spoils[1470] = aura_env.spoils[2404]\n\nlocal isInside = function(location, x, y)\n    local inside = false\n    local total = #location \n    \n    for i = 1, total do \n        local j = (i % total) + 1 --Next vertex (wraps around)\n        local xi, yi = location[i][1], location[i][2]\n        local xj, yj = location[j][1], location[j][2]\n        \n        --Check if the point is on an edge\n        if (xi == xj and x == xi and y >= math.min(yi, yj) and y <= math.max(yi, yj))\n        or (yi == yj and y == yi and x >= math.min(xi, xj) and x <= math.max(xi, xj))\n        then\n            return true  --On the edge\n        end\n        \n        --Ray-casting check\n        if (yi > y) ~= (yj > y) then\n            local intersect = (xj - xi) * (y - yi) / (yj - yi) + xi\n            if x <= intersect then\n                inside = not inside\n            end\n        end\n    end\n    --print(\"inside\", inside)\n    return inside\nend\n\naura_env.GetLocation = function()\n    local mapID = C_Map.GetBestMapForUnit(\"player\")\n    local current = aura_env.visions[mapID]\n    if current then\n        local position = C_Map.GetPlayerMapPosition(mapID, \"player\")\n        local x, y = position.x*100, position.y*100\n        for quartal, data in ipairs(current) do\n            local inside = isInside(data, x, y)\n            if inside then\n                return quartal\n            end\n        end\n    end\nend\n\naura_env.GetSpoilsLocation = function()\n    local mapID = C_Map.GetBestMapForUnit(\"player\")\n    local current = aura_env.spoils[mapID]\n    if current then\n        local position = C_Map.GetPlayerMapPosition(mapID, \"player\")\n        local x, y = position.x*100, position.y*100\n        local inside = isInside(current, x, y)\n        return inside\n    end\nend\n\n--https://www.wowhead.com/object=341367/odd-crystal\nlocal locale = GetLocale()\nlocal localization = {\n    [\"ruRU\"] = \"Странный кристалл\",\n    [\"enUS\"] = \"Odd Crystal\",\n    [\"frFR\"] = \"Cristal étrange\",\n    [\"deDE\"] = \"Seltsamer Kristall\",\n    [\"koKR\"] = \"기이한 수정\",\n    [\"zhCN\"] = \"怪异水晶\",\n    [\"zhTW\"] = \"奇怪的水晶\",\n    [\"esES\"] = \"Cristal extraño\",\n    [\"esMX\"] = \"Cristal extraño\",\n    [\"ptBR\"] = \"Cristal Estranho\",\n    [\"itIT\"] = \"Cristallo Strano\",\n}\n\naura_env.locale = localization[locale]",
["do_custom"] = true,
},
