["events"] = "TRIGGER:2:3 ENTANGLING_RETRIGGER",
["custom"] = "function(s, event, triggerNum, triggerStates)\n    local timeNow = GetTime()\n    if event == \"TRIGGER\" then\n        if triggerNum == 3 and WeakAuras.GetActiveTriggers(aura_env.id)[2] then\n            if aura_env.timer and not aura_env.timer:IsCancelled() then\n                aura_env.timer:Cancel()\n            end\n            s[\"\"] = {\n                show = true,\n                changed = true,\n                expirationTime = 59 + timeNow,\n                progressType = \"timed\",\n                duration = 59,\n                autoHide = true,\n            }\n            aura_env.timer = C_Timer.NewTimer(59.1, function() WeakAuras.ScanEvents(\"ENTANGLING_RETRIGGER\") end)\n            return true\n            \n        elseif triggerNum == 2 then\n            if not next(triggerStates) then\n                if aura_env.timer and not aura_env.timer:IsCancelled() then\n                    aura_env.timer:Cancel()\n                end\n                for _, state in pairs(s) do\n                    state.show = false\n                    state.changed = true\n                end\n                return true\n            end\n        end\n        \n    elseif event ==\"ENTANGLING_RETRIGGER\" and WeakAuras.GetActiveTriggers(aura_env.id)[2] and not s[\"\"] then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            expirationTime = 59 + timeNow,\n            progressType = \"timed\",\n            duration = 59,\n        }\n        return true\n    end\nend",
