["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local unit, _, spellID = ...\n        if spellID == 374365 then\n            aura_env.remainder = nil\n            local _, _, stacks = WA_GetUnitBuff(unit, 374410)\n            if stacks then\n                local duration = stacks * 5\n                aura_env.remainder = duration % 4\n                local remaining = (aura_env.remainder ~= 0 and math.floor(duration/4) + 1) or duration/4\n                allstates[\"mutation\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 4,\n                    expirationTime = 4 + GetTime(),\n                    remaining = remaining,\n                    autoHide = true,\n                }\n                PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..remaining..\".ogg\", \"MASTER\")\n                C_Timer.After(4, function() WeakAuras.ScanEvents(\"CAUSESE_MUTATION\", remaining-1) end)\n                return true\n            end\n        end\n    elseif event == \"CAUSESE_MUTATION\" and ... then\n        local remaining = ...\n        local duration = (remaining == 1 and aura_env.remainder ~= 0 and aura_env.remainder) or 4\n        if remaining > 1 then\n            C_Timer.After(4, function() WeakAuras.ScanEvents(\"CAUSESE_MUTATION\", remaining-1) end)\n        end\n        if WeakAuras.GetActiveTriggers(aura_env.id)[2] then\n            PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..remaining..\".ogg\", \"MASTER\")\n        end\n        allstates[\"mutation\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            remaining = remaining,\n            autoHide = true,\n        }\n        return true\n    end\nend",
