["do_message"] = false,
},
["init"] = {
["custom"] = "aura_env.db = { }\n\n-- transliteration\naura_env.langDB = {\n    [\"enUS\"] = \"Great Vault\",\n    [\"koKR\"] = \"위대한 금고\",\n    [\"zhCN\"] = \"宏伟宝库\",\n    [\"zhTW\"] = \"寶庫\"\n}",
