["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["events"] = "START, WEEKLY_REWARDS_ITEM_CHANGED, WEEKLY_REWARDS_UPDATE, HDH_VAULT",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(event, ...)\n    -- parse input\n    if event == \"HDH_VAULT\" then\n        local clone, value = ...\n        aura_env.db = { [clone] = value }\n    end\n    \n    -- check if anything is showing\n    local count = 0\n    for _, i in pairs(aura_env.db) do\n        count = i == 1 and count + 1\n    end    \n    if count == 0 then return end\n    \n    if aura_env.config.vault.vaultEnable then return true end\nend",
["customName"] = "function()\n    return aura_env.langDB[GetLocale()] or aura_env.langDB[\"enUS\"]\nend",
