},
["hideReorder"] = false,
["useDesc"] = false,
["nameSource"] = 2,
["width"] = 1,
["useCollapse"] = true,
["collapse"] = false,
["name"] = "Spells",
["key"] = "spells",
["limitType"] = "none",
