["names"] = {
},
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, id)\n    if(aura_env.config.hideIfComplete and C_QuestLog.IsQuestFlaggedCompleted(70893)) then\n        return false\n    end\n    if event == \"DRAGONFLIGHT_EVENT_TRACKER\" and id == aura_env.id\n    or event == \"STATUS\" or event == \"OPTIONS\"\n    then\n        local regionTimers = {\n            [1] = 1670333460, -- NA\n            [2] = 1670702460, -- KR\n            [3] = 1670331660, -- EU\n            [4] = 1670702460, -- TW\n            [5] = 1670677260  -- CN\n        }\n        \n        local firstFeastEpochTime = regionTimers[GetCurrentRegion()]\n        local interval = 5400\n        local duration = 900\n        local time_to_next_feast = interval - ((GetServerTime() - firstFeastEpochTime) % interval)\n        local active = interval - time_to_next_feast < duration\n        local remaining = duration - (interval - time_to_next_feast)\n        \n        allstates[\"\"] = {\n            changed = true,\n            show = aura_env.config.trackFeast,\n            progressType = \"timed\",\n            autoHide = true,\n            duration = active and duration or interval-duration,\n            expirationTime = GetTime() + (active and remaining or time_to_next_feast),\n            icon = 4687629,\n            active = active\n        }\n        \n        return true\n    end\nend\n\n\n\n\n",
