},
["height"] = 18,
["textureSource"] = "LSM",
["sparkBlendMode"] = "ADD",
["useAdjustededMax"] = false,
["source"] = "import",
["xOffset"] = -6.1035158438472e-05,
["information"] = {
["debugLog"] = false,
